const config = (state, methods) => ({
  state,
  methods,
  groupClass: 'pl-3',
  groups: [
    {
      id: 'tools-group-01',
      controls: [
        {
          id: 'scan-button-control',
          type: 'button',
          label:
            state.isScannerActive === true
              ? 'productsView.toolbar.buttons.keyboard'
              : 'productsView.toolbar.buttons.scan',
          icon:
            state.isScannerActive === true
              ? 'mdi-keyboard-outline'
              : 'mdi-barcode-scan',
          color: 'salesPrimary',
          context: true,
          onClick: () => {
            methods.onReset()
            methods.setSelectedSuperCategories([])
            methods.setSearchTerm(null)
            methods.setGroup(state.isScannerActive === true ? 'search' : 'all')
            methods.resetScannerStatus()
          },
        },
      ],
    },
  ],
})

export default config
