const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'productsView.details.productInSaleDialog.title',
    titleBackground: '',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['productsView.details.productInSaleDialog.message'],
    height: 275,
    maxWidth: 500,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: 'ProductInSaleDialog',
        name: 'Close dialog',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.confirmDialog(),
  },
})

export default setConfig
