<template>
  <DialogCard :config="dialogConfig.dialogData">
    <StepperSelector :config="stepperConfig.stepper" />
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'
import { filter, find, isNil, map } from 'ramda'

import { testMode } from '@/config/env'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'
import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import PURCHASE_ORDER_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderItemEvents'
import { storeInventory } from '@/config/storeMapper'
import { promotions } from '@/config/promotions'

import { getObjectCopy, mapStoreObject } from '@/tools/data'
import { formatNumberToDb } from '@/tools/numbersFormat'
import { ticketTools } from '@/tools/purchases'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import productsActions from '@/store/products/actions.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'

import setDialogConfig from '@/components/PurchasesView/ByWeightProductDialog/dialogConfig'
import setStepperConfig from '@/components/PurchasesView/ByWeightProductDialog/stepperConfig'
import DialogCard from '@/components/shared/DialogCard'
import StepperSelector from '@/components/PurchasesView/ByWeightProductDialog/ByWeightProductSector'

export default {
  name: 'ByWeightProductDialog',
  components: { DialogCard, StepperSelector },
  data() {
    return {
      formPayload: {},
      newByWeightProducts: [],
      isAcceptButtonDisabled: true,
      productError: false,
    }
  },
  byWeightProducts: [],
  computed: {
    ...mapState('purchasesView', [
      'byWeightProductDialog',
      'selectedByWeightCategory',
      'selectedPurchase',
      'selectedProduct',
    ]),
    ...mapState('products', {
      products: state => state.data.products,
    }),
    ...mapState('vendorsView', ['selectedVendor']),
    dialogConfig() {
      return setDialogConfig(
        {
          dialog: {
            isOpen: this.byWeightProductDialog.isOpen,
            isAcceptButtonDisabled: this.isAcceptButtonDisabled,
          },
          selectedByWeightCategory: this.selectedByWeightCategory,
          products: this.products,
        },
        {
          dialog: {
            onCloseDialog: this.onCloseDialog,
            onSubmitForm: this.onSubmitForm,
          },
          setGroupFilter: this[purchasesViewActions.setGroupFilter],
          track: this.$track,
        }
      )
    },
    stepperConfig() {
      return setStepperConfig(
        {
          selectedByWeightCategory: this.selectedByWeightCategory,
          products: this.products,
          product: !isNil(this.selectedProduct)
            ? this.selectedProduct.product
            : null,
          productError: this.productError,
        },
        {
          products: {
            getProductByUpc: this.getProductByUpc,
          },
          dialog: {
            onSubmitForm: this.onSubmitForm,
          },
        }
      )
    },
  },
  methods: {
    ...mapActions('purchasesView', [
      purchasesViewActions.toggleByWeightProductDialogStatus,
      purchasesViewActions.setGroupFilter,
      purchasesViewActions.setSearchTermFilter,
      purchasesViewActions.addProductToPurchase,
      purchasesViewActions.setSelectedProduct,
    ]),
    ...mapActions('products', [
      productsActions.addProductFromMLP,
      productsActions.setProductsState,
      productsActions.setProductsOrSuperCategoriesFetching,
    ]),
    onCloseDialog() {
      this[purchasesViewActions.toggleByWeightProductDialogStatus]()
      this.addNewProductsToStore()
    },
    onSubmitForm() {
      if (this.isAcceptButtonDisabled === true) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'ByWeightProductDialog',
        name: 'Submit',
      })
      this[purchasesViewActions.setGroupFilter](this.defaultProductsFilter)
      this[purchasesViewActions.toggleByWeightProductDialogStatus]()
      this.addToPurchase(this.formPayload)
      this.checkIfCostChange(this.formPayload)
    },
    checkIfCostChange(item) {
      if (item.product.isPriceChanged === 0) {
        rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
          event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
          data: {
            productToUpdated: {
              id: item.product.id,
              data: mapStoreObject(
                { cost: formatNumberToDb(item.inputs.cost) },
                storeInventory,
                true
              ),
            },
          },
        })
      }
    },
    addToPurchase(item) {
      if (this.isAcceptButtonDisabled) return
      const { product } = item
      const productExist = find(itemProduct => itemProduct.upc == product.upc)(
        this.selectedPurchase.items
      )
      if (!isNil(productExist)) {
        this.$track({
          type: 'system',
          action: 'submit_product',
          category: 'Purchases',
          screen: 'ByWeightProductDialog',
          name: 'Edit product from ticket',
        })
        this.editProductFromTicket()
        return
      }
      this.$track({
        type: 'system',
        action: 'submit_product',
        category: 'Purchases',
        screen: 'ByWeightProductDialog',
        name: 'Add product',
      })
      this.addNewProductToTicket()
    },
    editProductFromTicket() {
      const updatedTicketItem = ticketTools.buildTicketProductUpdateByType(
        this.formPayload,
        this.selectedPurchase._id
      )
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event: PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.update.name,
        data: {
          purchaseOrderId: this.selectedPurchase._id,
          purchaseItemUpdated: updatedTicketItem,
        },
      })
      this[purchasesViewActions.setSelectedProduct](null)
    },
    addNewProductToTicket() {
      const newTicketItem = ticketTools.buildTicketItem(
        this.formPayload,
        this.selectedPurchase._id
      )
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event: PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.add.name,
        data: {
          purchaseItem: newTicketItem,
        },
      })
      this[purchasesViewActions.setSelectedProduct](null)
    },
    getProductByUpc(upc) {
      const inventorySearchResult = this.byWeightProducts.find(
        item => item.upc === upc
      )
      if (inventorySearchResult) {
        this[purchasesViewActions.setSelectedProduct]({
          product: {
            ...inventorySearchResult,
            promotionTypeId: promotions.NONE,
            promotionExtra: 0,
            discountPercent: 0,
            discountAmount: 0,
            costWithoutTaxAndPromotion: inventorySearchResult.cost,
          },
        })
        rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
          event:
            PURCHASE_ORDER_ITEM_DB_API_EVENTS.events
              .getLastPurchaseOrderItemCost.name,
          data: {
            productId: inventorySearchResult.id,
            vendorId: this.selectedVendor.id,
            showProductTriangulationDialog: false,
          },
        })
        return
      }
      this[productsActions.setProductsOrSuperCategoriesFetching](true)
      rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
        event: ADD_PRODUCT_EVENTS.events.addProductFromMLP.name,
        data: {
          item: { property: 'upc_code', value: upc, limit: 1 },
          fromByWeightDialog: true,
        },
      })
    },
    getByWeightStoredProducts() {
      return filter(item => item.isGramaje === 1, this.products)
    },
    addNewProductsToStore() {
      map(
        product => this[productsActions.setProductsState](product),
        this.newByWeightProducts
      )
    },
    addProductFromMLPListener(event, payload) {
      const events = ADD_PRODUCT_EVENTS.events
      const replies = {
        [events.addProductFromMLP.replies.successFromByWeightDialog]: () =>
          this.onProductAddedFromMLP(payload.data),
        [events.addProductFromMLP.replies.errorFromByWeightDialog]: () => {
          this[productsActions.setProductsOrSuperCategoriesFetching](false)
          this.productError = true
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    onProductAddedFromMLP(data) {
      this.productError = false
      let { newProduct } = data
      newProduct.promotionTypeId = promotions.NONE
      newProduct.promotionExtra = 0
      newProduct.discountPercent = 0
      newProduct.discountAmount = 0
      newProduct.costWithoutTaxAndPromotion = newProduct.cost
      this[productsActions.addProductFromMLP]({
        newProduct: newProduct,
        currentView: 'purchasesView',
      })
      notificationsService.showInfo(
        'productsView.listView.messages.newProductAdded',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
      this[productsActions.setProductsOrSuperCategoriesFetching](false)
      this.byWeightProducts.push(newProduct)
      this.newByWeightProducts.push(newProduct)
      this[purchasesViewActions.setSelectedProduct]({ product: newProduct })
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductFromMLPListener
    )
  },
  mounted() {
    this.$barcodeScanner.destroy()
    this.byWeightProducts = getObjectCopy(this.getByWeightStoredProducts())
    this.$root.$on('by-weight-selected-product', payload => {
      const { isValid } = payload
      if (isValid === false) {
        this.isAcceptButtonDisabled = true
        return
      }
      this.formPayload = payload
      this.isAcceptButtonDisabled = false
    })
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
    rendererEventsService.removeListener(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductFromMLPListener
    )
  },
}
</script>
