import light from '@/themes/light'
import dark from '@/themes/dark'

export const config = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: () => {},
    onDblClick: () => {},
  },
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  hideTop: true,
  page: 1,
  rowsPerPage: 7,
  rowOffsetHeight: state.rowHeight,
  headers: [
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.productsView.details.tabs.history.date'
      ),
      align: 'center',
      value: 'creationDate',
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.productsView.details.tabs.history.data'
      ),
      align: 'center',
      value: 'operationType',
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.productsView.details.tabs.history.previousStock'
      ),
      align: 'center',
      value: 'stockBefore',
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.productsView.details.tabs.history.quantity'
      ),
      align: 'center',
      value: 'stockAfter',
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.productsView.details.tabs.history.actualStock'
      ),
      align: 'center',
      value: 'modificationQuantity',
    },
  ],
  sortBy: 'creationDate',
  sortDesc: true,
})

export default config
