<template>
  <div>
    <div>
      <FormattedText :value="productName" type="text-h6" />
    </div>
    <div class="d-flex align-center pb-4">
      <div class="d-flex align-center pt-2" v-if="product.isGramaje === 0">
        <v-icon color="salesPrimary"> mdi-barcode-scan </v-icon>
        <FormattedText
          :value="product.upc"
          type="text-subtitle-1"
          class="px-2"
        />
      </div>
      <v-spacer />
      <div class="show-dbprice" v-if="showDBCost && product.isGeneric !== 1">
        <v-btn
          @click="setCostFromDB"
          depressed
          class="d-flex align-center database-price"
        >
          <FormattedText
            intl
            class="text-subtitle-1"
            value="salesView.form.storeInventory"
          />
          <div class="pl-2 text-subtitle-1">
            <span class="font-weight-bold">{{ dbCost }}</span>
          </div>
        </v-btn>
      </div>
      <div class="reset-dbprice" v-if="alertConfig.type === 'error'">
        <v-btn
          @click="resetForm"
          depressed
          class="d-flex align-center database-price"
        >
          <FormattedText
            intl
            class="text-subtitle-1"
            value="salesView.form.reset"
          />
        </v-btn>
      </div>
    </div>
    <v-row>
      <v-col cols="3" v-if="product.isGeneric !== 1">
        <v-text-field
          id="quantity-input"
          ref="quantity"
          v-model.number="inputs.quantity"
          class="custom-text-field-large"
          filled
          rounded
          color="primary"
          :label="
            getTranslatedText(
              product.isGramaje === 1
                ? 'salesView.ticket.grams'
                : product.factor > 1
                ? 'salesView.ticket.packages'
                : 'salesView.ticket.pieces'
            )
          "
          :error-messages="onValidateFields('quantity')"
          @focus="currentFocus = 'quantity'"
          @blur="$v.inputs.quantity.$touch()"
          @input="onQuantityInput"
          @keydown.enter="onEnterEvent"
        />
      </v-col>
      <v-col :cols="product.isGeneric === 1 ? 4 : 3">
        <MoneyTextField
          ref="cost"
          v-model.number="inputs.cost"
          :config="{
            fieldName: 'cost',
            label: getCostLabel(),
            color: 'primary',
            filled: true,
            rounded: true,
            class: 'custom-text-field-large',
            errorMessage: onValidateFields,
          }"
          :options="moneyInputsConfig"
          @focus="currentFocus = 'cost'"
          @input="onCostInput"
          @blur="$v.inputs.cost.$touch()"
          @enter="onEnterEvent"
          v-on:moneyTextField-is-mounted="getInitialFocus()"
        />
      </v-col>
      <v-col :cols="product.isGeneric === 1 ? 4 : 3">
        <v-select
          v-model="inputs.tax"
          ref="tax"
          :items="taxes"
          item-text="percentage"
          item-value="value"
          label="IVA"
          filled
          rounded
          color="primary"
          background-color="cardBackgroundSecondary"
          :error-messages="onValidateFields('tax')"
          @focus="currentFocus = 'tax'"
          @change="onTaxInput"
          @blur="$v.inputs.tax.$touch()"
        />
      </v-col>
      <v-col :cols="product.isGeneric === 1 ? 4 : 3" class="line-container">
        <MoneyTextField
          ref="total"
          v-model.number="inputs.total"
          :config="{
            fieldName: 'total',
            color: 'white',
            filled: true,
            rounded: true,
            class: totalFieldStyles
              ? 'product-promotion total-text-field'
              : 'total-text-field',
            suffix: 'Total',
            backgroundColor: 'primary',
            errorMessage: onValidateFields,
            readonly: !(product.isGramaje === 1),
          }"
          :options="moneyInputsConfig"
          @focus="currentFocus = 'total'"
          @input="onTotalInput"
          @blur="onTotalInputBlur"
          @enter="onEnterEvent"
        />
      </v-col>
    </v-row>
  </div>
</template>

<script>
import { isNil } from 'ramda'
import { mapGetters, mapState } from 'vuex'

import { promotions } from '@/config/promotions'
import { testMode } from '@/config/env'

import WEIGHT_SCALE_EVENTS from '@/config/events/weightScaleEvents'

import {
  decimal,
  formatNumberFromDb,
  formatNumberFromDbToCurrency,
  formatNumberToDb,
  moneyTextFieldCountryConfig,
} from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import FormattedText from '@/components/shared/FormattedText'
import MoneyTextField from '@/components/shared/MoneyTextField'

import productTriangulation from '@/mixins/purchases/productTriangulation'

export default {
  name: 'ProductForm',
  components: { FormattedText, MoneyTextField },
  props: {
    product: {
      type: Object,
      required: true,
    },
    productType: {
      type: String,
      required: true,
    },
    onEnterEvent: {
      type: Function,
    },
    inputs: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      currentFocus: '',
      alertConfig: {},
      showDBCost: false,
      productDbCost: null,
      moneyInputsConfig: this.getMoneyInputsConfig(),
    }
  },
  computed: {
    ...mapGetters('account', ['getCountry']),
    ...mapState('purchasesView', ['tourEnabled']),
    productName() {
      return this.getTranslatedText(
        'purchaseView.productTriangulationDialog.productForm.title',
        [this.product.name]
      )
    },
    dbCost() {
      return formatNumberFromDbToCurrency(this.productDbCost)
    },
    taxes() {
      return this.getCountry.taxes
    },
    checkIfShowDbCost() {
      return formatNumberToDb(this.inputs.cost) !== this.productDbCost
    },
    totalFieldStyles() {
      return [
        promotions.PURCHASE_ITEM_FREE_PRODUCT,
        promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT,
      ].includes(this.inputs.promotionTypeId)
    },
  },
  methods: {
    getTranslatedText,
    getMoneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
    getInitialFocus() {
      if (testMode) return
      const costInput = this.$refs.cost.$el.querySelector('input')
      setTimeout(() => {
        costInput.select()
      }, 500)
      if (this.tourEnabled) {
        setTimeout(() => {
          costInput.select()
        }, 800)
      }
    },
    setCostFromDB() {
      this.inputs.cost = formatNumberFromDb(this.productDbCost)
      this.onCostInput()
      this.showDBCost = false
      this.getInitialFocus()
    },
    resetForm() {
      if (isNil(this.product.uniqueId)) {
        this.inputs.quantity = this.product.isGramaje === 1 ? 100 : 1
      } else {
        this.inputs.quantity =
          this.product.quantity > 0 ? this.product.quantity : 1
      }
      this.inputs.cost = formatNumberFromDb(this.productDbCost)
      this.initTax()
      this.initTotal()
      this.getInitialFocus()
      this.showDBCost = false
      this.alertConfig = {}
    },
    onQuantityInput() {
      if (this.currentFocus !== 'quantity') return
      rendererEventsService.send(WEIGHT_SCALE_EVENTS.channel, {
        event: WEIGHT_SCALE_EVENTS.events.stop.name,
      })
      this.$v.inputs.quantity.$touch()
      this.showDBCost = this.checkIfShowDbCost
      this.inputs.total = decimal(
        this.product.isGramaje === 1
          ? ((this.inputs.quantity || 0) / 1000) *
              this.inputs.cost *
              this.applyTax()
          : (this.inputs.quantity || 0) * this.inputs.cost * this.applyTax(),
        4
      )
    },
    onCostInput() {
      if (this.currentFocus !== 'cost') return
      this.$v.inputs.cost.$touch()
      this.showDBCost = this.checkIfShowDbCost
      this.inputs.total = decimal(
        this.product.isGramaje === 1
          ? ((this.inputs.quantity || 0) / 1000) *
              this.inputs.cost *
              this.applyTax()
          : (this.inputs.cost || 0) * this.inputs.quantity * this.applyTax(),
        4
      )
    },
    onTaxInput() {
      if (this.currentFocus !== 'tax') return
      this.$v.inputs.tax.$touch()
      this.showDBCost = this.checkIfShowDbCost
      this.inputs.total = decimal(
        this.product.isGramaje === 1
          ? ((this.inputs.quantity || 0) / 1000) *
              this.inputs.cost *
              this.applyTax()
          : (this.inputs.cost || 0) * this.inputs.quantity * this.applyTax(),
        4
      )
    },
    onTotalInput() {
      if (this.currentFocus !== 'total' || this.product.isGramaje !== 1) return
      rendererEventsService.send(WEIGHT_SCALE_EVENTS.channel, {
        event: WEIGHT_SCALE_EVENTS.events.stop.name,
      })
      this.$v.inputs.total.$touch()
      this.showDBCost = this.checkIfShowDbCost
      this.inputs.quantity = Math.floor(
        decimal(
          (this.inputs.total / (this.inputs.cost * this.applyTax())) * 1000,
          4
        )
      )
    },
    onTotalInputBlur() {
      this.getInitialFocus()
      this.$v.inputs.total.$touch()
    },
    getCostLabel() {
      if (this.product.isGeneric === 1) {
        return this.getTranslatedText('shared.cost')
      }
      switch (this.productType) {
        case 'isPieceProduct':
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costPiece'
          )
        case 'isByWeightProduct':
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costUnit'
          )
        case 'isOpenProductPackage':
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costPackage'
          )
        case 'isOpenProductPiece':
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costPiece'
          )
      }
    },
    setFormValidators() {
      const validations = {
        inputs: {
          quantity: this.setDefaultValidators(100000),
          cost: this.setMoneyValidator(1000000, 4),
          tax: this.setRequiredValidator(),
          total: this.setMoneyValidator(1000000, 4),
        },
      }
      return validations
    },
    weightScaleListener(event, payload) {
      const replies = {
        [WEIGHT_SCALE_EVENTS.events.getWeight.replies.success]: () => {
          this.inputs.quantity = payload.data.weight
          this.showDBCost = this.checkIfShowDbCost
          this.inputs.total = decimal(
            ((this.inputs.quantity || 0) / 1000) *
              this.inputs.cost *
              this.applyTax(),
            4
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  mixins: [productTriangulation],
  validations() {
    return this.setFormValidators()
  },
  beforeMount() {
    if (this.product.isGramaje === 1) {
      rendererEventsService.send(WEIGHT_SCALE_EVENTS.channel, {
        event: WEIGHT_SCALE_EVENTS.events.getWeight.name,
      })
    }
    rendererEventsService.subscribe(
      WEIGHT_SCALE_EVENTS.replyChannel,
      this.weightScaleListener
    )
  },
  mounted() {
    this.productDbCost = this.product.costWithoutTaxAndPromotion
    this.showDBCost = this.checkIfShowDbCost
  },
  beforeDestroy() {
    rendererEventsService.send(WEIGHT_SCALE_EVENTS.channel, {
      event: WEIGHT_SCALE_EVENTS.events.stop.name,
    })
    rendererEventsService.removeListener(
      WEIGHT_SCALE_EVENTS.replyChannel,
      this.weightScaleListener
    )
  },
}
</script>

<style lang="scss" scoped>
.price {
  max-width: 214px;
}
.database-price {
  color: var(--v-salesPrimary-base);
}
</style>
