<template>
  <tr :style="`height:${rowHeight}px`" class="stock-modification__row">
    <td class="text-center">
      <FormattedText
        type="body"
        :value="getTime(stockModification.creationDate)"
      />
      <FormattedText
        type="body"
        :value="getDate(stockModification.creationDate)"
      />
    </td>
    <td>
      <div class="text-center">
        <FormattedText
          type="body"
          intl
          :value="stockModificationTypeText"
          className="font-weight-bold"
        />
        <FormattedText type="body" :value="stockModification.username" />
      </div>
    </td>
    <td class="text-center">
      {{
        getFormatQuantity(
          stockModification.stockBefore,
          stockModification.isGramajeBefore
        )
      }}
    </td>
    <td
      class="text-center"
      :class="getColorClass(stockModification.operationType)"
    >
      {{ formatModificationQuantity }}
    </td>
    <td class="text-center">
      {{
        getFormatQuantity(
          stockModification.stockAfter,
          stockModification.isGramajeAfter
        )
      }}
    </td>
    <v-btn
      v-if="enableDeleteOperation"
      class="stock-modification__delete"
      color="error"
      fab
      depressed
      x-small
      absolute
      right
      @click="deleteOperation()"
    >
      <v-icon>mdi-delete</v-icon>
    </v-btn>
  </tr>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { stockModificationType } from '@/config/stockModificationsVariables'

import { formatDate, getDateWithFormat } from '@/tools/dates'
import { getTranslatedText } from '@/tools/data'

import productsViewActions from '@/store/productsView/action.types'

import FormattedText from '@/components/shared/FormattedText'
import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'

export default {
  name: 'DetailStockModification',
  components: {
    FormattedText,
  },
  props: {
    stockModification: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      rowHeight: 65,
    }
  },
  computed: {
    ...mapState('usersView', ['selectedUser']),
    ...getSelectedProductByRoute(),
    stockModificationTypeText() {
      switch (this.stockModification.operationType) {
        case stockModificationType.SALE:
          return 'stockModificationTypes.sale'
        case stockModificationType.SALE_RETURN:
          return 'stockModificationTypes.saleReturn'
        case stockModificationType.PURCHASE:
          return 'stockModificationTypes.purchase'
        case stockModificationType.PURCHASE_RETURN:
          return 'stockModificationTypes.purchaseReturn'
        case stockModificationType.ADJUSTEMENT:
          return 'stockModificationTypes.adjustement'
        case stockModificationType.RESET:
          return 'stockModificationTypes.reset'
        case stockModificationType.SELF_CONSUMPTION:
          return 'stockModificationTypes.selfConsumption'
        case stockModificationType.WASTED_PRODUCTS:
          return 'stockModificationTypes.wastedProducts'
        case stockModificationType.PURCHASE_RETURN_CANCELLED:
          return 'stockModificationTypes.purchaseReturnCancelled'
        case stockModificationType.UNIT_MEASURE_CHANGE:
          return 'stockModificationTypes.unitMeasureChange'
        default:
          return 'stockModificationTypes.unknown'
      }
    },
    formatModificationQuantity() {
      switch (this.stockModification.operationType) {
        case stockModificationType.SALE:
        case stockModificationType.PURCHASE_RETURN:
        case stockModificationType.SELF_CONSUMPTION:
        case stockModificationType.WASTED_PRODUCTS:
          return `- ${this.getFormatQuantity(
            this.stockModification.modificationQuantity,
            this.stockModification.isGramajeAfter
          )}`
        case stockModificationType.SALE_RETURN:
        case stockModificationType.PURCHASE:
        case stockModificationType.PURCHASE_RETURN_CANCELLED:
          return `+ ${this.getFormatQuantity(
            this.stockModification.modificationQuantity,
            this.stockModification.isGramajeAfter
          )}`
        case stockModificationType.UNIT_MEASURE_CHANGE:
        case stockModificationType.ADJUSTEMENT:
        case stockModificationType.RESET:
          return '-'
        default:
          return ''
      }
    },
    enableDeleteOperation() {
      return (
        this.stockModification.operationType ===
          stockModificationType.WASTED_PRODUCTS &&
        this.selectedUser.inventoryPermission === 0
      )
    },
  },
  methods: {
    ...mapActions('productsView', [
      productsViewActions.setDeleteStockModificationOperationDialog,
    ]),
    getTranslatedText,
    getTime(date) {
      return getDateWithFormat(date, 'HH:mm')
    },
    getDate(date) {
      return formatDate(date)
    },
    getColorClass(operationType) {
      switch (operationType) {
        case stockModificationType.SALE:
        case stockModificationType.PURCHASE_RETURN:
        case stockModificationType.SELF_CONSUMPTION:
        case stockModificationType.WASTED_PRODUCTS:
          return 'negative'
        case stockModificationType.SALE_RETURN:
        case stockModificationType.PURCHASE:
        case stockModificationType.PURCHASE_RETURN_CANCELLED:
          return 'positive'
        default:
          return ''
      }
    },
    getFormatQuantity(stock, isGramaje) {
      const factor = this.selectedProduct.factor
      if (factor > 1) {
        const pack =
          factor === 0 ? Math.floor(stock) | 0 : Math.floor(stock / factor) | 0
        const pieces = stock % factor
        return `${pack} paq ${pieces} pzs`
      } else if (isGramaje === 1) {
        return `${stock} g`
      }
      return `${stock} uds`
    },
    deleteOperation() {
      this[productsViewActions.setDeleteStockModificationOperationDialog]({
        isOpen: true,
        operation: this.stockModification,
      })
    },
  },
}
</script>

<style scoped lang="scss">
tr {
  td {
    max-width: 102px;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}
.negative {
  color: var(--v-error-darken2);
}
.positive {
  color: var(--v-primary-darken2);
}
.theme--dark {
  .negative {
    color: var(--v-error-base);
  }
  .positive {
    color: var(--v-primary-base);
  }
}
.stock-modification {
  &__row {
    &:hover {
      :deep(.stock-modification__delete) {
        display: block;
      }
    }
  }
  &__delete {
    display: none;
    right: 5px;
    margin-top: 15px;
  }
}
</style>
