const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.dialog.isOpen,
    icon: 'mdi-weight',
    title:
      state.isEditForm === true
        ? 'salesView.productTriangulationDialog.editTitle'
        : 'salesView.productTriangulationDialog.addTitle',
    messages: '',
    extraValuesMessages: '',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    acceptButtonText: 'salesView.productTriangulationDialog.acceptButtonText',
    isAcceptButtonDisabled: state.dialog.isAcceptButtonDisabled,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    maxWidth: state.isGenericProduct ? 758 : 1000,
    height: state.dialog.dialogHeight,
    ref: 'purchase-product-triangulation-dialog',
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'ProductTriangulationDialog',
        name: 'Cancel',
      })
      methods.dialog.onCloseDialog()
    },
    onClickAccept: () => methods.dialog.onSubmitForm(),
  },
})

export default setConfig
