const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.dialog.isOpen,
    icon: '$vuetify.icons.values.returnProduct',
    title: 'purchaseView.returnProductDialog.title',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    acceptButtonText: 'salesView.productTriangulationDialog.acceptButtonText',
    isAcceptButtonDisabled: state.dialog.isAcceptButtonDisabled,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    maxWidth: 1000,
    hidden: state.dialog.hidden,
    height: state.dialog.dialogHeight,
    ref: 'purchase-return-product-dialog',
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'ReturnProductDialog',
        name: 'Cancel',
      })
      methods.dialog.onCloseDialog()
    },
    onClickAccept: () => methods.dialog.onSubmitForm(),
  },
})

export default setConfig
