export default {
  channel: 'weight-scale',
  replyChannel: 'weight-scale-reply',
  events: {
    getWeight: {
      name: 'weight-scale-get-weight',
      replies: {
        success: 'weight-scale-get-weight-success',
        error: 'weight-scale-get-weight-error',
      },
    },
    stop: {
      name: 'weight-scale-stop',
      replies: {
        success: 'weight-scale-stop-success',
        error: 'weight-scale-stop-error',
      },
    },
    connection: {
      name: 'weight-scale-stop',
      replies: {
        success: 'weight-scale-connection-success',
        error: 'weight-scale-connection-error',
      },
    },
  },
}
