<template>
  <div>
    <v-row>
      <v-col cols="12">
        <FormattedText
          intl
          value="purchaseView.returnProductDialog.returnTypeForm.title"
          type="text-h6"
        />
      </v-col>
      <v-row class="px-3">
        <v-col cols="3">
          <v-select
            ref="returnTypeSelect"
            v-model="inputs.returnType"
            :disabled="!isProductSelected"
            :items="returnProductLiterals"
            :item-text="item => getTranslatedText(item.text)"
            item-value="value"
            background-color="cardBackgroundSecondary"
            filled
            rounded
            @change="handleSelectChange"
          />
        </v-col>
        <v-col cols="6" v-if="inputs.returnType === returnTypes.DISCOUNT">
          <DiscountForm :inputs="inputs" />
        </v-col>
      </v-row>
    </v-row>
    <div v-if="inputs.returnType === returnTypes.CHANGE_PRODUCT">
      <ChangeProductForm :inputs="inputs" />
    </div>
  </div>
</template>

<script>
import { isNil } from 'ramda'

import { returnProductLiterals, returnTypes } from '@/config/returnProductTypes'

import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'
import DiscountForm from '@/components/PurchasesView/ReturnProductDialog/ReturnProductForm/ReturnTypeForm/DiscountForm'
import ChangeProductForm from '@/components/PurchasesView/ReturnProductDialog/ReturnProductForm/ReturnTypeForm/ChangeProductForm'

export default {
  name: 'ReturnTypeForm',
  components: { FormattedText, DiscountForm, ChangeProductForm },
  props: {
    inputs: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      returnTypes,
      returnProductLiterals,
    }
  },
  computed: {
    isProductSelected() {
      return !isNil(this.inputs.productToReturn)
    },
  },
  methods: {
    getTranslatedText,
    handleSelectChange() {
      this.$refs.returnTypeSelect.blur()
    },
  },
}
</script>
