<template>
  <v-card flat color="cardBackgroundPrimary">
    <div class="pt-6 d-flex flex-column">
      <v-alert
        border="left"
        dense
        icon="mdi-information-outline"
        text
        type="info"
      >
        <FormattedText
          intl
          type="body"
          value="productsView.details.tabs.sales.info"
        />
      </v-alert>
      <StockSoldDetails :report="productSalesReport" />
      <ProfitsDetails :report="productSalesReport" class="mt-3" />
    </div>
  </v-card>
</template>

<script>
import SALES_ITEMS_DB_API_EVENTS from '@/config/events/databaseAPI/salesItemsEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'
import FormattedText from '@/components/shared/FormattedText'
import StockSoldDetails from '@/components/ProductDetail/SalesTab/StockSoldDetails'
import ProfitsDetails from '@/components/ProductDetail/SalesTab/ProfitsDetails'

export default {
  name: 'ProductSalesTab',
  components: { FormattedText, StockSoldDetails, ProfitsDetails },
  data() {
    return {
      productSalesReport: {
        quantity: 0,
        quantityPackage: 0,
        quantityUnit: 0,
        quantityWeight: 0,
        income: 0,
        profit: 0,
      },
    }
  },
  computed: {
    ...getSelectedProductByRoute(),
  },
  methods: {
    loadSalesReport() {
      rendererEventsService.send(SALES_ITEMS_DB_API_EVENTS.channel, {
        event: SALES_ITEMS_DB_API_EVENTS.events.getSalesReport.name,
        data: { product: this.selectedProduct },
      })
    },
    async salesItemsListener(event, payload) {
      const salesItemsEvents = SALES_ITEMS_DB_API_EVENTS.events
      const replies = {
        [salesItemsEvents.getSalesReport.replies.success]: () => {
          this.productSalesReport = payload.data.productSalesReport
        },
        [salesItemsEvents.getSalesReport.replies.error]: () => {
          notificationsService.showError(
            payload.data.errorMsg,
            this.$vuetify.lang
          )
          this.productSalesReport = {
            quantity: 0,
            quantityPackage: 0,
            quantityUnit: 0,
            quantityWeight: 0,
            income: 0,
            profit: 0,
          }
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      SALES_ITEMS_DB_API_EVENTS.replyChannel,
      this.salesItemsListener
    )
  },
  mounted() {
    this.loadSalesReport()
    this.$root.$on('navigateToProductWasDone', this.loadSalesReport)
  },
  beforeDestroy() {
    this.$root.$off('navigateToProductWasDone', this.loadSalesReport)
    rendererEventsService.removeListener(
      SALES_ITEMS_DB_API_EVENTS.replyChannel,
      this.salesItemsListener
    )
  },
}
</script>
