import ProductCard from '@/components/shared/ProductCard'
import ProductImageCard from '@/components/shared/ProductImageCard'

import light from '@/themes/light'
import dark from '@/themes/dark'

export const setConfig = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: item => methods.onCLickCard(item),
    onDblClick: item => {
      if (item.id < 0 || item.isStoreInventory === 0 || item.airTime === 1) {
        methods.onCLickCard(item)
        return
      }
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'ProductCard',
        name: 'Open product details',
      })
      methods.closeProductTriangulation()
      methods.setSelectedProduct(item)
      methods.toggleDetailPanel()
    },
  },
  containerRef: 'purchase-view__products-list',
  title: 'productsView.listView.title',
  icon: 'mdi-fridge-outline',
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  groups: [
    {
      id: 'all',
      icon: 'mdi-view-module',
      title: 'productsView.toolbar.buttons.all',
    },
    {
      id: 'byWeight',
      icon: 'mdi-weight',
      title: 'productsView.toolbar.buttons.byWeight',
    },
    {
      id: 'favorites',
      icon: 'mdi-cards-heart',
      title: 'productsView.toolbar.buttons.favorites',
    },
    {
      id: 'vendor',
      icon: 'mdi-truck',
      title: 'productsView.toolbar.buttons.vendor',
    },
    {
      id: 'search',
      icon: 'mdi-magnify',
      title: 'productsView.toolbar.buttons.search',
    },
    {
      id: 'superCategories',
      icon: 'mdi-tag-outline',
      title: 'productsView.toolbar.buttons.superCategories',
    },
    {
      id: 'scan',
      icon: 'mdi-barcode',
      title: 'productsView.toolbar.buttons.scan',
    },
    {
      id: 'generics',
      icon: 'mdi-calculator',
      title: 'productsView.toolbar.buttons.generics',
    },
  ],
  sortBy: 'name',
  sortDesc: false,
  sort: {
    by: [
      { prop: 'name', text: 'productsView.listView.sortBy.name' },
      { prop: 'price', text: 'productsView.listView.sortBy.price' },
      {
        prop: 'quantity',
        text: 'productsView.listView.sortBy.quantity',
      },
      { prop: 'upc', text: 'productsView.listView.sortBy.upc' },
    ],
    sortDesc: false,
    iconColor: 'accent',
  },
  isDetail: true,
  rowsPerPage: 4,
  page: 1,
  cardComponents: {
    ProductCard: {
      cardOffsetHeight: 122,
      component: ProductCard,
      itemsPerRow: {
        small: 1,
        medium: 2,
        large: 3,
        extraLarge: 3,
      },
      truncate: {
        lg: '50',
        xl: '100',
      },
    },
    ProductImageCard: {
      cardOffsetHeight: 210,
      component: ProductImageCard,
      itemsPerRow: {
        small: 2,
        medium: 3,
        large: 4,
        extraLarge: 6,
      },
      truncate: {
        lg: '50',
        xl: '100',
      },
    },
  },
  noDataMessage: {
    icon: 'mdi-barcode-scan',
    messages: [
      'productsView.listView.noData.firstMessage',
      'productsView.listView.noData.secondMessage',
    ],
  },
})
export default setConfig
