<template>
  <div>
    <DialogCard :config="config.dialogData">
      <v-alert type="info" text>
        <p class="mb-0 info--text text--darken-1">
          {{ getTranslatedText('productsView.similarProducts.info') }}
        </p>
      </v-alert>
      <ScrollContainer
        v-if="!!similarProductsUpcDialog.product"
        height="auto"
        max-height="385px"
      >
        <template v-for="product in similarProducts">
          <v-card
            v-if="!deletedProducts.includes(product.id)"
            :key="`similar-product-${product.id}`"
            class="mb-2 similar-product"
            color="cardBackgroundSecondary"
            flat
          >
            <v-card-text class="pa-4">
              <div class="d-flex flex-column">
                <div class="d-flex justify-space-between align-start mb-1">
                  <p class="text-h6 mb-0">
                    {{ product.name }} {{ product.alternativeName }}
                  </p>
                  <v-tooltip bottom>
                    <template v-slot:activator="{ on }">
                      <v-btn
                        v-if="
                          deletedProducts.length < similarProducts.length - 1
                        "
                        color="error"
                        text
                        icon
                        v-on="on"
                        class="mt-n1"
                        @click="showDeleteProductConfirmation(product)"
                        v-track:click="{
                          category: $route.name,
                          screen: 'SimilarProductUpcDialog',
                          name: 'Delete product',
                        }"
                      >
                        <v-icon>mdi-delete</v-icon>
                      </v-btn>
                    </template>
                    <span>{{
                      getTranslatedText('productsView.similarProducts.delete')
                    }}</span>
                  </v-tooltip>
                </div>
                <div
                  class="d-flex justify-space-between text-body-1 grey--text"
                >
                  <div class="d-flex align-center">
                    <v-icon class="mr-1" color="grey">
                      {{
                        isSupportedUpcOrEan(product.upc)
                          ? 'mdi-barcode'
                          : 'mdi-barcode-off'
                      }}
                    </v-icon>
                    {{ product.upc }}
                  </div>
                  <div class="d-flex align-center mx-4">
                    <v-icon class="mr-1" color="grey">mdi-basket-fill</v-icon>
                    {{ product.quantity }}
                  </div>
                  <div class="d-flex align-center">
                    <v-icon class="mr-1" color="grey"
                      >$currencyUsdCircle</v-icon
                    >
                    {{ formatNumberFromDbToCurrency(product.price) }}
                  </div>
                </div>
                <div class="d-flex justify-space-between">
                  <p class="mb-0 text-caption text-success">
                    ({{
                      isSupportedUpcOrEan(product.upc)
                        ? getTranslatedText(
                            'productsView.similarProducts.validCode'
                          )
                        : getTranslatedText(
                            'productsView.similarProducts.invalidCode'
                          )
                    }})
                  </p>
                </div>
              </div>
            </v-card-text>
          </v-card>
        </template>
      </ScrollContainer>
    </DialogCard>
    <DeleteProductDialog v-if="deleteProductDialog.isOpen" />
    <ProductInSaleDialog v-if="productInSaleDialog.isOpen" />
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import SYNCHRONIZATION_EVENTS from '@/config/events/synchronization'
import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'

import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import upcTools from '@/tools/upc'
import { getTranslatedText } from '@/tools/data'
import { getActionsTypes, getViewStore } from '@/tools/view'
import { captureException } from '@/tools/exceptions'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import productsViewActions from '@/store/productsView/action.types'

import productsActions from '@/store/products/actions.types'
import salesActions from '@/store/sales/actions.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'

import setConfig from '@/components/ProductsView/ProductsList/SimilarProductsUpc/config'
import DialogCard from '@/components/shared/DialogCard'
import DeleteProductDialog from '@/components/ProductDetail/Footer/DeleteProductDialog'
import ScrollContainer from '@/components/shared/ScrollContainer'
import ProductInSaleDialog from '@/components/ProductDetail/Footer/ProductInSaleDialog'
import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'

export default {
  name: 'SimilarProductsUpc',
  components: {
    ProductInSaleDialog,
    ScrollContainer,
    DeleteProductDialog,
    DialogCard,
  },
  data() {
    return {
      similarProducts: [],
      deletedProducts: [],
    }
  },
  computed: {
    ...getSelectedProductByRoute(),
    ...mapState('products', {
      products: state => state.data.products,
      productsSimilarUpc: state => state.data.productsSimilarUpc,
    }),
    ...mapState('productsView', [
      'similarProductsUpcDialog',
      'deleteProductDialog',
      'productInSaleDialog',
    ]),
    config() {
      return setConfig(
        {
          isOpen:
            this.similarProductsUpcDialog.isOpen &&
            !!this.similarProductsUpcDialog.product,
          similarProductCount: this.similarProducts.length,
        },
        {
          closeDialog: this.closeDialog,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
    isSupportedUpcOrEan: upcTools.isSupportedUpcOrEan,
    ...mapActions({
      toggleDetailDialog(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).toggleDetailDialog
          }`,
          payload
        )
      },
      setSelectedProduct(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).setSelectedProduct
          }`,
          payload
        )
      },
    }),
    ...mapActions('productsView', [
      productsViewActions.setSimilarProductsUpcDialog,
      productsViewActions.setDeleteProductDialogStatus,
      productsViewActions.setProductInSaleDialogStatus,
    ]),
    ...mapActions('products', [productsActions.removeProduct]),
    ...mapActions('sales', [salesActions.removeProductFromAllSales]),
    ...mapActions('purchasesView', [
      purchasesViewActions.removeProductFromPurchase,
      purchasesViewActions.removeReturnProductFromPurchase,
    ]),
    setSimilarProducts() {
      this.similarProducts.push(this.similarProductsUpcDialog.product)
      this.similarProducts.push(
        ...this.products.filter(product =>
          this.productsSimilarUpc[
            this.similarProductsUpcDialog.product.id
          ].includes(product.id)
        )
      )
    },
    showDeleteProductConfirmation(product) {
      this.setSelectedProduct(product)
      this[productsViewActions.setDeleteProductDialogStatus](true)
    },
    closeDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'SimilarProductUpcDialog',
        name: 'Close dialog',
      })
      this.setSelectedProduct(null)
      if (
        this.similarProductsUpcDialog.isFromProductDetails &&
        !this.deletedProducts.includes(this.similarProductsUpcDialog.product.id)
      ) {
        this.setSelectedProduct(this.similarProductsUpcDialog.product)
        this.toggleDetailDialog()
      }
      this[productsViewActions.setSimilarProductsUpcDialog]({
        isOpen: false,
        product: null,
        isFromProductDetails: false,
      })
      this.similarProducts = []
      this.deletedProducts = []
    },
    deleteProduct() {
      this.$loading.show('deleteProduct')
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'DeleteProductDialog',
        name: `Confirm delete product`,
      })
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.delete.name,
        data: { productId: this.selectedProduct.id },
      })
    },
    deleteProductListener(event, payload) {
      const replies = {
        [STORE_INVENTORY_DB_API_EVENTS.events.delete.replies.success]: () => {
          rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
            event: SYNCHRONIZATION_EVENTS.events.deleteOperation.name,
            data: {
              entityData: payload.data,
              entityName: 'stock',
            },
          })
          this[productsActions.removeProduct](payload.data)
          notificationsService.showSuccess(
            'notification.products.deleted',
            this.$vuetify.lang
          )
          this.$root.$emit('productWasDeleted', { productId: payload.data })
          console.log('Product deleted: ', payload.data)
          this.deletedProducts.push(payload.data)
          this[productsViewActions.setDeleteProductDialogStatus](false)
        },
        [STORE_INVENTORY_DB_API_EVENTS.events.delete.replies.error]: () => {
          if (payload.data) captureException(payload.data)
          notificationsService.showError(
            'notification.products.errorDeleting',
            this.$vuetify.lang
          )
        },
      }
      this.$loading.hide()
      if (payload.event in replies) replies[payload.event]()
    },

    async purchaseOrderListener(event, payload) {
      const purchaseEvents = PURCHASES_DB_API_EVENTS.events
      const replies = {
        [purchaseEvents.removeItemInDraftPurchases.replies.success]: () => {
          this[salesActions.removeProductFromAllSales]({
            product: this.selectedProduct,
          })
          this[purchasesViewActions.removeProductFromPurchase]({
            upcProduct: this.selectedProduct.upc,
          })
          this[purchasesViewActions.removeReturnProductFromPurchase]({
            returnProductId: this.selectedProduct.id,
          })
          this.deleteProduct()
          this[productsViewActions.setProductInSaleDialogStatus](false)
        },
        [purchaseEvents.removeItemInDraftPurchases.replies.error]: () => {
          notificationsService.showError(
            'notification.products.errorDeleting',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  mounted() {
    this.setSimilarProducts()
    this.$root.$on('productMustBeDeleted', this.deleteProduct)
    rendererEventsService.subscribe(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.deleteProductListener
    )
    rendererEventsService.subscribe(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseOrderListener
    )
  },
  destroyed() {
    this.$root.$off('productMustBeDeleted', this.deleteProduct)
    rendererEventsService.removeListener(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.deleteProductListener
    )
    rendererEventsService.removeListener(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseOrderListener
    )
  },
}
</script>
