import { storeInventory } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'
import {
  formatNumberFromDb,
  formatNumberToCurrency,
} from '@/tools/numbersFormat'

import {
  getPiecePriceValue,
  setPiecePriceValue,
  finishPiecePriceEdit,
  getPieceCostValue,
  setPieceCostValue,
  getPieceMarginValue,
} from '@/components/ProductDetail/DetailsTab/tools'
import dialogConfig from '@/components/ProductDetail/DetailsTab/costWarningDialogConfig'

const setConfig = (state, methods) => ({
  state,
  methods,
  singleWidgets: {
    firstSection: [
      {
        id: 'piecePrice',
        type: 'SingleEditDataWidget',
        value: getPiecePriceValue(
          state.product.price,
          state.product.unitProdPrice,
          state.product.factor
        ),
        valueTextColor: 'textPrimary',
        valueLimit: state.limits.maxValuePrice,
        label: 'productsView.details.price',
        iconColor: state.product.price <= 0 ? 'error' : 'accent',
        labelIcon: 'mdi-pencil',
        reverse: false,
        onInputChange: newValue =>
          setPiecePriceValue(methods, state.product.factor, newValue),
        onInputFinishEdit: () => {
          methods.track({
            type: 'interaction',
            action: 'click',
            category: state.routeName,
            screen: 'ProductDetails',
            name: `Save piece price`,
          })
          finishPiecePriceEdit(methods, state.product)
        },
        numberFormatter: value => formatNumberFromDb(value),
        textFormatter: value => formatNumberToCurrency(value),
      },
    ],
    secondSection: [
      {
        id: 'pieceCost',
        type: 'SingleEditDataWidget',
        value: getPieceCostValue(state.product.cost, state.product.factor),
        valueTextColor: 'textPrimary',
        valueLimit: state.limits.maxValuePrice,
        label: 'productsView.details.averageCost',
        labelIcon: 'mdi-pencil',
        reverse: true,
        dialogConfig: dialogConfig,
        warningMessageTitle: 'productsView.details.warningMsgChangingCostTitle',
        warningMessages: [
          'productsView.details.warningMsgChangingCost',
          'productsView.details.warningMsgChangingCostB',
        ],
        onInputChange: newValue =>
          setPieceCostValue(methods, state.product.factor, newValue),
        onInputFinishEdit: () => {
          methods.track({
            type: 'interaction',
            action: 'click',
            category: state.routeName,
            screen: 'ProductDetails',
            name: `Save piece cost`,
          })
          methods.updateDatabase({
            id: state.product.id,
            data: mapStoreObject(
              { cost: state.product.cost },
              storeInventory,
              true
            ),
          })
        },
        numberFormatter: value => formatNumberFromDb(value),
        textFormatter: value => formatNumberToCurrency(value),
      },
      {
        id: 'pieceMargin',
        type: 'SingleDataWidget',
        value: getPieceMarginValue(
          state.product.price,
          state.product.unitProdPrice,
          state.product.cost,
          state.product.factor
        ),
        label: 'productsView.details.averageMargin',
        labelIcon: 'mdi-chart-bar',
        reverse: true,
      },
    ],
  },
})

export default setConfig
