<template>
  <Product
    price-key="cost"
    price-without-promotion-key="costWithoutPromotion"
    :product="item"
    :actions="cardActions"
    @productCardWasClicked="onClickEditProduct"
  />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import PURCHASE_ORDER_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderItemEvents'
import { promotions } from '@/config/promotions'

import { calculateUnitaryCostWithPromotion } from '@/tools/promotions'
import { getTranslatedText } from '@/tools/data'
import { getTotalProductPriceWithIva } from '@/tools/ticket'
import { applyTax } from '@/tools/purchases/tools'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import purchasesViewActions from '@/store/purchasesView/actions.types'

import Product from '@/components/shared/Ticket/Product'

export default {
  name: 'TicketProduct',
  components: { Product },
  props: {
    product: {
      type: Object,
      required: true,
    },
    ticketCols: {
      type: Number,
      required: true,
    },
  },
  data() {
    return {
      hover: false,
    }
  },
  computed: {
    ...mapState('app', ['windowSize', 'sidebarOpened']),
    ...mapState('purchasesView', ['selectedPurchase']),
    item() {
      return {
        ...this.product,
        price: this.product.cost,
        discount: this.product.discountPercent,
        costWithoutPromotion: Number(
          (
            this.product.costWithoutTaxAndPromotion * applyTax(this.product.iva)
          ).toFixed(0)
        ),
      }
    },
    cardActions() {
      return {
        add: {
          on: { click: () => this.updateQuantity('add') },
          show: this.product.isGeneric !== 1,
        },
        subtract: {
          on: { click: () => this.updateQuantity('subtract') },
          show: this.product.isGeneric !== 1,
        },
        delete: {
          on: { click: () => this.removeProduct() },
          show: true,
        },
        edit: {
          on: { click: () => this.onClickEditProduct() },
          show: true,
        },
      }
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('purchasesView', Object.values(purchasesViewActions)),
    removeProduct() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'TicketProduct',
        name: 'Remove product',
      })
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event: PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.delete.name,
        data: {
          purchaseOrderItem: this.product,
        },
      })
    },
    updateQuantity(operation) {
      if (!['add', 'subtract'].includes(operation)) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'TicketProduct',
        name: `${operation === 'add' ? 'Add' : 'Subtract'} quantity`,
      })
      const {
        promotionExtra,
        promotionTypeId,
        quantity: currentQuantity,
      } = this.product
      let newQuantity = currentQuantity + (operation === 'add' ? 1 : -1)
      const isInvalidQuantity =
        newQuantity < 1 ||
        (promotionTypeId === promotions.PURCHASE_ITEM_FREE_UNITS &&
          newQuantity - promotionExtra < 1)
      if (isInvalidQuantity) return
      let unitaryCost = this.getUnitaryCost(newQuantity)
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event: PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.update.name,
        data: {
          purchaseOrderId: this.selectedPurchase._id,
          purchaseItemUpdated: {
            ...this.product,
            cost: unitaryCost,
            quantity: newQuantity,
          },
        },
      })
    },
    getUnitaryCost(quantity) {
      this.checkDiscountAmountIsGreaterThanCost(quantity)
      return calculateUnitaryCostWithPromotion({
        ...this.product,
        quantity,
        cost:
          this.product.costWithoutTaxAndPromotion * applyTax(this.product.iva),
      })
    },
    checkDiscountAmountIsGreaterThanCost(quantity) {
      if (
        this.product.promotionTypeId !==
          promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT ||
        this.product.discountAmount <= 0
      ) {
        return
      }
      const total = getTotalProductPriceWithIva(
        {
          ...this.product,
          quantity,
        },
        'costWithoutTaxAndPromotion'
      )
      if (total <= this.product.discountAmount) {
        this.product.promotionTypeId = promotions.NONE
        this.product.promotionExtra = 0
        this.product.discountAmount = 0
        notificationsService.showWarning(
          'purchaseView.promotion.errorDiscountGreaterThanCost',
          this.$vuetify.lang,
          {},
          [this.product.name]
        )
      }
    },
    onClickEditProduct() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'TicketProduct',
        name: 'Show product triangulation dialog',
      })
      this[purchasesViewActions.setSelectedProduct]({
        product: this.product,
        fromTicket: true,
      })
      this[purchasesViewActions.setProductTriangulationDialogStatus](true)
    },
  },
}
</script>
