<template>
  <tr class="stock-modification__row">
    <td>
      {{ purchaseItem.date }}
    </td>
    <td>
      {{ formattedQuantity }}
    </td>
    <td>
      {{ purchaseItem.vendorName }}
    </td>
    <td>
      {{ formattedCost }}
    </td>
    <td>{{ purchaseItem.iva }}%</td>
  </tr>
</template>

<script>
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'
export default {
  name: 'DetailPurchaseRow',
  props: {
    purchaseItem: {
      type: Object,
      required: true,
    },
  },
  computed: {
    ...getSelectedProductByRoute(),
    formattedCost() {
      return formatNumberFromDbToCurrency(this.purchaseItem.cost)
    },
    formattedQuantity() {
      if (this.selectedProduct.factor > 1) {
        return `${this.purchaseItem.quantity} paq `
      } else if (this.purchaseItem.isGramaje === 1) {
        return `${this.purchaseItem.quantity} g`
      }
      return `${this.purchaseItem.quantity} uds`
    },
  },
}
</script>

<style lang="scss" scoped>
tr {
  td {
    max-width: 102px;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}
</style>
