<template>
  <div class="d-flex flex-column">
    <v-text-field
      v-model="value"
      :type="valueType"
      class="custom-text-field"
      color="textPrimary"
      filled
      rounded
      :label="label"
      :prepend-inner-icon="icon"
      :hint="hint"
      :readonly="readonly"
      :suffix="suffix"
    />
  </div>
</template>

<script>
import { removeEmojis } from '@/tools/data'

export default {
  name: 'SingleTextFieldWidget',
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      label: this.config.label,
      icon: this.config.icon,
      reverse: this.config.reverse,
      data: this.config.data,
      row: this.config.rowOrientation,
      hint: this.config.hint,
      valueType: this.config.valueType || 'text',
      readonly: this.config.readonly || false,
      suffix: this.config.suffix || undefined,
    }
  },
  computed: {
    value: {
      get: function() {
        return 'numberFormatter' in this.config
          ? this.config.numberFormatter(this.config.value)
          : this.config.value
      },
      set: function(newValue) {
        this.config.onInputChange(removeEmojis(newValue))
      },
    },
  },
  methods: {
    changeSelect() {
      this.config.onInputFinishEdit()
    },
  },
}
</script>
