<template>
  <v-col :cols="cols" :offset="offset">
    <MoneyTextField
      ref="totalDiscount"
      v-model="inputs.totalWithDiscount"
      :config="{
        fieldName: 'total',
        color: 'white',
        filled: true,
        rounded: true,
        class: 'total-text-field',
        suffix: 'Total',
        backgroundColor: 'primary',
        errorMessage: onValidateFields,
        readonly: true,
      }"
      :options="moneyInputsConfig"
    />
  </v-col>
</template>

<script>
import { moneyTextFieldCountryConfig } from '@/tools/numbersFormat'

import MoneyTextField from '@/components/shared/MoneyTextField'

import productTriangulation from '@/mixins/purchases/productTriangulation'

export default {
  name: 'GiftProductsForm',
  components: { MoneyTextField },
  props: {
    inputs: {
      type: Object,
      required: true,
    },
    offset: {
      type: Number,
      default: 0,
    },
    cols: {
      type: Number,
      default: 0,
    },
  },
  data() {
    return {
      moneyInputsConfig: this.getMoneyInputsConfig(),
    }
  },
  methods: {
    getMoneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
    setFormValidators() {
      const validations = {
        inputs: {
          totalWithDiscount: this.setMoneyValidator(1000000, 4),
        },
      }
      return validations
    },
  },
  mixins: [productTriangulation],
  validations() {
    return this.setFormValidators()
  },
}
</script>
