const setConfig = (state, methods) => ({
  state,
  methods,
  paymentType: {
    id: 'paymentType',
    type: 'radioGroup',
    value: state.data.payOption,
    disabled: () => state.data.items.length <= 0,
    onChangeValue: methods.changePayOption,
    options: [
      {
        id: 'cash',
        label: 'salesView.ticket.cash',
        value: 'cash',
      },
      {
        id: 'credit',
        label: 'salesView.ticket.credit',
        value: 'credit',
      },
    ],
  },
  fields: [
    {
      id: 'print',
      type: 'switch',
      label: 'salesView.ticket.title',
      color: 'primary',
      value: state.data.print,
      hideDetails: true,
      inset: true,
      onChangeValue: methods.changePrintStatus,
    },
  ],
})

export default setConfig
