import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

const setConfig = (state, methods) => ({
  state,
  methods,
  columns: [
    {
      id: 'right',
      class: 'd-flex flex-column right-column ml-4',
      rows: [
        {
          id: 'titleRow',
          class: 'd-flex',
          elements: [
            {
              id: 'discountLabel',
              componentType: 'text',
              type: 'text-subtitle-1',
              class: 'pl-1',
              className: 'font-weight-bold',
              color: 'productCardWarningPrimary',
              value: methods.getTranslatedText(
                'purchaseView.promotion.ticket.productToChange'
              ),
            },
          ],
        },
        {
          id: 'productReturnRow',
          class: 'd-flex',
          elements: [
            {
              id: 'productReturnColumns',
              componentType: 'column',
              class: 'd-flex flex-column',
              columns: [
                {
                  id: 'quantityColumn',
                  rows: [
                    {
                      id: 'quantityRow',
                      class: 'd-flex flex-column align-center',
                      elements: [
                        {
                          id: 'quantity',
                          componentType: 'text',
                          type: 'text-h5',
                          class: 'px-1 text-center',
                          className: 'font-weight-bold',
                          color: 'productProductNameTicket',
                          value: `${state.returnProduct.productChangeQuantity} `,
                        },
                      ],
                    },
                    {
                      id: 'quantityTypeRow',
                      class: 'd-flex',
                      elements: [
                        {
                          id: 'unitType',
                          componentType: 'text',
                          type: 'text-subtitle-1',
                          class: 'extra-icons',
                          color: 'unitTypeTicket',
                          intl: true,
                          value: getUnitType(
                            state.returnProduct.productChangeIsGramaje
                          ),
                        },
                      ],
                    },
                  ],
                },
              ],
            },
            {
              id: 'productReturnDataColumn',
              componentType: 'column',
              class: 'd-flex flex-column right-column ml-4',
              columns: [
                {
                  id: 'dataColum',
                  rows: [
                    {
                      id: 'productNameRow',
                      class: 'd-flex',
                      elements: [
                        {
                          id: 'productChangeName',
                          componentType: 'text',
                          type: 'text-h6',
                          class: 'pl-1',
                          color: 'productProductNameTicket',
                          value: state.returnProduct.productChangeName,
                          shorter: state.truncateLength,
                        },
                        {
                          id: 'totalPrice',
                          componentType: 'text',
                          type: 'text-h5',
                          class: 'ml-auto pr-1',
                          className: 'font-weight-bold',
                          color: 'productProductNameTicket',
                          value: formatNumberFromDbToCurrency(
                            getTotal(state.returnProduct)
                          ),
                        },
                      ],
                    },
                    {
                      id: 'UnitPriceRow',
                      class: 'd-flex',
                      elements: [
                        {
                          id: 'unitPrice',
                          componentType: 'text',
                          type: 'pl-1 text-h6',
                          color: 'primary',
                          value: formatNumberFromDbToCurrency(
                            state.returnProduct.productChangeCost
                          ),
                        },
                      ],
                    },
                  ],
                },
              ],
            },
          ],
        },
        {
          id: 'ProductReturnTitle',
          class: 'd-flex',
          elements: [
            {
              id: 'discountLabel',
              componentType: 'text',
              type: 'text-subtitle-1',
              className: 'font-weight-bold',
              color: 'productCardWarningPrimary',
              value: methods.getTranslatedText(
                'purchaseView.promotion.ticket.productToReturn'
              ),
            },
          ],
        },
        {
          id: 'ProductReturn',
          class: 'd-flex',
          elements: [
            {
              id: 'productReturnQuantity',
              componentType: 'text',
              type: 'text-subtitle-1',
              className: 'font-weight-bold',
              color: 'productProductNameTicket',
              value: `${state.returnProduct.productReturnQuantity} ${
                state.returnProduct.productReturnIsGramaje ? 'gr' : 'pzs'
              }`,
            },
            {
              id: 'productReturnName',
              componentType: 'text',
              type: 'text-subtitle-1',
              class: 'ml-4',
              className: 'font-weight-bold',
              color: 'productProductNameTicket',
              value: state.returnProduct.productReturnName,
            },
          ],
        },
      ],
    },
  ],
})

const getUnitType = isGramaje => {
  return isGramaje === 1 ? 'salesView.ticket.grams' : 'salesView.ticket.pieces'
}

const getTotal = () => {
  return 0
}

export default setConfig
