<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'

import { formatNumberToDb } from '@/tools/numbersFormat'
import { getPromotionTicketToDB } from '@/tools/promotions'

import rendererEventsService from '@/services/renderer/rendererEvents'

import purchasesViewActions from '@/store/purchasesView/actions.types'

import setDialogConfig from '@/components/PurchasesView/OverCreditLimitDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'OverCreditLimitDialog',
  components: { DialogCard },
  computed: {
    ...mapState('purchasesView', [
      'overCreditLimitDialog',
      'selectedPurchase',
      'currentPurchase',
    ]),
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.overCreditLimitDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
          payPurchase: this.payPurchase,
        }
      )
    },
  },
  methods: {
    ...mapActions('purchasesView', [
      purchasesViewActions.toggleOverCreditLimitDialogStatus,
      purchasesViewActions.toggleConfirmPurchaseDialogStatus,
      purchasesViewActions.setFinishingPurchaseStatus,
    ]),
    closeDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'OverCreditLimitDialog',
        name: 'Cancel',
      })
      this[purchasesViewActions.toggleOverCreditLimitDialogStatus]()
    },
    payPurchase() {
      if (this.currentPurchase.isFinishing === true) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'OverCreditLimitDialog',
        name: 'Submit',
      })
      this[purchasesViewActions.setFinishingPurchaseStatus](true)
      const { payOption, cost } = this.selectedPurchase
      this.$loading.show('finishPurchase')
      rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
        event: PURCHASES_DB_API_EVENTS.events.finishPurchase.name,
        data: {
          purchaseData: {
            ...this.selectedPurchase,
            payOption:
              payOption === 'credit' && cost === 0 ? 'cash' : payOption,
            promotion: getPromotionTicketToDB(this.selectedPurchase),
          },
          userId: this.selectedUser.id,
          username: this.selectedUser.name,
          estimatedCash: this.getEstimatedCash(),
          isFromExternalCashRegister: false,
        },
      })
    },
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
  },
}
</script>
