import { promotions } from '@/config/promotions'

import {
  discountTypes,
  getAmountFromPercent,
  getTotalTicketWithPromotion,
} from '@/tools/promotions'
import {
  formatNumberFromDb,
  formatNumberFromDbToCurrency,
  formatNumberToCurrency,
} from '@/tools/numbersFormat'

const setConfig = (state, methods) => ({
  state,
  methods,
  payButton: {
    flat: true,
    color: state.disabledButton ? 'cardBackgroundDisabled' : 'primary',
    borderRadius: '10px',
    class:
      !isFromSalesPage(state.fromPage) && state.data.promotion === 0
        ? 'py-4 px-4'
        : 'py-2 px-4',
    onClick: methods.onClickPayButton,
    tooltip: 'payButton.tooltip',
    columns: [
      {
        id: 'left',
        class: 'd-flex flex-column justify-center',
        elements: [
          {
            id: 'payLine',
            columns: [
              {
                id: 'payText',
                type: 'text-h6',
                class: 'pl-1',
                className: 'font-weight-bold',
                color: 'textOverWhiteBackground',
                intl: true,
                value: `payButton.title.${state.fromPage}`,
              },
              {
                id: 'numberProductsText',
                type: 'text-subtitle-2',
                class: 'pt-1 pl-2',
                color: 'textOverWhiteBackground',
                value: totalProducts(state.data, state.lang),
              },
            ],
          },
          {
            id: 'promotion',
            columns: getPromotionRow(state, methods),
          },
          getClientInfo(state),
        ],
      },
      {
        id: 'right',
        elements: getTotalCost(state, methods),
      },
    ],
  },
})

const totalProducts = (ticket, lang) => {
  const products = new Set()
  ticket.items.forEach(item => products.add(item.id))
  if (ticket.promotions) {
    ticket.promotions.forEach(promo => {
      products.add(promo.promotions.firstProductId)
      products.add(promo.promotions.secondProductId)
    })
  }
  return `${products.size} ${lang.t('$vuetify.payButton.products')}`
}

const getPromotionRow = (state, methods) => {
  if (!hasTicketPromotion(state)) {
    return [
      {
        id: 'promotionText',
        type: 'text-subtitle-2',
        class: 'pl-1 mb-1',
        color: 'textOverWhiteBackground',
        intl: true,
        value: 'payButton.noPromotion',
      },
    ]
  }
  return [
    {
      id: 'promotionIcon',
      type: 'icon',
      icon: 'mdi-sale',
      color: state.isDarkMode ? 'grey darken-4' : 'white',
      size: '22',
    },
    {
      id: 'promotionText',
      type: 'text-subtitle-2',
      class: 'pl-1 mb-1',
      color: 'textOverWhiteBackground',
      intl: false,
      value: state.lang.t(...getPromotion(state, methods)),
    },
  ]
}

const hasTicketPromotion = state => {
  if (
    state.data.promotionTicketId &&
    state.data.promotionTicketId === promotions.SALE_TICKET_AT_COST
  ) {
    return true
  }
  return state.data.promotion > 0
}

const getPromotion = (state, methods) => {
  if (
    state.data.promotionTicketId &&
    state.data.promotionTicketId === promotions.SALE_TICKET_AT_COST
  ) {
    return ['$vuetify.payButton.saleAtCost']
  }
  return getDiscount(state, methods)
}

const getDiscount = (state, methods) => {
  if (discountTypes.isDiscountPerAmount(state.data.promotion_type)) {
    return [
      '$vuetify.payButton.discountOfAmount',
      formatNumberFromDbToCurrency(state.data.promotion),
    ]
  }
  return [
    '$vuetify.payButton.discountOfPercent',
    `${state.data.promotion}% (${formatNumberToCurrency(
      getAmountFromPercent(
        state.data.promotion,
        formatNumberFromDb(
          methods.getPrice(state.data.items, state.data.returnItems)
        )
      )
    )})`,
  ]
}

const getClientInfo = state => {
  if (!isFromSalesPage(state.fromPage)) return {}
  return {
    id: 'customerLine',
    columns: [
      {
        id: 'customerIcon',
        type: 'icon',
        icon:
          state.data.customer === '' ? 'mdi-account-question' : 'mdi-account',
        color: state.isDarkMode ? 'grey darken-4' : 'white',
        size: '25',
      },
      {
        id: 'customerText',
        type: 'text-subtitle-2',
        class: 'pl-1',
        color: 'textOverWhiteBackground',
        intl: state.data.customer === '',
        value:
          state.data.customer === ''
            ? 'salesView.ticket.noCustomer'
            : state.data.customer.name,
      },
    ],
  }
}

const getTotalCost = (state, methods) => {
  if (state.data.promotion === 0) {
    return [
      {
        id: 'totalPrice',
        type: 'text-h3',
        class: 'pt-0',
        className: 'font-weight-bold',
        color: 'textOverWhiteBackground',
        value: formatNumberFromDbToCurrency(
          methods.getPrice(state.data.items, state.data.returnItems)
        ),
      },
    ]
  }
  return [
    {
      id: 'oldTotalPrice',
      type: 'text-h6',
      class: 'pt-0 text-right',
      className: 'text-decoration-line-through',
      color: 'cardBackgroundDisabled',
      value: formatNumberFromDbToCurrency(
        methods.getPrice(state.data.items, state.data.returnItems)
      ),
    },
    {
      id: 'totalPrice',
      type: isFromSalesPage(state.fromPage) ? 'text-h3' : 'text-h4',
      class: 'pt-0 text-right',
      className: 'font-weight-bold',
      color: 'textOverWhiteBackground',
      value: getTotalWithPromotion(state, methods),
    },
  ]
}

const getTotalWithPromotion = (state, methods) => {
  return formatNumberFromDbToCurrency(
    getTotalTicketWithPromotion(methods.getPrice, state.data)
  )
}

const isFromSalesPage = fromPage => {
  return fromPage === 'sales'
}

export default setConfig
