<template>
  <v-hover v-model="hover">
    <div class="px-6 pt-3" style="position: relative">
      <div
        v-for="button in config.floatingButtons"
        :key="button.id"
        class="floating-buttons"
      >
        <v-btn
          v-if="button.show"
          :class="button.class"
          :absolute="button.absolute"
          :icon="button.showIcon"
          :fab="button.fab"
          :x-small="button.xSmall"
          @click="button.onClick"
        >
          <v-icon :color="button.iconColor">{{ button.icon }}</v-icon>
        </v-btn>
      </div>
      <v-card
        flat
        class="py-2 px-4 d-flex return-card"
        @click="onClickEditProduct"
      >
        <v-icon
          large
          color="productCardWarningPrimary"
          class="align-self-start"
        >
          $vuetify.icons.values.returnProduct</v-icon
        >
        <DiscountProductType
          v-if="isDiscountType"
          style="width:100%"
          class="pr-4"
          :config="productConfig"
        />
        <ChangeProductType
          v-else
          style="width:100%"
          class="pr-4"
          :config="productConfig"
        />
      </v-card>
    </div>
  </v-hover>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderReturnItemEvents'
import { returnTypes } from '@/config/returnProductTypes'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import purchasesViewActions from '@/store/purchasesView/actions.types'

import setDiscountProductConfig from '@/components/PurchasesView/Ticket/TicketReturnProduct/discountProductConfig'
import setChangeProductConfig from '@/components/PurchasesView/Ticket/TicketReturnProduct/changeProductConfig'
import setConfig from '@/components/PurchasesView/Ticket/TicketReturnProduct/config'
import DiscountProductType from '@/components/shared/ChangeProductType'
import ChangeProductType from '@/components/shared/ChangeProductType'

export default {
  name: 'TicketReturnProduct',
  components: { DiscountProductType, ChangeProductType },
  props: {
    returnProduct: {
      type: Object,
      required: true,
    },
    ticketCols: {
      type: Number,
      required: true,
    },
  },
  data() {
    return {
      hover: false,
    }
  },
  computed: {
    ...mapState('app', ['windowSize', 'sidebarOpened']),
    config() {
      return setConfig(
        {
          hover: this.hover,
        },
        {
          editReturnProduct: this.onClickEditProduct,
          deleteFromCart: this.deleteFromCart,
        }
      )
    },
    productConfig() {
      return this.isDiscountType
        ? setDiscountProductConfig(
            {
              returnProduct: this.returnProduct,
              truncateLength: this.truncateLength,
              lang: this.$vuetify.lang,
            },
            {
              getTranslatedText: this.getTranslatedText,
            }
          )
        : setChangeProductConfig(
            {
              returnProduct: this.returnProduct,
              truncateLength: this.truncateLength,
              lang: this.$vuetify.lang,
            },
            {
              getTranslatedText: this.getTranslatedText,
            }
          )
    },
    isDiscountType() {
      return this.returnProduct.returnType === returnTypes.DISCOUNT
    },
    truncateLength() {
      const value = this.sidebarOpened
        ? this.windowSize.x - 256 + 250 * this.ticketCols
        : this.windowSize.x - 56 + 250 * this.ticketCols
      if (value < 2350) return '14'
      if (value < 2450) return '16'
      if (value < 2525) return '18'
      if (value < 2600) return '20'
      if (value < 2692) return '22'
      if (value < 2785) return '24'
      if (value < 2850) return '26'
      if (value < 2900) return '28'
      if (value < 3000) return '30'
      if (value < 3100) return '33'
      if (value < 3250) return '36'
      return '40'
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('purchasesView', [
      purchasesViewActions.setReturnProductDialogStatus,
    ]),
    deleteFromCart() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'TicketReturnProduct',
        name: 'Remove return product',
      })
      rendererEventsService.send(
        PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.channel,
        {
          event: PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.events.delete.name,
          data: {
            purchaseOrderReturnItem: this.returnProduct,
          },
        }
      )
    },
    onClickEditProduct() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'TicketReturnProduct',
        name: 'Show return product dialog',
      })
      this[purchasesViewActions.setReturnProductDialogStatus]({
        isOpen: true,
        isFromTicket: true,
        returnProduct: this.returnProduct,
      })
    },
  },
}
</script>

<style lang="scss" scoped>
.return-card {
  background-color: var(--v-cardBackgroundPrimary-base);
  border-radius: 10px;
  border-left: 6px solid var(--v-productCardWarningPrimary-base);
}
.delete-from-cart-button {
  z-index: 100;
  top: 4px;
  right: 10px;
}
.edit-from-cart-button {
  z-index: 100;
  bottom: -6px;
  right: 10px;
}
</style>
