import { isNil } from 'ramda'

import { returnTypes } from '@/config/returnProductTypes'

import { getDateWithFormat } from '@/tools/dates'
import {
  formatNumberFromDbToCurrency,
  formatNumberToDb,
  roundToNearestMultiple,
} from '@/tools/numbersFormat'
import { discountTypes, getAmountFromPercent } from '@/tools/promotions'
import { getTotalTicketPrice } from '@/tools/ticket'

const getDetails = function() {
  const details = [
    ['purchaseView.confirmDialog.vendor', this.selectedVendor.name],
  ]
  if (!this.isCashPayOption) {
    details.push([
      'purchaseView.confirmDialog.currentDebt',
      currentDebt(this.selectedVendor),
    ])
  }
  details.push(
    [
      'purchaseView.confirmDialog.payOption',
      this.getTranslatedText(
        `salesView.ticket.${this.selectedPurchase.payOption}`
      ),
    ],
    ['purchaseView.confirmDialog.datePurchase', getDate(this.selectedPurchase)],
    [
      'purchaseView.confirmDialog.NumberProducts',
      this.selectedPurchase.items.length,
    ]
  )
  if (this.hasPromotion) {
    details.push(getPromotionDetail.call(this))
  }
  return details
}

const getDate = selectedPurchase =>
  getDateWithFormat(selectedPurchase.creation_date, 'DD/MM/YYYY')

const currentDebt = selectedVendor =>
  formatNumberFromDbToCurrency(selectedVendor.debt)

const getPromotionDetail = function() {
  if (discountTypes.isDiscountPerAmount(this.selectedPurchase.promotion_type)) {
    return [
      'purchaseView.promotion.ticket.discountOfAmount',
      formatNumberFromDbToCurrency(this.selectedPurchase.promotion),
    ]
  }
  return [
    'purchaseView.promotion.ticket.discountOfPercent',
    `${this.selectedPurchase.promotion}% (${formatNumberFromDbToCurrency(
      getDiscountAmountFromPercent.call(this)
    )})`,
  ]
}

const getDiscountAmountFromPercent = function() {
  return getAmountFromPercent(
    this.selectedPurchase.promotion,
    getPriceToDb.call(this)
  )
}

const getLogoPath = function() {
  if (this.selectedVendor.hasLogo !== 1) {
    return require(`@/assets/logos/Icono_PlayStore.svg`)
  }
  const vendorId = !isNil(this.selectedVendor.supplierId)
    ? this.selectedVendor.supplierId
    : this.selectedVendor.id
  return `file://${this.assetsPath}/suppliers/supplier_${vendorId}.png`
}

const getEstimatedCash = function() {
  const stateEstimatedCash =
    this.estimatedCash === null || this.estimatedCash === undefined
      ? 0
      : this.estimatedCash
  return formatNumberToDb(stateEstimatedCash)
}

const getPriceToDb = function() {
  const totalProducts = getTotalTicketPrice(
    this.selectedPurchase.items,
    'cost'
  ).toFixed(0)
  const returnProductsTotal = this.selectedPurchase.returnItems
    .reduce((total, returnItem) => {
      const { returnType, amountToDiscount } = returnItem
      const subtotal =
        returnType === returnTypes.DISCOUNT ? amountToDiscount : 0
      return total + subtotal
    }, 0)
    .toFixed(0)
  return roundToNearestMultiple(
    parseInt(totalProducts) + parseInt(-returnProductsTotal)
  )
}

const isCreditLessThanDebtLimit = function() {
  const totalDebt = this.selectedVendor.debt + this.selectedPurchase.cost
  return (
    isNil(this.selectedVendor.debtLimit) ||
    this.selectedVendor.debtLimit === 0 ||
    this.selectedVendor.debtLimit > totalDebt
  )
}

export default {
  getDetails,
  getLogoPath,
  getEstimatedCash,
  getPriceToDb,
  isCreditLessThanDebtLimit,
  getDiscountAmountFromPercent,
}
