const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    id: 'similar-products-upc',
    opened: state.isOpen,
    icon: 'mdi-alert',
    title: 'productsView.similarProducts.title',
    titleColor: 'textPrimary',
    height: state.similarProductCount > 2 ? 665 : 580,
    buttons: {
      cancel: true,
      accept: false,
    },
    buttonTextColor: {
      cancel: 'white',
    },
    buttonColor: {
      cancel: 'accent',
    },
    cancelButtonText: 'close',
    maxWidth: 500,
    onClickCancel: () => {
      methods.closeDialog()
    },
    ref: 'similar-product-dialog',
  },
})

export default setConfig
