<template>
  <div class="fill-height">
    <PaginatedCards :config="paginatedCardsConfig" id="purchases-products-list">
      <template v-slot:title>
        <div class="d-flex align-center paginated-title">
          <v-img
            height="50"
            max-width="100"
            contain
            :src="logoPath"
            alt="logo"
            class="mr-4"
          />
          <h2 class="font-weight-bold ">
            {{ getTranslatedText('purchaseView.title', selectedVendor.name) }}
          </h2>
        </div>
      </template>
    </PaginatedCards>
    <ReturnProductDialog v-if="returnProductDialog.isOpen" />
    <SimilarProductsUpc v-if="similarProductsUpcDialog.isOpen" />
    <v-dialog
      v-model="productDetailDialog.isOpen"
      max-width="715"
      content-class="default-dialog"
      :overlay-opacity="0.15"
      @click:outside="onClickOutside"
      @keydown.esc="onClickOutside"
    >
      <!-- Detail view -->
      <ProductDetail v-if="productDetailDialog.isOpen" />
    </v-dialog>
  </div>
</template>

<script>
import { mapGetters, mapState, mapActions } from 'vuex'
import { concat, filter, isNil, values } from 'ramda'
import uniqid from 'uniqid'

import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'
import { testMode } from '@/config/env'
import PURCHASE_ORDER_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderItemEvents'
import { promotions } from '@/config/promotions'

import { getObjectCopy } from '@/tools/data'
import { getNow } from '@/tools/dates'
import { getTranslatedText } from '@/tools/data'
import productsTools from '@/tools/products'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'
import productsActions from '@/store/products/actions.types'

import PaginatedCards from '@/components/shared/PaginatedCards'
import ProductDetail from '@/components/ProductDetail'
import ReturnProductDialog from '@/components/PurchasesView/ReturnProductDialog'
import setConfig from '@/components/PurchasesView/ProductsList/PaginatedCards/config'
import SimilarProductsUpc from '@/components/ProductsView/ProductsList/SimilarProductsUpc'

export default {
  name: 'PaginatedCardsList',
  components: {
    SimilarProductsUpc,
    PaginatedCards,
    ProductDetail,
    ReturnProductDialog,
  },
  data() {
    return {
      barcode: null,
    }
  },
  computed: {
    ...mapState('app', {
      windowSize: state => state.windowSize,
      sidebarOpened: state => state.sidebarOpened,
      assetsPath: state => state.paths.assets,
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    ...mapState('vendorsView', ['selectedVendor']),
    ...mapState('products', {
      productFetching: state => state.fetching,
      products: state => state.data.products,
      mlp: state => state.data.mlp,
      byWeightTree: state => state.data.byWeightTree,
    }),
    ...mapState('purchasesView', {
      selectedProduct: state => state.selectedProduct,
      currentCardComponent: state => state.cardComponent,
      selectedPurchase: state => state.selectedPurchase,
      filters: state => state.filters,
      tourEnabled: state => state.tourEnabled,
      returnProductDialog: state => state.returnProductDialog,
    }),
    ...mapGetters('purchasesView', ['getFilteredProducts']),
    ...mapState('productsView', ['similarProductsUpcDialog']),
    paginatedCardsConfig() {
      return setConfig(
        {
          items: this.filteredData,
          selectedCard: this.selectedProduct,
          filters: this.filters,
          windowHeight: this.windowSize.y,
          windowWidth: this.windowSize.x,
          fetching: this.productFetching,
          sidebarOpened: this.sidebarOpened,
          currentCardComponent: this.currentCardComponent,
          byWeightTree: this.byWeightTree,
          products: this.products,
        },
        {
          context: this,
          resetScannerStatus: this.resetScannerStatus,
          setGroup: this[purchasesViewActions.setGroupFilter],
          setSelectedProduct: this[purchasesViewActions.setSelectedProduct],
          setSelectedSuperCategories: this[
            purchasesViewActions.setSuperCategoriesFilter
          ],
          onCLickCard: this.onCLickCard,
          toggleDetailPanel: this[purchasesViewActions.toggleDetailDialog],
          setProductTriangulationDialogStatus: this[
            purchasesViewActions.setProductTriangulationDialogStatus
          ],
          track: this.$track,
          closeProductTriangulation: () =>
            this[purchasesViewActions.setProductTriangulationDialogStatus](
              false
            ),
        }
      )
    },
    ...mapState({
      productDetailDialog(state) {
        return state[this.getViewStore()].productDetailDialog
      },
    }),
    filteredData() {
      const filteredData = concat(this.getFilteredProducts, this.mlp)
      const searchTerm = this.filters.searchTerm
      if (
        !isNil(searchTerm) &&
        this.isScannerActive === true &&
        filteredData.length === 0
      ) {
        if (searchTerm.length > 24) {
          this.$root.$emit('reset')
          this.resetScannerStatus(this.defaultProductsFilter)
          this[purchasesViewActions.setSearchTermFilter](null)
          return this.getFilteredProducts
        }
        this.tryAddProductFromMLP(searchTerm)
      }
      return filteredData
    },
    logoPath() {
      const vendorId = !isNil(this.selectedVendor.supplierId)
        ? this.selectedVendor.supplierId
        : this.selectedVendor.id
      const logoSRC =
        this.selectedVendor.hasLogo === 1
          ? `file://${this.assetsPath}/suppliers/supplier_${vendorId}.png`
          : require(`@/assets/logos/Icono_PlayStore.svg`)
      return logoSRC
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('products', [
      productsActions.setProductsOrSuperCategoriesFetching,
      productsActions.addProductFromMLP,
    ]),
    ...mapActions('purchasesView', values(purchasesViewActions)),
    onClickOutside() {
      this[purchasesViewActions.toggleDetailDialog]()
      this[purchasesViewActions.setSelectedProduct](null)
      document.getElementById('clear-button-control').click()
    },
    getViewStore() {
      if (testMode) return 'salesView'
      let view = ''
      switch (this.$route.name) {
        case 'Products':
          view = 'productsView'
          break
        case 'Purchases':
          view = 'purchasesView'
          break
        case 'Sales':
          view = 'salesView'
          break
      }
      return view
    },
    resetScannerStatus(group) {
      switch (group) {
        case 'search-control':
          if (this.isScannerActive === false)
            this[appActions.updateScannerStatus]()
          break
        case 'clear':
          this[purchasesViewActions.setSearchTermFilter](null)
          this[purchasesViewActions.setGroupFilter](this.defaultProductsFilter)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
        default:
          group === 'superCategories'
            ? this[purchasesViewActions.setGroupFilter]('superCategories')
            : this[purchasesViewActions.setGroupFilter](group)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
      }
    },
    async tryAddProductFromMLP(searchTerm) {
      this.barcode = searchTerm
      if (this.productFetching) return
      this[productsActions.setProductsOrSuperCategoriesFetching](true)
      rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
        event: ADD_PRODUCT_EVENTS.events.addProductFromMLP.name,
        data: { item: { property: 'upc_code', value: searchTerm, limit: 1 } },
      })
    },
    processSelectedProduct(product) {
      this[purchasesViewActions.setSelectedProduct](product)
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event:
          PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.getLastPurchaseOrderItemCost
            .name,
        data: {
          productId: product.product.isGeneric ? null : product.product.id,
          vendorId: this.selectedVendor.id,
          showProductTriangulationDialog: true,
        },
      })
    },
    onCLickCard(item) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'ProductCard',
        name: 'Open product triangulation',
      })
      if (this.tourEnabled) {
        if (item.isGeneric === 1 || item.isGramaje === 1) {
          notificationsService.showError(
            'tour.productNotAvailable',
            this.$vuetify.lang,
            { timeout: 4000 }
          )
          return
        } else {
          this.$root.$emit('product-added-tour')
        }
      }
      if (!isNil(item.isStoreInventory) && item.isStoreInventory !== 1) {
        this.tryAddProductFromMLP(item.upc)
        return
      }
      const product = getObjectCopy(item)
      if (product.isGeneric === 1) {
        this.processSelectedProduct({
          product: {
            ...product,
            uniqueId: uniqid(),
            promotionTypeId: promotions.NONE,
            promotionExtra: 0,
            costWithoutTaxAndPromotion: 0,
            discountPercent: 0,
            discountAmount: 0,
            quantity: 1,
            cost: 0,
          },
        })
      } else if (product.isGramaje === 0 && product.id > 0) {
        const productPrices = productsTools.getPrices(product, this.products)
        this.processSelectedProduct({
          product: {
            uniqueId: uniqid(),
            id: product.id,
            stock: product.quantity,
            isGramaje: product.isGramaje === 1 ? 1 : 0,
            isOpenProduct: product.factor > 0 ? 1 : 0,
            openProductType: product.factorSalesBy,
            openProductDbPrices: productPrices.openProductDbPrices,
            isGeneric: product.isGeneric === 1 ? 1 : 0,
            isPriceChanged: productPrices.isPriceChanged,
            isPiecePriceChanged: productPrices.isPiecePriceChanged,
            name: product.name,
            quantity: 1,
            unitPrice: productPrices.unitPrice,
            cost: product.cost,
            upc: product.upc,
            timeAdded: getNow(false),
            priceFrom: productsTools.getAddedFrom(item),
            dbPrice: productPrices.dbPrice,
            levelWarning: item.levelWarning,
            factor: product.factor,
            description: product.alternativeName,
            factorSalesBy: product.factorSalesBy,
            iva: product.iva,
            promotionTypeId: promotions.NONE,
            promotionExtra: 0,
            costWithoutTaxAndPromotion: product.cost,
            discountPercent: 0,
            discountAmount: 0,
          },
        })
      } else if (product.isGramaje === 1) {
        this.processSelectedProduct({
          product: {
            ...product,
            promotionTypeId: promotions.NONE,
            promotionExtra: 0,
            costWithoutTaxAndPromotion: product.cost,
            discountPercent: 0,
            discountAmount: 0,
          },
        })
      } else if (product.id < -1) {
        const category = filter(category => category.name === product.name)(
          this.byWeightTree
        )[0]
        this[purchasesViewActions.setSelectedByWeightCategory](category)
        this[purchasesViewActions.toggleByWeightProductDialogStatus]()
      }
    },
    addProductFromMLPListener(event, payload) {
      const events = ADD_PRODUCT_EVENTS.events
      const replies = {
        [events.addProductFromMLP.replies.success]: () =>
          this.onProductAddedFromMLP(payload.data),
        [events.addProductFromMLP.replies.error]: () =>
          this.onAddingProductFromMLPError(payload.data),
      }
      if (payload.event in replies) replies[payload.event]()
    },
    onProductAddedFromMLP(data) {
      const { newProduct } = data
      this[productsActions.addProductFromMLP]({
        newProduct: newProduct,
        currentView: 'purchasesView',
      })
      const product = getObjectCopy(newProduct)
      this.$root.$emit('reset')
      this.resetScannerStatus(this.defaultProductsFilter)
      this[purchasesViewActions.setSearchTermFilter](null)
      notificationsService.showInfo(
        'productsView.listView.messages.newProductAdded',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
      if (product.isGramaje === 0 && product.id > 0 && product.factor > 0) {
        this[purchasesViewActions.setSelectedProduct]({
          product: {
            ...product,
            openProductDbPrices: {
              package: product.price,
              piece: product.unitProdPrice,
            },
            factorSalesBy: 0,
            promotionTypeId: promotions.NONE,
            costWithoutTaxAndPromotion: product.cost,
            promotionExtra: 0,
            discountPercent: 0,
            discountAmount: 0,
            stock: 0,
          },
        })
        this[purchasesViewActions.setProductTriangulationDialogStatus](true)
        return
      }
      product.stock = 0
      this[purchasesViewActions.setSelectedProduct]({
        product: {
          ...product,
          promotionTypeId: promotions.NONE,
          promotionExtra: 0,
          costWithoutTaxAndPromotion: product.cost,
          discountPercent: 0,
          discountAmount: 0,
        },
      })
      this[purchasesViewActions.setProductTriangulationDialogStatus](true)
      this[productsActions.setProductsOrSuperCategoriesFetching](false)
    },
    onAddingProductFromMLPError(data) {
      if (data.error.message === 'newProduct') {
        this[purchasesViewActions.setAddProductDialogStatus]({
          isOpen: true,
          barcode: this.barcode,
        })
        return
      }
      notificationsService.showError(data.errorMsg, this.$vuetify.lang, {
        timeout: 8000,
      })
      this.$root.$emit('reset')
      this.resetScannerStatus(this.defaultProductsFilter)
      this[purchasesViewActions.setSearchTermFilter](null)
      if (data.error.message === 'invalid-barcode') {
        this[productsActions.setProductsOrSuperCategoriesFetching](false)
        return
      }
      rendererEventsService.send(ENTITIES_EVENTS.channel, {
        event: ENTITIES_EVENTS.events.getAllByEntities.name,
        data: {
          entitiesToGet: [
            'storeInventory',
            'superCategories',
            'genericCategories',
            'byWeightHomeCodes',
            'airtimeProviders',
            'airtimeServices',
          ],
          replyName: 'fetchProducts',
        },
      })
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductFromMLPListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductFromMLPListener
    )
  },
}
</script>
