<template>
  <v-item-group>
    <v-container>
      <v-row>
        <div v-for="brand in data.children" :key="brand.name">
          <div class=" pr-2 pb-2" v-if="brand.visible">
            <v-tooltip bottom>
              <template v-slot:activator="{ on, attrs }">
                <v-item v-slot="{ active, toggle }">
                  <v-hover v-slot="{ hover }">
                    <v-card
                      flat
                      color="cardBackgroundAlternative"
                      class="rounded-lg"
                      :class="{ 'on-hover': hover || active }"
                      width="86"
                      height="86"
                      v-on="on"
                      v-bind="attrs"
                      @click="onClickBrand(brand, toggle)"
                    >
                      <div
                        v-if="brand.logo"
                        class="logo-container d-flex justify-center align-center"
                      >
                        <img
                          v-if="brand.logo"
                          :src="getImageSRC(brand.logo)"
                          class="product-image"
                        />
                      </div>
                      <div
                        v-if="!brand.logo"
                        class="text-container d-flex justify-center align-center"
                      >
                        <span>{{ brand.name }}</span>
                      </div>

                      <div
                        class="icon-container d-flex justify-center align-center"
                      >
                        <v-icon small color="checkIcon">
                          {{ active ? 'mdi-check-circle' : '' }}
                        </v-icon>
                      </div>
                    </v-card>
                  </v-hover>
                </v-item>
              </template>
              {{ brand.name }}
            </v-tooltip>
          </div>
        </div>
      </v-row>
    </v-container>
  </v-item-group>
</template>

<script>
import { mapState } from 'vuex'

import { getDuplicatedItemsByProp } from '@/tools/data'

export default {
  name: 'BrandCard',
  props: {
    data: {
      type: Object,
      required: true,
    },
    onClickChip: {
      type: Function,
      required: true,
    },
  },
  data() {
    return {
      repeatedLogos: [],
    }
  },
  computed: {
    ...mapState('app', {
      assetsPath: state => state.paths.assets,
    }),
  },
  methods: {
    getImageSRC(fileName) {
      return `file://${this.assetsPath}/${fileName}`
    },
    onClickBrand(brand, toggle) {
      toggle()
      this.onClickChip(brand)
    },
  },
  watch: {
    'data.children'() {
      this.repeatedLogos = getDuplicatedItemsByProp(this.data.children, 'logo')
    },
  },
}
</script>

<style lang="scss" scoped>
.v-card {
  transition: opacity 0.4s ease-in-out;
  .logo-container {
    margin: auto;
    height: 100%;
    .product-image {
      width: 78px;
    }
  }
  .text-container {
    height: 100%;
    opacity: 1;
  }
  .icon-container {
    position: absolute;
    top: 4px;
    right: 4px;
  }
}
.v-card:not(.on-hover) {
  opacity: 0.6;
}
</style>
