<template>
  <div class="ml-2">
    <v-tooltip top>
      <template v-slot:activator="{ on, attrs }">
        <v-btn
          v-bind="attrs"
          v-on="on"
          color="primary"
          class="promotion-btn"
          elevation="0"
          :disabled="disabledButton"
          v-track:click="{
            category: $route.name,
            screen: 'TicketFooter',
            name: 'Show ticket promotion dialog',
          }"
          @click="openPromotionDialog"
        >
          <v-icon large>mdi-sale</v-icon>
        </v-btn>
      </template>
      <span>{{
        getTranslatedText(
          `${hasPromotion ? 'promotion.ticket.edit' : 'promotion.ticket.add'}`
        )
      }}</span>
    </v-tooltip>
    <DialogCard v-if="promotionTicketDialog.isOpen" :config="config.dialogData">
      <v-form>
        <div v-if="!onlyOnePromotionOption" class="d-flex align-center">
          <v-select
            v-model="inputs.promotionTicketId"
            :items="promotionsOptions"
            item-text="text"
            item-value="value"
            background-color="cardBackgroundSecondary"
            filled
            rounded
            class="select-promotions"
            @change="promotionTypeIdWasChanged"
          />
          <v-tooltip v-if="showDeleteButton" right>
            <template v-slot:activator="{ on, attrs }">
              <v-btn
                ref="deletePromotionBtn"
                v-bind="attrs"
                v-on="on"
                icon
                class="mb-8 ml-4"
                color="error"
                @click="resetAndSavePromotion(false)"
              >
                <v-icon>mdi-delete</v-icon>
              </v-btn>
            </template>
            <span>{{
              getTranslatedText('promotion.ticket.discount.deleteDiscount')
            }}</span>
          </v-tooltip>
        </div>
        <TicketDiscount
          v-if="showDiscountForm"
          ref="ticketDiscount"
          :form-data="config.formData"
          :type-discount="inputs.type"
          :showDeleteButton="onlyOnePromotionOption"
        />
        <TicketToCost
          v-else-if="showTicketCost"
          ref="ticketAtCost"
          :ticket="ticket"
        />
      </v-form>
    </DialogCard>
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { promotions } from '@/config/promotions'

import { getTranslatedText } from '@/tools/data'
import { discountTypes } from '@/tools/promotions'
import salesTools from '@/tools/sales'

import appActions from '@/store/app/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import tools from '@/components/shared/Ticket/Promotion/ticketPromotion.tools'
import setConfig from '@/components/shared/Ticket/Promotion/config'
import TicketToCost from '@/components/shared/Ticket/Promotion/TicketToCost'
import TicketDiscount from '@/components/shared/Ticket/Promotion/TicketDiscount'

export default {
  name: 'Promotion',
  components: {
    TicketDiscount,
    TicketToCost,
    DialogCard,
  },
  props: {
    ticket: {
      type: Object,
      required: true,
    },
    cost: {
      type: Number,
      required: true,
    },
    disabledButton: {
      type: Boolean,
      default: false,
    },
    promotionsOptions: {
      type: Array,
      default: () => [],
    },
    defaultType: {
      type: String,
      default: discountTypes.amount,
    },
  },
  data() {
    return {
      inputs: {
        discount: 0,
        type: this.defaultType,
        promotionTicketId: promotions.NONE,
      },
    }
  },
  computed: {
    ...mapState('app', {
      promotionTicketDialog: 'promotionTicketDialog',
    }),
    config() {
      return setConfig(
        {
          isOpen: this.promotionTicketDialog.isOpen,
          hasPromotion: this.hasPromotion,
          onlyOnePromotionOption: this.onlyOnePromotionOption,
          ticket: this.ticket,
          inputs: this.inputs,
          cost: this.cost,
          v: this.$v,
        },
        {
          closeDialog: this.closePromotionDialog,
          applyPromotion: this.applyPromotion,
        }
      )
    },
    onlyOnePromotionOption() {
      return this.promotionsOptions.length === 0
    },
    showDeleteButton() {
      return this.inputs.promotionTicketId !== promotions.NONE
    },
    showDiscountForm() {
      return tools.DISCOUNT_PROMOTIONS_IDS.includes(
        this.inputs.promotionTicketId
      )
    },
    showTicketCost() {
      return tools.TICKET_AT_COST_IDS.includes(this.inputs.promotionTicketId)
    },
    hasPromotion() {
      return (
        (tools.DISCOUNT_PROMOTIONS_IDS.includes(
          this.ticket.promotionTicketId
        ) &&
          this.ticket.promotion !== 0) ||
        this.ticket.promotionTicketId === promotions.SALE_TICKET_AT_COST
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', [appActions.setPromotionTicketDialogStatus]),
    openPromotionDialog() {
      tools.setInputsValueFromTicket.call(this)
      this[appActions.setPromotionTicketDialogStatus](true)
    },
    applyPromotion() {
      this.$emit('applyPromotion', tools.getPromotionTicketToSave.call(this))
      this.closePromotionDialog()
    },
    closePromotionDialog() {
      this[appActions.setPromotionTicketDialogStatus](false)
    },
    resetAndSavePromotion(needToSave = true) {
      if (!this.onlyOnePromotionOption) {
        this.inputs.promotionTicketId = promotions.NONE
      }
      this.resetDiscountPromotion()
      if (needToSave) {
        this.applyPromotion()
      }
      this.$v.inputs.discount.$reset()
    },
    promotionTypeIdWasChanged(value) {
      if (!tools.DISCOUNT_PROMOTIONS_IDS.includes(value)) {
        this.resetDiscountPromotion()
        this.$v.inputs.discount.$reset()
      }
    },
    resetDiscountPromotion() {
      this.inputs.discount = 0
      this.inputs.type = this.defaultType
    },
  },
  watch: {
    cost(newValue) {
      if (newValue === 0) {
        this.resetAndSavePromotion()
        return
      }
      if (tools.isPromotionPerAmountGreaterThanCost.call(this)) {
        tools.showHighDiscountAlertWarning.call(this)
        this.resetAndSavePromotion()
      }
    },
    'ticket.payOption': function(newValue) {
      if (salesTools.isOwnerSale(newValue)) {
        this.closePromotionDialog()
      }
    },
  },
  beforeDestroy() {
    this.closePromotionDialog()
  },
  validations() {
    return {
      inputs: {
        discount: tools.getDiscountValidation.call(this),
      },
    }
  },
}
</script>

<style scoped lang="scss">
.promotion-btn {
  border-radius: 10px;
  height: 45px !important;
  border: 1px solid rgba(0, 0, 0, 0.12) !important;
  &.v-btn.v-size--default {
    padding: 0 10px;
  }
}
.ticket-promotion-form {
  display: flex;
  align-items: center;
}
.select-promotions {
  flex: 0 3 content;
}
</style>
