<template>
  <DialogCard :config="dialogConfig.dialogData">
    <ReturnProductForm :formPayload.sync="formPayload" />
  </DialogCard>
</template>

<script>
import { isNil, find } from 'ramda'
import { mapActions, mapState } from 'vuex'

import { returnTypes } from '@/config/returnProductTypes'
import PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderReturnItemEvents'
import MLP_DB_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'

import { ticketTools } from '@/tools/purchases'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import purchasesViewActions from '@/store/purchasesView/actions.types'
import productsActions from '@/store/products/actions.types'

import setConfig from '@/components/PurchasesView/ReturnProductDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import ReturnProductForm from '@/components/PurchasesView/ReturnProductDialog/ReturnProductForm'

export default {
  name: 'ReturnProductDialog',
  components: { DialogCard, ReturnProductForm },
  data() {
    return {
      formPayload: {},
      addingProduct: false,
    }
  },
  computed: {
    ...mapState('purchasesView', {
      returnProductDialog: 'returnProductDialog',
      selectedPurchase: 'selectedPurchase',
    }),
    isAcceptButtonDisabled() {
      return !this.formPayload.isValid
    },
    dialogHeight() {
      if (isNil(this.formPayload) || isNil(this.formPayload.inputs)) return 430
      return this.formPayload.inputs.returnType === returnTypes.DISCOUNT
        ? 430
        : 510
    },
    dialogConfig() {
      return setConfig(
        {
          dialog: {
            dialogHeight: this.dialogHeight,
            isOpen: this.returnProductDialog.isOpen,
            hidden: this.returnProductDialog.hidden,
            isAcceptButtonDisabled: this.isAcceptButtonDisabled,
          },
        },
        {
          dialog: {
            onCloseDialog: this.onCloseDialog,
            onSubmitForm: this.onSubmitForm,
          },
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('products', [
      productsActions.setMlpFilteredProducts,
      productsActions.setProductsOrSuperCategoriesFetching,
    ]),
    ...mapActions('purchasesView', [
      purchasesViewActions.setReturnProductDialogStatus,
    ]),
    onCloseDialog() {
      this[purchasesViewActions.setReturnProductDialogStatus]({ isOpen: false })
    },
    addNewReturnProduct() {
      const newTicketReturnItem = ticketTools.buildTicketReturnItem(
        this.formPayload,
        this.selectedPurchase._id
      )
      rendererEventsService.send(
        PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.channel,
        {
          event: PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.events.add.name,
          data: {
            returnItem: newTicketReturnItem,
          },
        }
      )
      this.onCloseDialog()
    },
    editProductFromTicket() {
      const updatedTicketReturnItem = ticketTools.buildTicketReturnProductUpdated(
        this.formPayload,
        this.selectedPurchase._id
      )
      rendererEventsService.send(
        PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.channel,
        {
          event: PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.events.update.name,
          data: {
            returnItemUpdated: updatedTicketReturnItem,
          },
        }
      )
      this.onCloseDialog()
    },
    onSubmitForm() {
      if (this.isAcceptButtonDisabled || this.addingProduct) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'ReturnProductDialog',
        name: 'Submit',
      })
      this.addingProduct = true
      const { inputs } = this.formPayload
      const returnProductExist = find(
        item => item.productReturnId === inputs.productToReturn.id
      )(this.selectedPurchase.returnItems)
      if (!isNil(returnProductExist)) {
        this.$track({
          type: 'system',
          action: 'submit_return_product',
          category: 'Purchases',
          screen: 'ReturnProductDialog',
          name: 'Edit return product from ticket',
        })
        this.editProductFromTicket()
        return
      }
      this.$track({
        type: 'system',
        action: 'submit_return_product',
        category: 'Purchases',
        screen: 'ReturnProductDialog',
        name: 'Add return product',
      })
      this.addNewReturnProduct()
    },
    async purchaseOrderReturnItemListener(event, payload) {
      const purchaseOrderReturnItemEvents =
        PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.events
      const replies = {
        [purchaseOrderReturnItemEvents.add.replies.success]: () =>
          (this.addingProduct = false),
        [purchaseOrderReturnItemEvents.add.replies.error]: () =>
          (this.addingProduct = false),
      }
      if (payload.event in replies) replies[payload.event]()
    },
    async mlpApiListener(event, payload) {
      const replies = {
        [MLP_DB_API_EVENTS.events.findByPropertiesLikes.replies
          .success]: () => {
          this[productsActions.setMlpFilteredProducts](payload.data)
          this[productsActions.setProductsOrSuperCategoriesFetching](false)
        },
        [MLP_DB_API_EVENTS.events.findByPropertiesLikes.replies.error]: () => {
          this[productsActions.setProductsOrSuperCategoriesFetching](false)
          notificationsService.showError(payload.error, this.$vuetify.lang, {
            timeout: 8000,
          })
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseOrderReturnItemListener
    )
    rendererEventsService.subscribe(
      MLP_DB_API_EVENTS.replyChannel,
      this.mlpApiListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseOrderReturnItemListener
    )
    rendererEventsService.removeListener(
      MLP_DB_API_EVENTS.replyChannel,
      this.mlpApiListener
    )
  },
}
</script>
