<template>
  <DialogCard :config="dialogConfig.dialogData">
    <template #titleRight v-if="selectedProduct.product.isGramaje === 1">
      <v-spacer />
      <WeightScaleStatus />
    </template>
    <ProductTriangulationForm
      :key="`triangulation-form-${selectedProduct?.product.id || 'noProduct'}`"
      :product="selectedProduct.product"
      :onEnterEvent="onSubmitForm"
      :fromTicket="selectedProduct.fromTicket"
    />
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { find, isNil, values } from 'ramda'

import { testMode } from '@/config/env'
import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import PURCHASE_ORDER_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderItemEvents'
import { storeInventory } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'
import { formatNumberFromDb, formatNumberToDb } from '@/tools/numbersFormat'
import { ticketTools } from '@/tools/purchases'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'

import setDialogConfig from '@/components/PurchasesView/ProductTriangulationDialog/config'

import DialogCard from '@/components/shared/DialogCard'
import ProductTriangulationForm from '@/components/PurchasesView/ProductTriangulationDialog/ProductTriangulationForm'
import WeightScaleStatus from '@/components/MainView/WeightScaleStatus.vue'

export default {
  name: 'ProductTriangulationDialog',
  components: { WeightScaleStatus, DialogCard, ProductTriangulationForm },
  data() {
    return {
      formPayload: {},
      isAcceptButtonDisabled: true,
      isEditForm: false,
      addingProduct: false,
    }
  },
  computed: {
    ...mapState('purchasesView', [
      'productTriangulationDialog',
      'selectedProduct',
      'selectedPurchase',
      'tourEnabled',
    ]),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    dialogHeight() {
      if (this.selectedProduct?.product?.isGeneric === 1) return 360
      if (this.selectedProduct?.product?.factor > 1) return 730
      return 640
    },
    dialogConfig() {
      return setDialogConfig(
        {
          dialog: {
            isOpen: this.productTriangulationDialog.isOpen,
            isAcceptButtonDisabled: this.isAcceptButtonDisabled,
            dialogHeight: this.dialogHeight,
          },
          isGenericProduct: this.selectedProduct?.product?.isGeneric === 1,
          isEditForm: this.isEditForm,
        },
        {
          dialog: {
            onCloseDialog: this.onCloseDialog,
            onSubmitForm: this.onSubmitForm,
          },
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('purchasesView', values(purchasesViewActions)),
    onCloseDialog() {
      if (this.tourEnabled) this.$root.$emit('purchase-cancel-tour')
      this.$root.$emit('reset')
      this.resetScannerStatus(this.defaultProductsFilter)
      this[purchasesViewActions.setSelectedProduct](null)
      this[purchasesViewActions.setProductTriangulationDialogStatus](false)
    },
    editProductFromTicket() {
      const updatedTicketItem = ticketTools.buildTicketProductUpdateByType(
        this.formPayload,
        this.selectedPurchase._id
      )
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event: PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.update.name,
        data: {
          purchaseOrderId: this.selectedPurchase._id,
          purchaseItemUpdated: updatedTicketItem,
        },
      })
      this[purchasesViewActions.setSelectedProduct](null)
      this[purchasesViewActions.setProductTriangulationDialogStatus](false)
    },
    addNewProductToTicket() {
      const newTicketItem = ticketTools.buildTicketItem(
        this.formPayload,
        this.selectedPurchase._id
      )
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event: PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.add.name,
        data: {
          purchaseItem: newTicketItem,
        },
      })
      this[purchasesViewActions.setSelectedProduct](null)
      this[purchasesViewActions.setProductTriangulationDialogStatus](false)
    },
    onSubmitForm() {
      if (this.isAcceptButtonDisabled || this.addingProduct) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'ProductTriangulationDialog',
        name: 'Submit',
      })
      this.addingProduct = true
      const { product } = this.selectedProduct
      const productExist = find(item => item.upc === product.upc)(
        this.selectedPurchase.items
      )
      const { productType, inputs } = this.formPayload
      const dbPrice = !isNil(product.dbPrice)
        ? formatNumberFromDb(product.dbPrice)
        : formatNumberFromDb(product.price)
      const dbStock =
        product.isGramaje || product.isGeneric || product.factor > 1
          ? product.quantity
          : product.stock
      this.$emit('reset')
      this.resetScannerStatus('clear')
      this[purchasesViewActions.setSearchTermFilter](null)
      this.updatePrices(
        productType,
        inputs.price,
        inputs.pricePack,
        dbPrice,
        product
      )
      this.updateExistences(
        dbStock,
        inputs.existences,
        inputs.existencesPack,
        product
      )
      if (!isNil(productExist)) {
        this.$track({
          type: 'system',
          action: 'submit_product',
          category: 'Purchases',
          screen: 'ProductTriangulationDialog',
          name: 'Edit product from ticket',
        })
        this.editProductFromTicket()
        return
      }
      this.$track({
        type: 'system',
        action: 'submit_product',
        category: 'Purchases',
        screen: 'ProductTriangulationDialog',
        name: 'Add product',
      })
      this.addNewProductToTicket()
    },
    updatePrices(productType, price, pricePack, dbPrice, product) {
      if (productType !== 'isOpenProductPackage' && dbPrice !== price) {
        rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
          event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
          data: {
            productToUpdated: {
              id: product.id,
              data: mapStoreObject(
                {
                  isPriceChanged: 1,
                  price: formatNumberToDb(price),
                },
                storeInventory,
                true
              ),
            },
          },
        })
      }
      if (
        productType === 'isOpenProductPackage' &&
        (dbPrice !== pricePack ||
          formatNumberFromDb(product.unitProdPrice) !== price)
      ) {
        rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
          event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
          data: {
            productToUpdated: {
              id: product.id,
              data: mapStoreObject(
                {
                  isPriceChanged: 1,
                  price: formatNumberToDb(pricePack),
                  unitProdPrice: formatNumberToDb(price),
                },
                storeInventory,
                true
              ),
            },
          },
        })
      }
    },
    updateExistences(dbStock, existences, existencesPack, product) {
      const inputsExistences = this.getTotalExistences(
        product.factor,
        existences,
        existencesPack
      )
      if (dbStock !== inputsExistences) {
        rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
          event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
          data: {
            productToUpdated: {
              id: product.id,
              data: mapStoreObject(
                {
                  quantity: inputsExistences,
                },
                storeInventory,
                true
              ),
            },
            username: this.selectedUser.name,
          },
        })
      }
    },
    getTotalExistences(factor, existences, existencesPack) {
      if (factor <= 1) {
        return existences || 0
      }
      return Math.floor(existencesPack) * factor + Math.floor(existences)
    },
    resetScannerStatus(group) {
      switch (group) {
        case 'search-control':
          if (this.isScannerActive === false)
            this[appActions.updateScannerStatus]()
          break
        case 'clear':
          this[purchasesViewActions.setSearchTermFilter](null)
          this[purchasesViewActions.setGroupFilter](this.defaultProductsFilter)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
        default:
          group === 'superCategories'
            ? this[purchasesViewActions.setGroupFilter]('superCategories')
            : this[purchasesViewActions.setGroupFilter](group)
          if (this.isScannerActive === true)
            this[appActions.updateScannerStatus]()
          break
      }
    },
    async purchaseOrderItemListener(event, payload) {
      const purchaseOrderItemEvents = PURCHASE_ORDER_ITEM_DB_API_EVENTS.events
      const replies = {
        [purchaseOrderItemEvents.add.replies.success]: () =>
          (this.addingProduct = false),
        [purchaseOrderItemEvents.add.replies.error]: () =>
          (this.addingProduct = false),
        [purchaseOrderItemEvents.update.replies.success]: () =>
          (this.addingProduct = false),
        [purchaseOrderItemEvents.update.replies.error]: () =>
          (this.addingProduct = false),
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      PURCHASE_ORDER_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseOrderItemListener
    )
  },
  mounted() {
    this.$barcodeScanner.destroy()
    const productExist = find(
      item => item.upc === this.selectedProduct.product.upc
    )(this.selectedPurchase.items)
    this.isEditForm = !isNil(productExist)
    this.$root.$on('by-weight-selected-product', payload => {
      if (payload.isValid === false) {
        this.isAcceptButtonDisabled = true
        return
      }
      this.formPayload = payload
      this.isAcceptButtonDisabled = false
    })
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
    rendererEventsService.removeListener(
      PURCHASE_ORDER_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseOrderItemListener
    )
    this[purchasesViewActions.setProductTriangulationDialogStatus](false)
  },
}
</script>
