<template>
  <div v-if="selectedPurchase" class="ticket-container">
    <ProductTriangulationDialog v-if="productTriangulationDialog.isOpen" />
    <AddNewProductDialog v-if="newProductDialog.isOpen" />
    <ByWeightProductDialog v-if="byWeightProductDialog.isOpen" />
    <ConfirmPurchaseDialog v-if="confirmPurchaseDialog.isOpen" />
    <OverCreditLimitDialog v-if="overCreditLimitDialog.isOpen" />
    <v-card
      flat
      color="cardBackgroundSecondary"
      height="100%"
      style="border-radius: 10px"
      class="d-flex flex-column pt-3 pb-4"
    >
      <ScrollContainer
        height="98%"
        class="mb-4 pr-5"
        :scroll-active-style="{ 'padding-right': '0 !important' }"
      >
        <TicketProduct
          v-for="product in selectedPurchase.items.slice().reverse()"
          :key="product.uniqueId"
          :product="product"
          :ticketCols="ticketCols"
        />
        <TicketReturnProduct
          v-for="returnProduct in selectedPurchase.returnItems
            .slice()
            .reverse()"
          :key="returnProduct.uniqueId"
          :returnProduct="returnProduct"
          :ticketCols="ticketCols"
        />
      </ScrollContainer>
      <TicketFooter class="mt-auto px-6" />
    </v-card>
  </div>
</template>

<script>
import { mapState } from 'vuex'

import TicketProduct from '@/components/PurchasesView/Ticket/TicketProduct'
import TicketReturnProduct from '@/components/PurchasesView/Ticket/TicketReturnProduct'
import ProductTriangulationDialog from '@/components/PurchasesView/ProductTriangulationDialog'
import TicketFooter from '@/components/PurchasesView/Ticket/TicketFooter'
import ConfirmPurchaseDialog from '@/components/PurchasesView/ConfirmPurchaseDialog'
import ByWeightProductDialog from '@/components/PurchasesView/ByWeightProductDialog'
import OverCreditLimitDialog from '@/components/PurchasesView/OverCreditLimitDialog'
import AddNewProductDialog from '@/components/AddNewProductDialog'
import ScrollContainer from '@/components/shared/ScrollContainer'

export default {
  name: 'PurchaseTicket',
  components: {
    ScrollContainer,
    TicketProduct,
    TicketReturnProduct,
    ProductTriangulationDialog,
    TicketFooter,
    ConfirmPurchaseDialog,
    ByWeightProductDialog,
    OverCreditLimitDialog,
    AddNewProductDialog,
  },
  props: {
    ticketCols: {
      type: Number,
      default: 4,
    },
  },
  computed: {
    ...mapState('purchasesView', [
      'selectedPurchase',
      'productTriangulationDialog',
      'confirmPurchaseDialog',
      'byWeightProductDialog',
      'overCreditLimitDialog',
      'newProductDialog',
    ]),
  },
  methods: {
    getTranslatedText(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
  },
}
</script>

<style lang="scss" scoped>
.ticket-container {
  background: var(--v-mainBackground-base);
  height: calc(100vh - 200px);
}
</style>
