<template>
  <div>
    <ProductToReturnForm :inputs="inputs" :productType="productType" />
    <ReturnTypeForm :inputs="inputs" />
  </div>
</template>

<script>
import { isNil, concat } from 'ramda'
import { mapActions, mapGetters, mapState } from 'vuex'
import { required } from 'vuelidate/lib/validators'

import { returnTypes } from '@/config/returnProductTypes'
import productsVariables from '@/config/products'
import { testMode } from '@/config/env'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'

import { formatNumberFromDb } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import productsActions from '@/store/products/actions.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'

import ProductToReturnForm from '@/components/PurchasesView/ReturnProductDialog/ReturnProductForm/ProductToReturnForm'
import ReturnTypeForm from '@/components/PurchasesView/ReturnProductDialog/ReturnProductForm/ReturnTypeForm'
import {
  setDefaultValidators,
  setMoneyValidator,
} from '@/components/PurchasesView/ReturnProductDialog/ReturnProductForm/tools'

export default {
  name: 'ReturnProductForm',
  components: { ProductToReturnForm, ReturnTypeForm },
  props: {
    formPayload: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      inputs: {
        productToReturn: null,
        unitsToReturn: 0,
        costToReturn: 0,
        returnType: returnTypes.DISCOUNT,
        amountToDiscount: 0,
        productToChange: null,
        unitsToChange: 0,
        costToChange: 0,
        currentFocus: '',
      },
      productType: '',
      barcode: '',
    }
  },
  computed: {
    ...mapState('products', {
      mlp: state => state.data.mlp,
    }),
    ...mapState('purchasesView', ['returnProductDialog']),
    ...mapGetters('products', ['getOnlyStockedProducts', 'getFilteredData']),
    productChangeList() {
      return isNil(this.inputs.productToReturn)
        ? concat(this.getFilteredData, this.mlp)
        : concat(
            this.getFilteredData.filter(
              product => product.id !== this.inputs.productToReturn.id
            ),
            this.mlp
          )
    },
  },

  methods: {
    ...mapActions('products', [
      productsActions.setProductsOrSuperCategoriesFetching,
      productsActions.addProductFromMLP,
      productsActions.resetMlpFilteredProducts,
    ]),
    ...mapActions('purchasesView', [
      purchasesViewActions.setHiddenReturnProductDialog,
      purchasesViewActions.setAddProductDialogStatus,
    ]),
    getFormValues() {
      return {
        inputs: this.inputs,
        isValid: !this.$v.$invalid,
      }
    },
    setProductType() {
      const product = this.inputs.productToReturn
      if (isNil(product)) return ''
      const isOpenProduct = product.factor > 0 || product.isOpenProduct === 1
      const isPieceProduct = isOpenProduct === false && product.isGramaje === 0
      const isByWeightProduct =
        isOpenProduct === false && product.isGramaje === 1
      if (isPieceProduct) return 'isPieceProduct'
      if (isByWeightProduct) return 'isByWeightProduct'
      if (isOpenProduct) return 'isOpenProductPackage'
    },
    onSelectProductToReturn() {
      const scannedProduct = this.getOnlyStockedProducts.find(
        product => product.upc === this.barcode
      )
      if (isNil(scannedProduct)) {
        notificationsService.showWarning(
          'notification.purchases.returnProduct.productNotFound',
          this.$vuetify.lang
        )
        return
      }
      this.inputs.productToReturn = scannedProduct
      this.$v.inputs.productToReturn.$touch()
    },
    onSelectProductToChange() {
      if (this.barcode === this.inputs.productToReturn.upc) return
      const scannedProduct = this.productChangeList.find(
        product => product.upc === this.barcode
      )
      if (
        isNil(scannedProduct) ||
        (!isNil(scannedProduct.isStoreInventory) &&
          scannedProduct.isStoreInventory !== 1)
      ) {
        this[productsActions.setProductsOrSuperCategoriesFetching](true)
        rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
          event: ADD_PRODUCT_EVENTS.events.addProductFromMLP.name,
          data: {
            item: { property: 'upc_code', value: this.barcode, limit: 1 },
            fromReturnProductDialog: true,
          },
        })
        return
      }
      this.inputs.productToChange = scannedProduct
      this.$v.inputs.productToChange.$touch()
    },
    onBarcodeScanned(barcode) {
      this.barcode = barcode
      const { productToReturn, returnType } = this.inputs
      if (isNil(productToReturn)) {
        this.onSelectProductToReturn()
        return
      }
      switch (returnType) {
        case returnTypes.DISCOUNT:
          this.onSelectProductToReturn()
          break
        case returnTypes.CHANGE_PRODUCT:
          this.onSelectProductToChange()
          break
      }
    },
    onProductAddedFromMLP(data) {
      let { newProduct } = data
      this[productsActions.addProductFromMLP]({
        newProduct: newProduct,
        currentView: 'purchasesView',
      })
      this[productsActions.setProductsOrSuperCategoriesFetching](false)
      this.inputs.productToChange = newProduct
      notificationsService.showInfo(
        'productsView.listView.messages.newProductAdded',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
    },
    addProductFromMLPListener(event, payload) {
      const events = ADD_PRODUCT_EVENTS.events
      const replies = {
        [events.addProductFromMLP.replies.successFromReturnProductDialog]: () =>
          this.onProductAddedFromMLP(payload.data),
        [events.addProductFromMLP.replies.errorFromReturnProductDialog]: () => {
          this[productsActions.setProductsOrSuperCategoriesFetching](false)
          if (payload.data.error.message === 'newProduct') {
            this[purchasesViewActions.setHiddenReturnProductDialog](true)
            this[purchasesViewActions.setAddProductDialogStatus]({
              isOpen: true,
              fromReturnProductDialog: true,
              barcode: this.barcode,
            })
            return
          }
          notificationsService.showError(
            payload.data.errorMsg,
            this.$vuetify.lang,
            {
              timeout: 8000,
            }
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  watch: {
    $v: {
      handler() {
        this.$emit('update:formPayload', this.getFormValues())
      },
      deep: true,
    },
    'inputs.productToReturn': function() {
      this.productType = this.setProductType()
    },
    'returnProductDialog.hidden': function() {
      this.$barcodeScanner.init(this.onBarcodeScanned)
    },
  },
  validations() {
    const maxStock = isNil(this.inputs.productToReturn)
      ? 0
      : this.inputs.productToReturn.quantity
    let validations = {
      inputs: {
        productToReturn: {
          required,
        },
        unitsToReturn: setDefaultValidators(maxStock),
        costToReturn: setMoneyValidator(1000000, 2),
        returnType: {
          required,
        },
      },
    }
    switch (this.inputs.returnType) {
      case returnTypes.DISCOUNT:
        validations.inputs = {
          ...validations.inputs,
          amountToDiscount: setMoneyValidator(1000000, 2),
        }
        break
      case returnTypes.CHANGE_PRODUCT:
        validations.inputs = {
          ...validations.inputs,
          productToChange: { required },
          unitsToChange: setDefaultValidators(
            productsVariables.STOCK_MAX_VALUE
          ),
          costToChange: setMoneyValidator(1000000, 2),
        }
        break
    }
    return validations
  },
  created() {
    if (testMode) return
    this.$barcodeScanner.init(this.onBarcodeScanned)
    this.$root.$on(
      'productAddedFromMatch',
      (productUPC, fromReturnProductDialog) => {
        if (fromReturnProductDialog) {
          this.onBarcodeScanned(productUPC)
        }
      }
    )
    this.$root.$on('new-product-from-return-product-dialog', payload => {
      this.inputs.productToChange = payload.newProduct
    })
    rendererEventsService.subscribe(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductFromMLPListener
    )
  },
  beforeMount() {
    if (!this.returnProductDialog.isFromTicket) return
    const { returnProduct } = this.returnProductDialog
    const {
      productReturnId,
      productReturnQuantity,
      productReturnCost,
      returnType,
      productChangeId,
      productChangeQuantity,
      amountToDiscount,
    } = returnProduct
    const product = this.getOnlyStockedProducts.find(
      stockedProduct => stockedProduct.id === productReturnId
    )
    this.inputs.productToReturn = product
    this.inputs.unitsToReturn = productReturnQuantity
    this.inputs.costToReturn = formatNumberFromDb(productReturnCost)
    this.inputs.returnType = returnType
    switch (returnType) {
      case returnTypes.DISCOUNT: {
        this.inputs.amountToDiscount = formatNumberFromDb(amountToDiscount)
        break
      }
      case returnTypes.CHANGE_PRODUCT: {
        const productChange = this.productChangeList.find(
          stockedProduct => stockedProduct.id === productChangeId
        )
        this.inputs.productToChange = productChange
        this.inputs.unitsToChange = productChangeQuantity
        const gramajeReturn = product.isGramaje === 1 ? 1000 : 1
        const gramajeChange = productChange.isGramaje === 1 ? 1000 : 1
        const totalCostReturn =
          (this.inputs.unitsToReturn / gramajeReturn) * this.inputs.costToReturn
        this.inputs.costToChange =
          totalCostReturn / (this.inputs.unitsToChange / gramajeChange)
      }
    }
  },
  beforeDestroy() {
    if (!testMode) {
      this.$barcodeScanner.destroy()
    }
    this.$root.$emit('enable-scanner', {})
    this.$root.$off(
      'productAddedFromMatch',
      (productUPC, fromReturnProductDialog) => {
        if (fromReturnProductDialog) {
          this.onBarcodeScanned(productUPC)
        }
      }
    )
    this[productsActions.resetMlpFilteredProducts]([])
    rendererEventsService.removeListener(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductFromMLPListener
    )
  },
}
</script>
