import { storeInventory } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'
import {
  formatNumberFromDb,
  formatNumberToCurrency,
} from '@/tools/numbersFormat'

import {
  setDecimalValue,
  getPackageMarginValue,
} from '@/components/ProductDetail/DetailsTab/tools'
import dialogConfig from '@/components/ProductDetail/DetailsTab/costWarningDialogConfig'

const setConfig = (state, methods) => ({
  state,
  methods,
  singleWidgets: {
    firstSection: [
      {
        id: 'packagePrice',
        type: 'SingleEditDataWidget',
        value: state.product.price,
        valueTextColor: 'textPrimary',
        valueLimit: state.limits.maxValuePackagePrice,
        label: 'productsView.details.price',
        labelIcon: 'mdi-pencil',
        reverse: false,
        onInputChange: newValue => setDecimalValue(methods, 'price', newValue),
        onInputFinishEdit: () => {
          methods.track({
            type: 'interaction',
            action: 'click',
            category: state.routeName,
            screen: 'ProductDetails',
            name: `Save package price`,
          })
          methods.updateDatabase({
            id: state.product.id,
            data: mapStoreObject(
              { price: state.product.price },
              storeInventory,
              true
            ),
          })
        },
        numberFormatter: value => formatNumberFromDb(value),
        textFormatter: value => formatNumberToCurrency(value),
      },
    ],
    secondSection: [
      {
        id: 'packageCost',
        type: 'SingleEditDataWidget',
        value: state.product.cost,
        valueTextColor: 'textPrimary',
        valueLimit: state.limits.maxValuePackagePrice,
        label: 'productsView.details.averageCost',
        labelIcon: 'mdi-pencil',
        reverse: true,
        dialogConfig: dialogConfig,
        warningMessageTitle: 'productsView.details.warningMsgChangingCostTitle',
        warningMessages: [
          'productsView.details.warningMsgChangingCost',
          'productsView.details.warningMsgChangingCostB',
        ],
        onInputChange: newValue => setDecimalValue(methods, 'cost', newValue),
        onInputFinishEdit: () => {
          methods.track({
            type: 'interaction',
            action: 'click',
            category: state.routeName,
            screen: 'ProductDetails',
            name: `Save package cost`,
          })
          methods.updateDatabase({
            id: state.product.id,
            data: mapStoreObject(
              { cost: state.product.cost },
              storeInventory,
              true
            ),
          })
        },
        numberFormatter: value => formatNumberFromDb(value),
        textFormatter: value => formatNumberToCurrency(value),
      },
      {
        id: 'packageMargin',
        type: 'SingleDataWidget',
        value: getPackageMarginValue(state.product.price, state.product.cost),
        label: 'productsView.details.averageMargin',
        labelIcon: 'mdi-chart-bar',
        reverse: true,
      },
    ],
  },
})

export default setConfig
