<template>
  <v-stepper v-model="currentStep" class="stepper">
    <!-- Stepper header -->
    <v-stepper-header non-linear class="stepper__header">
      <!-- Dynamic steps -->
      <div v-for="(step, index) in config.steps" :key="step.id">
        <v-stepper-step
          :editable="step.editable"
          :step="index + 1"
          :complete="step.complete"
        >
          <FormatedText intl :value="step.name" />{{
            selectors[step.id].selected.name
          }}
        </v-stepper-step>
      </div>
      <v-divider v-if="config.finalStep.enable === true"></v-divider>
      <!-- Final step -->
      <v-stepper-step
        v-if="config.finalStep.enable === true"
        :complete="currentStep > totalSteps"
        :step="totalSteps"
      >
        <FormatedText intl :value="config.finalStep.name" />
      </v-stepper-step>
    </v-stepper-header>
    <!-- Steps content -->
    <v-stepper-items>
      <div v-for="(step, index) in config.steps" :key="step.id">
        <v-stepper-content :step="index + 1">
          <component
            :is="step.component"
            :data="selectors[step.id].data"
            :onClickChip="onClickSelector"
          />
        </v-stepper-content>
      </div>
      <!-- Final step content -->
      <v-stepper-content :step="totalSteps">
        <v-scroll-x-reverse-transition>
          <component
            v-if="currentStep === totalSteps && product !== null"
            :key="`finalStep-${reloadFinalStep}`"
            :is="config.finalStep.component"
            :product="product"
            :onEnterEvent="config.onFormEnterEvent"
            :fromTicket="false"
          />
        </v-scroll-x-reverse-transition>
        <Alert
          v-if="currentStep === totalSteps && product === null"
          :config="config.errorAlertConfig"
          :show="productError"
        />
      </v-stepper-content>
    </v-stepper-items>
  </v-stepper>
</template>

<script>
import { isNil, prop, propEq, find, map, isEmpty } from 'ramda'

import { captureException } from '@/tools/exceptions'

import FormatedText from '@/components/shared/FormattedText'
import Alert from '@/components/shared/Alert'

export default {
  name: 'StepperSelector',
  components: { FormatedText, Alert },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      currentStep: 1,
      selectors: {},
      reloadFinalStep: 1,
    }
  },
  computed: {
    totalSteps() {
      return this.config.finalStep.enable === true
        ? this.config.steps.length + 1
        : this.config.steps.length
    },
    selectorsCount() {
      return this.config.steps.length
    },
    userSelection() {
      const selectors = map(item => `${item.name}`, this.selectors)
      return selectors
    },
    getProductUPC() {
      const upc = isEmpty(this.selectors.type.selected.children)
        ? this.selectors.type.selected.upc
        : this.selectors.brand.selected.upc
      return upc
    },
    product() {
      return this.config.data.product
    },
    productError() {
      return this.config.data.productError
    },
  },
  methods: {
    setSelectors() {
      this.config.steps.forEach((step, index) => {
        index === 0
          ? this.$set(this.selectors, step.id, {
              data: this.config.data.selectedByWeightCategory,
              selected: {},
            })
          : this.$set(this.selectors, step.id, {
              data: {},
              selected: {},
            })
      })
    },
    getSelectorId(index) {
      return this.config.steps[index].id
    },
    onClickSelector(selectedItem) {
      const thereChildren =
        !isNil(prop('children', selectedItem)) &&
        selectedItem.children.length > 0
      const selectorIndex = this.currentStep - 1

      this.setSelectorState('editable', true, selectorIndex)
      this.setSelectorState('complete', true, selectorIndex)
      this.selectors[this.getSelectorId(selectorIndex)].selected = selectedItem

      // Assign data to next step
      if (thereChildren === true && this.currentStep < this.selectorsCount) {
        this.selectors[this.getSelectorId(this.currentStep)].data = find(
          propEq('id', selectedItem.id)
        )(this.selectors[this.getSelectorId(selectorIndex)].data.children)
        this.currentStep = this.currentStep + 1
        return
      }
      // No children data
      if (this.currentStep < this.selectorsCount) {
        // Reset selectors
        do {
          this.selectors[this.getSelectorId(this.currentStep)].selected = {}
          this.setSelectorState('editable', false, this.currentStep)
          this.setSelectorState('complete', false, this.currentStep)
          this.currentStep = this.currentStep + 1
        } while (this.currentStep < this.totalSteps - 1)
      }
      this.currentStep = this.totalSteps
    },
    setSelectorState(prop, value, selectorIndex) {
      this.config.steps[selectorIndex][prop] = value
    },
    checkIfTypeHasbrands(type) {
      const brands = type.children
      if (brands.length <= 0) {
        this.selectors.type.selected = type
        this.setSelectorState('editable', false, 0)
        this.setSelectorState('complete', true, 0)
        this.currentStep = this.totalSteps
      }
    },
    launchFinalStepHook() {
      try {
        return this.config.finalStep.hook(this.getProductUPC)
      } catch (error) {
        captureException(error)
      }
    },
  },
  watch: {
    currentStep: async function(newValue) {
      if (newValue === this.totalSteps) {
        this.launchFinalStepHook()
      }
    },
  },
  created() {
    this.setSelectors()
  },
  mounted() {
    const types = this.selectors.type.data.children
    if (!isNil(types) && types.length === 1) this.checkIfTypeHasbrands(types[0])
    this.$root.$on(
      'selectedProductCostWasUpdated',
      () => (this.reloadFinalStep += 1)
    )
  },
  beforeDestroy() {
    this.$root.$off('selectedProductCostWasUpdated')
  },
}
</script>

<style lang="scss" scoped>
.stepper {
  box-shadow: none !important;
  .stepper__header {
    box-shadow: none !important;
  }
}
</style>
