<template>
  <v-chip-group v-model="selectedChip" active-class="primary" column>
    <span v-for="chip in data.children" :key="chip.name">
      <v-chip @click="onClickChip(chip)" :ref="chip.name">
        {{ chip.name }}
      </v-chip>
    </span>
  </v-chip-group>
</template>

<script>
export default {
  name: 'ChipsGroup',
  props: {
    data: {
      type: Object,
      required: true,
    },
    onClickChip: {
      type: Function,
      required: true,
    },
  },
  data() {
    return {
      selectedChip: null,
    }
  },
}
</script>
