<template>
  <v-card-title class="large-icon-title header" id="product-detail-card-header">
    <div>
      <div class="flex">
        <FormattedText type="text-h6" class="d-inline-block">
          {{ selectedProduct ? selectedProduct.name : null }}
        </FormattedText>
        <div class="d-inline-block">
          <v-tooltip bottom v-if="productsSimilarUpc[selectedProduct.id]">
            <template v-slot:activator="{ on }">
              <v-btn
                v-on="on"
                color="warning"
                icon
                class="ml-1 similar-products-button"
                @click.prevent.stop="showSimilarProductsUpc(selectedProduct)"
                v-track:click="{
                  category: $route.name,
                  screen: 'ProductDetails',
                  name: 'Show similar products upc',
                }"
              >
                <v-icon>mdi-alert</v-icon>
              </v-btn>
            </template>
            <span>{{ getTranslatedText('productCard.similarUpc') }}</span>
          </v-tooltip>
          <v-btn
            icon
            class="ml-1 favorite-button"
            @click="changeFavoriteStatus()"
          >
            <v-icon color="cardFavorite">
              {{ iconIsFav }}
            </v-icon>
          </v-btn>

          <v-tooltip bottom v-if="productIsPromoted">
            <template v-slot:activator="{ on }">
              <v-btn
                v-on="on"
                icon
                class="ml-1 favorite-button"
                @click="goToPromotions"
              >
                <v-icon color="primary">
                  mdi-sale
                </v-icon>
              </v-btn>
            </template>
            <span>{{
              getTranslatedText('productsView.details.goToPromotion')
            }}</span>
          </v-tooltip>
        </div>
      </div>
      <FormattedText className="font-weight-light" class="mt-n1" type="text-h6">
        {{ selectedProduct.alternativeName }}
      </FormattedText>
      <FormattedText
        v-if="selectedProduct.factor <= 0 || !selectedProduct.isOpenGramaje"
        className="font-italic"
        color="textSecondary"
        type="text-caption"
      >
        {{
          `${getTranslatedText(
            'productsView.details.soldBy'
          )} ${getTranslatedText(soldBy).toLowerCase()}`
        }}
      </FormattedText>
      <v-radio-group
        ref="isGramajeRadioGroup"
        v-if="selectedProduct.isOpenGramaje"
        :value="selectedProduct.isGramaje.toString()"
        @change="onIsGramajeRadioChange"
        row
        dense
      >
        <template v-slot:label>
          <div>
            {{ getTranslatedText('productsView.details.soldBy') }}
          </div>
        </template>
        <v-radio value="0" color="accent">
          <template v-slot:label>
            <div class="text-subtitle-1">
              {{ getTranslatedText('productsView.details.piece') }}
            </div>
          </template>
        </v-radio>
        <v-radio value="1" color="accent">
          <template v-slot:label>
            <div class="text-subtitle-1">
              {{ getTranslatedText('productsView.details.byWeight') }}
            </div>
          </template>
        </v-radio>
      </v-radio-group>
      <v-radio-group
        v-if="selectedProduct.factor > 0"
        :value="selectedProduct.factorSalesBy.toString()"
        @change="onFactorSalesByRadioChange"
        row
        dense
      >
        <template v-slot:label>
          <div>
            {{ getTranslatedText('productsView.details.soldBy') }}
          </div>
        </template>
        <v-radio value="0" color="accent">
          <template v-slot:label>
            <div class="text-subtitle-1">
              {{ getTranslatedText('productsView.details.package') }}
            </div>
          </template>
        </v-radio>
        <v-radio value="1" color="accent">
          <template v-slot:label>
            <div class="text-subtitle-1">
              {{ getTranslatedText('productsView.details.piece') }}
            </div>
          </template>
        </v-radio>
        <v-radio value="2" color="accent">
          <template v-slot:label>
            <div class="text-subtitle-1">
              {{ getTranslatedText('productsView.details.soldByAsk') }}
            </div>
          </template>
        </v-radio>
      </v-radio-group>
      <div class="d-flex mt-1" v-if="selectedProduct.isGramaje === 0">
        <v-icon color="accent" class="pr-1">mdi-barcode-scan</v-icon>
        <FormattedText className="font-weight-thin">
          {{ selectedProduct.upc.toString() }}
        </FormattedText>
      </div>
    </div>

    <div class="product-icon" :style="cssVars">
      <div>
        <CategoryIcon
          :categoryName="categoryName"
          :iconSize="{ x: 45, y: 45 }"
        />
      </div>
      <div>
        <v-tooltip top>
          <template v-slot:activator="{ on, attrs }">
            <div class="stat-widget" v-bind="attrs" v-on="on">
              <FormattedText
                :value="stock"
                type="text-caption"
                color="textOverWhiteBackground"
                className="font-weight-bold"
              />
            </div>
          </template>
          <span>Stock</span>
        </v-tooltip>
      </div>
    </div>
  </v-card-title>
</template>

<script>
import { isNil } from 'ramda'
import { mapActions, mapGetters, mapState } from 'vuex'

import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import { storeInventory } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'
import { getActionsTypes, getViewStore } from '@/tools/view'

import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'

import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'
import FormattedText from '@/components/shared/FormattedText'
import CategoryIcon from '@/components/shared/CategoryIcon'

export default {
  name: 'Header',
  components: {
    FormattedText,
    CategoryIcon,
  },
  computed: {
    ...mapState({
      productDetailDialog(state) {
        return state[getViewStore(this.$route.name)].productDetailDialog
      },
    }),
    ...mapGetters('customPromotions', ['getCustomPromotionsByProduct']),
    ...mapState('products', {
      productsSimilarUpc: state => state.data.productsSimilarUpc,
    }),
    ...getSelectedProductByRoute(),
    iconIsFav() {
      return this.selectedProduct.isStarred === 1
        ? 'mdi-heart'
        : 'mdi-heart-outline'
    },
    productIsPromoted() {
      return !!this.getCustomPromotionsByProduct[this.selectedProduct.id]
    },
    soldBy() {
      const product = this.selectedProduct
      if (product.isGramaje === 1) {
        return 'productsView.details.byWeight'
      } else if (product.factor > 1) {
        // Todo: upc_code_individual (?)
        return 'productsView.details.package'
      }
      return 'productsView.details.piece'
    },
    stock() {
      const factor = this.selectedProduct.factor
      const stockRaw = this.selectedProduct.quantity
      if (factor > 1) {
        const pack =
          factor === 0
            ? Math.floor(stockRaw) | 0
            : Math.floor(stockRaw / factor) | 0
        const pieces = stockRaw % factor
        return `${pack} paq ${pieces} pzs`
      } else if (this.selectedProduct.isGramaje === 1) {
        return `${stockRaw} g`
      }
      return `${stockRaw} uds`
    },
    categoryName() {
      return this.selectedProduct.categoryName
    },
    cssVars() {
      const cardStyles = {
        active: {
          '--primary-bg-color': `var(--v-productCardAvailableSecondary-base)`,
          '--secondary-bg-color': `var(--v-productCardAvailablePrimary-base)`,
        },
        warning: {
          '--primary-bg-color': `var(--v-productCardWarningSecondary-base)`,
          '--secondary-bg-color': `var(--v-productCardWarningPrimary-base)`,
        },
        out: {
          '--primary-bg-color': `var(--v-productCardOutSecondary-base)`,
          '--secondary-bg-color': `var(--v-productCardOutPrimary-base)`,
        },
        inactive: {
          '--primary-bg-color': `var(--v-productCardInactiveSecondary-base)`,
          '--secondary-bg-color': `var(--v-productCardInactivePrimary-base)`,
        },
      }
      return isNil(this.selectedProduct.isStoreInventory) ||
        this.selectedProduct.isStoreInventory === 1
        ? cardStyles[`${this.getProductLevel(this.selectedProduct)}`]
        : cardStyles.inactive
    },
  },
  methods: {
    ...mapActions({
      updateSelectedProductField(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).updateSelectedProductField
          }`,
          payload
        )
      },
      toggleDetailDialog(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).toggleDetailDialog
          }`,
          payload
        )
      },
      setSelectedProduct(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).setSelectedProduct
          }`,
          payload
        )
      },
    }),
    ...mapActions('productsView', [
      productsViewActions.setChangeOpenGramajeDialog,
      productsViewActions.setSimilarProductsUpcDialog,
    ]),
    goToPromotions() {
      const upc = this.selectedProduct.upc
      if (this.productDetailDialog.isOpen) {
        this.setSelectedProduct(null)
        this.toggleDetailDialog()
      }
      this.$router.push({
        path: `/app/custom-promotions?search=${upc}`,
      })
    },
    getTranslatedText: function(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
    changeFavoriteStatus: function() {
      const newValue = this.selectedProduct.isStarred === 1 ? 0 : 1
      this.updateSelectedProductField({
        field: 'isStarred',
        value: newValue,
      })
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
        data: {
          productToUpdated: {
            id: this.selectedProduct.id,
            data: mapStoreObject(
              { isStarred: this.selectedProduct.isStarred },
              storeInventory,
              true
            ),
          },
        },
      })
    },
    onIsGramajeRadioChange(value) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'ProductDetails',
        name: 'Change unit measure of a product',
      })
      this.updateSelectedProductField({
        field: 'isGramaje',
        value: parseInt(value),
      })
      this[productsViewActions.setChangeOpenGramajeDialog](true)
    },
    onFactorSalesByRadioChange(value) {
      this.updateSelectedProductField({
        field: 'factorSalesBy',
        value: value,
      })
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
        data: {
          productToUpdated: {
            id: this.selectedProduct.id,
            data: mapStoreObject(
              { factorSalesBy: this.selectedProduct.factorSalesBy },
              storeInventory,
              true
            ),
          },
        },
      })
    },
    getCategoryURL: function(name) {
      return require(`@/assets/superCategories/${name}.svg`)
    },
    getProductLevel(product) {
      if (product.quantity > product.levelWarning) return 'active'
      if (product.quantity > 0 && product.quantity <= product.levelWarning)
        return 'warning'
      if (product.quantity <= 0) return 'out'
      return 'inactive'
    },
    showSimilarProductsUpc(product) {
      this[productsViewActions.setSimilarProductsUpcDialog]({
        isOpen: true,
        product,
        isFromProductDetails: true,
      })
      this.toggleDetailDialog()
    },
    changeOpenGramajeCanceled() {
      const value = this.selectedProduct.isGramaje == 1 ? 0 : 1
      this.updateSelectedProductField({
        field: 'isGramaje',
        value: parseInt(value),
      })
    },
  },
  created() {
    this.$root.$on('changeOpenGramajeCanceled', this.changeOpenGramajeCanceled)
  },
  beforeDestroy() {
    this.$root.$off('changeOpenGramajeCanceled', this.changeOpenGramajeCanceled)
  },
}
</script>

<style lang="scss" scoped>
.header {
  .v-input--radio-group {
    margin-top: 0;
    :deep(.v-input__control) {
      .v-messages {
        display: none;
      }
      .v-input--selection-controls__input {
        margin-right: 4px;
      }
    }
  }
}
</style>
