<template>
  <v-row>
    <v-col cols="6">
      <ProductAutoComplete
        id="products-change-autocomplete"
        ref="productToChange"
        v-model="inputs.productToChange"
        :items="productChangeList"
        :filter="customFilter"
        :label="
          getTranslatedText(
            'purchaseView.returnProductDialog.productToReturnForm.productToReturn'
          )
        "
        :loading="loading"
        className="custom-text-field"
        clearable
        returnObject
        :errorMessages="onValidateFields('productToChange')"
        :onBlur="$v.inputs.productToChange.$touch()"
        @searchInputUpdated="searchInMLP"
      />
    </v-col>
    <v-col cols="3">
      <v-text-field
        id="quantity-change-input"
        ref="unitsToChange"
        v-model.number="inputs.unitsToChange"
        type="number"
        class="custom-text-field"
        filled
        :disabled="!isProductSelected"
        rounded
        background-color="cardBackgroundSecondary"
        :label="
          getTranslatedText(
            'purchaseView.returnProductDialog.productToReturnForm.quantity'
          )
        "
        :error-messages="onValidateFields('unitsToChange')"
        @input="calculateUnitCost"
        @blur="$v.inputs.unitsToChange.$touch()"
      />
    </v-col>
    <v-col cols="3">
      <MoneyTextField
        id="cost-change-input"
        ref="costToChange"
        v-model.number="inputs.costToChange"
        :config="{
          fieldName: 'costToChange',
          label: getCostLabel(),
          color: 'primary',
          filled: true,
          rounded: true,
          disabled: !isProductSelected,
          readonly: true,
          backgroundColor: 'cardBackgroundSecondary',
          errorMessage: onValidateFields,
        }"
        :options="moneyInputsConfig"
        @blur="$v.inputs.costToChange.$touch()"
      />
    </v-col>
  </v-row>
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'
import { isNil, has, concat } from 'ramda'
import { required } from 'vuelidate/lib/validators'

import productsVariables from '@/config/products'
import MLP_DB_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'

import { getTranslatedText } from '@/tools/data'
import { moneyTextFieldCountryConfig } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import productsActions from '@/store/products/actions.types'

import {
  setDefaultValidators,
  setMoneyValidator,
} from '@/components/PurchasesView/ReturnProductDialog/ReturnProductForm/tools'
import ProductAutoComplete from '@/components/shared/ProductAutoComplete'
import MoneyTextField from '@/components/shared/MoneyTextField'

export default {
  name: 'ChangeProductForm',
  components: { ProductAutoComplete, MoneyTextField },
  props: {
    inputs: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      productType: '',
      moneyInputsConfig: this.getMoneyInputsConfig(),
      debounceTimeout: null,
    }
  },
  computed: {
    ...mapState('products', {
      mlp: state => state.data.mlp,
      loading: state => state.fetching,
    }),
    ...mapGetters('products', ['getFilteredData']),
    productChangeList() {
      return isNil(this.inputs.productToReturn)
        ? concat(this.getFilteredData, this.mlp)
        : concat(
            this.getFilteredData.filter(
              product => product.id !== this.inputs.productToReturn.id
            ),
            this.mlp
          )
    },
    isProductSelected() {
      return !isNil(this.inputs.productToChange)
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('products', [
      productsActions.setProductsOrSuperCategoriesFetching,
    ]),
    getMoneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
    customFilter(item, queryText) {
      return (
        item.name.toLowerCase().indexOf(queryText.toLowerCase()) > -1 ||
        item.upc.toLowerCase().indexOf(queryText.toLowerCase()) > -1
      )
    },
    onValidateFields(input) {
      const errors = []
      if (
        !Object.keys(this.$v.inputs).includes(input) ||
        !this.$v.inputs[input].$dirty
      )
        return errors
      has('required')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].required &&
        errors.push(this.getTranslatedText('salesView.form.errors.empty'))
      has('minValue')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].minValue &&
        errors.push(this.getTranslatedText('salesView.form.errors.minValue'))
      has('maxValue')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].maxValue &&
        errors.push(this.getTranslatedText('salesView.form.errors.maxValue'))
      has('maxDecimals')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].maxDecimals &&
        errors.push(this.getTranslatedText('salesView.form.errors.maxValue'))
      has('integer')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].integer &&
        errors.push(this.getTranslatedText('salesView.form.errors.decimal'))
      return errors
    },
    getCostLabel() {
      switch (this.productType) {
        case 'isPieceProduct':
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costPiece'
          )
        case 'isByWeightProduct':
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costUnit'
          )
        case 'isOpenProductPackage':
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costPackage'
          )
        default:
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costPiece'
          )
      }
    },
    setProductType() {
      const product = this.inputs.productToChange
      if (isNil(product)) return ''
      const isOpenProduct = product.factor > 0 || product.isOpenProduct === 1
      const isPieceProduct = isOpenProduct === false && product.isGramaje === 0
      const isByWeightProduct =
        isOpenProduct === false && product.isGramaje === 1
      if (isPieceProduct) return 'isPieceProduct'
      if (isByWeightProduct) return 'isByWeightProduct'
      if (isOpenProduct) return 'isOpenProductPackage'
    },
    calculateUnitCost() {
      if (isNil(this.inputs.unitsToChange) || this.inputs.unitsToChange <= 0) {
        return
      }
      const gramajeReturn =
        this.inputs.productToReturn.isGramaje === 1 ? 1000 : 1
      const gramajeChange =
        this.inputs.productToChange.isGramaje === 1 ? 1000 : 1
      const totalCostReturn =
        (this.inputs.unitsToReturn / gramajeReturn) * this.inputs.costToReturn
      this.inputs.costToChange =
        totalCostReturn / (this.inputs.unitsToChange / gramajeChange)
    },
    searchInMLP(newValue) {
      if (isNil(newValue)) return
      if (this.debounceTimeout) {
        clearTimeout(this.debounceTimeout)
      }
      this.debounceTimeout = setTimeout(() => {
        this[productsActions.setProductsOrSuperCategoriesFetching](true)
        const parsedValue = newValue === '' ? null : newValue
        rendererEventsService.send(MLP_DB_API_EVENTS.channel, {
          event: MLP_DB_API_EVENTS.events.findByPropertiesLikes.name,
          data: [
            { key: 'upc_code', value: parsedValue },
            { key: 'prod_name', value: parsedValue },
          ],
        })
      }, 300)
    },
    async tryAddProductFromMLP(searchTerm) {
      this[productsActions.setProductsOrSuperCategoriesFetching](true)
      rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
        event: ADD_PRODUCT_EVENTS.events.addProductFromMLP.name,
        data: {
          item: { property: 'upc_code', value: searchTerm, limit: 1 },
          fromReturnProductDialog: true,
        },
      })
    },
  },
  watch: {
    'inputs.productToChange': function() {
      const { productToChange } = this.inputs
      this.inputs.unitsToChange = 0
      this.inputs.costToChange = 0
      if (isNil(productToChange)) {
        this.inputs.productToChange = null
        this.productType = ''
        return
      }
      if (
        !isNil(productToChange.isStoreInventory) &&
        productToChange.isStoreInventory !== 1
      ) {
        this.tryAddProductFromMLP(productToChange.upc)
        return
      }
      this.productType = this.setProductType()
    },
    'inputs.unitsToReturn': function() {
      this.calculateUnitCost()
    },
    'inputs.costToReturn': function() {
      this.calculateUnitCost()
    },
  },
  validations() {
    return {
      inputs: {
        productToChange: { required },
        unitsToChange: setDefaultValidators(productsVariables.STOCK_MAX_VALUE),
        costToChange: setMoneyValidator(1000000, 2),
      },
    }
  },
  beforeMount() {
    this.productType = this.setProductType()
  },
}
</script>

<style lang="scss" scoped>
.custom-text-field {
  border-radius: 12px;
}
</style>
