<template>
  <v-container fluid id="purchase-view" class="purchase-view">
    <v-row no-gutters>
      <v-col
        class="purchase-view__filter-toolbar px-6 pt-6"
        id="purchase-view__filter-toolbar"
      >
        <ProductsFilterToolbar />
      </v-col>
    </v-row>
    <v-row
      no-gutters
      :style="{
        height: `calc(100vh - ${getPurchaseListStyles}px)`,
      }"
    >
      <v-col
        :cols="columns.products"
        class="purchase-products-list"
        id="purchase-view__products-list"
      >
        <ProductsList />
      </v-col>
      <v-col
        :cols="columns.ticket"
        class="purchase-ticket"
        id="purchase-ticket"
      >
        <Ticket :ticketCols="columns.ticket" />
      </v-col>
    </v-row>
    <PurchasesViewTour v-if="tourEnabled" ref="purchaseTour" />
  </v-container>
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'
import { values, isNil } from 'ramda'
import uniqid from 'uniqid'

import MLP_DB_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'
import PURCHASE_ORDER_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'
import PURCHASE_ORDER_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderItemEvents'
import PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderReturnItemEvents'
import PRINTER_EVENTS from '@/config/events/printer'
import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'
import { promotions } from '@/config/promotions'
import { returnTypes } from '@/config/returnProductTypes'

import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'
import { ticketTools } from '@/tools/purchases'
import { roundToNearestMultiple } from '@/tools/numbersFormat'
import { getObjectCopy } from '@/tools/data'
import productsTools from '@/tools/products'
import { getNow } from '@/tools/dates'
import {
  getPromotionTicketToDB,
  getPromotionTicketToStore,
} from '@/tools/promotions'
import { getTotalTicketPrice } from '@/tools/ticket'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import productsActions from '@/store/products/actions.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'
import appActions from '@/store/app/actions.types'
import usersViewActions from '@/store/usersView/actions.types'
import salesActions from '@/store/sales/actions.types'

import ProductsList from '@/components/PurchasesView/ProductsList'
import ProductsFilterToolbar from '@/components/PurchasesView/ProductsFilterToolbar'
import Ticket from '@/components/PurchasesView/Ticket'
import PurchasesViewTour from '@/components/PurchasesView/PurchasesViewTour'
import config from '@/components/PurchasesView/config'

export default {
  name: 'PurchasesView',
  components: {
    ProductsList,
    ProductsFilterToolbar,
    Ticket,
    PurchasesViewTour,
  },
  data() {
    return {
      layoutCommonElementsHeight: 0,
      columns: {
        products: 8,
        ticket: 4,
      },
      searchInput: null,
    }
  },
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      windowSize: state => state.windowSize,
      defaultProductsFilter: state => state.defaultProductsFilter,
      addMarginTicket: state => state.addMarginTicket,
    }),
    ...mapState('products', {
      products: state => state.data.products,
    }),
    ...mapState('vendorsView', ['selectedVendor']),
    ...mapState('purchasesView', {
      selectedPurchase: state => state.selectedPurchase,
      filters: state => state.filters,
      tourEnabled: state => state.tourEnabled,
      isReturnProductDialogOpen: state => state.returnProductDialog.isOpen,
      productDetailDialogIsOpen: state => state.productDetailDialog.isOpen,
    }),
    ...mapState('usersView', ['selectedUser']),
    ...mapGetters('purchasesView', ['getFilteredProducts']),
    config() {
      return config()
    },
    getPurchaseListStyles() {
      return this.layoutCommonElementsHeight
    },
  },
  methods: {
    ...mapActions('app', [
      appActions.updateScannerStatus,
      appActions.addPendingSyncOperation,
    ]),
    ...mapActions('products', [
      productsActions.setMlpFilteredProducts,
      productsActions.editProductField,
      productsActions.fetchProducts,
      productsActions.setProductsOrSuperCategoriesError,
      productsActions.setProductsOrSuperCategoriesFetching,
    ]),
    ...mapActions('purchasesView', values(purchasesViewActions)),
    ...mapActions('usersView', [usersViewActions.setSelectedUserHasPurchases]),
    ...mapActions('sales', [salesActions.updateProductsFieldsFromAllSales]),
    getLayoutHeight() {
      const layoutComponentsHeight = getAppLayoutHeaderAndFooterHeight(
        'purchase-view'
      )
      const purchaseViewToolbar = document.getElementById(
        'purchase-view__filter-toolbar'
      ).offsetHeight
      this.layoutCommonElementsHeight =
        layoutComponentsHeight + purchaseViewToolbar
    },
    getPurchasesDataContainerColumns(value) {
      if (value <= 1280) return (this.columns = this.config.columns.half)
      if (value <= 1800) return (this.columns = this.config.columns.fifth)
      return (this.columns = this.config.columns.third)
    },
    mlpApiListener(event, payload) {
      const replies = {
        [MLP_DB_API_EVENTS.events.findByPropertiesLikes.replies
          .success]: () => {
          this[productsActions.setMlpFilteredProducts](payload.data)
        },
        [MLP_DB_API_EVENTS.events.findByPropertiesLikes.replies.error]: () => {
          notificationsService.showError(payload.error, this.$vuetify.lang, {
            timeout: 8000,
          })
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    initPurchaseView() {
      this.$track({
        type: 'system',
        action: 'init_purchase',
        category: 'Purchases',
        screen: 'Purchase',
        name: 'Load data by purchase id',
      })
      const lastPurchase = this.selectedVendor.purchases[0]
      const purchaseOrderId = !isNil(lastPurchase) ? lastPurchase._id : -1
      this.$loading.show('loadPurchase')
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event: PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.getAllByPurchaseId.name,
        data: {
          purchaseOrderId: !isNil(lastPurchase) ? lastPurchase._id : -1,
        },
      })
      rendererEventsService.send(
        PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.channel,
        {
          event:
            PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.events.getAllByPurchaseId
              .name,
          data: {
            purchaseOrderId,
          },
        }
      )
    },
    getTotalPrice() {
      const productTotal = getTotalTicketPrice(
        this.selectedPurchase.items,
        'cost'
      ).toFixed(0)
      const returnProductsTotal = this.selectedPurchase.returnItems
        .reduce((total, returnItem) => {
          const { amountToDiscount, returnType } = returnItem
          const subtotal =
            returnType === returnTypes.DISCOUNT ? amountToDiscount : 0
          return total + subtotal
        }, 0)
        .toFixed(0)
      const total = roundToNearestMultiple(
        parseInt(productTotal) + parseInt(-returnProductsTotal)
      )
      this[purchasesViewActions.updateTotalCostPurchase](total)
      rendererEventsService.send(PURCHASE_ORDER_DB_API_EVENTS.channel, {
        event: PURCHASE_ORDER_DB_API_EVENTS.events.update.name,
        data: {
          purchaseOrder: {
            ...this.selectedPurchase,
            promotion: getPromotionTicketToDB(this.selectedPurchase),
          },
        },
      })
    },
    purchaseItemsListener(event, payload) {
      const events = PURCHASE_ORDER_ITEM_DB_API_EVENTS.events
      const replies = {
        [events.getAllByPurchaseId.replies.success]: () => {
          let lastPurchase = this.selectedVendor.purchases[0]
          const { purchaseItems } = payload.data
          let procesedItems = []
          purchaseItems.forEach(item =>
            procesedItems.push(
              ticketTools.buildTicketItemFromBD(item, lastPurchase._id)
            )
          )
          lastPurchase.items = procesedItems
          lastPurchase.promotion = getPromotionTicketToStore(lastPurchase)
          this[purchasesViewActions.setSelectedPurchase](lastPurchase)
          this.getTotalPrice()
        },
        [events.getAllByPurchaseId.replies.error]: () => {
          notificationsService.showError(
            'notification.vendors.purchaseError',
            this.$vuetify.lang
          )
          this.$router.push({
            path: '/app/vendors',
            query: { fromTour: this.tourEnabled },
          })
        },
        [events.add.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'add_product',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Add product purchase store',
          })
          this[purchasesViewActions.addProductToPurchase](
            payload.data.purchaseItem
          )
          this.getTotalPrice()
          notificationsService.showSuccess(
            'notification.purchases.addItemSuccess',
            this.$vuetify.lang
          )
        },
        [events.add.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Error adding product',
          })
          notificationsService.showError(
            'notification.purchases.addItemError',
            this.$vuetify.lang
          )
        },
        [events.update.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'edit_product',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Edit product purchase store',
          })
          this[purchasesViewActions.updateProductFromPurchase](
            payload.data.purchaseItemUpdated
          )
          this.getTotalPrice()
        },
        [events.update.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Error editing product',
          })
          notificationsService.showError(
            'notification.purchases.updateItemError',
            this.$vuetify.lang
          )
        },
        [events.delete.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'delete_product',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Delete product purchase store',
          })
          this[purchasesViewActions.removeProductFromPurchase]({
            upcProduct: payload.data.purchaseOrderItem.upc,
          })
          this.getTotalPrice()
        },
        [events.delete.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Error deleting product',
          })
          notificationsService.showError(
            'notification.purchases.deleteItemError',
            this.$vuetify.lang
          )
        },
        [events.getLastPurchaseOrderItemCost.replies.success]: () => {
          this[purchasesViewActions.setUnitCostInSelectedProduct](
            payload.data.unitCost
          )
          if (payload.data.showProductTriangulationDialog) {
            this[purchasesViewActions.setProductTriangulationDialogStatus](true)
          }
          this.$root.$emit('selectedProductCostWasUpdated')
        },
        [events.getLastPurchaseOrderItemCost.replies.error]: () => {
          if (payload.data.showProductTriangulationDialog) {
            this[purchasesViewActions.setProductTriangulationDialogStatus](true)
          }
        },
      }
      if (payload.event in replies) replies[payload.event]()
      this.$loading.hide()
    },
    purchaseOrderReturnItemsListener(event, payload) {
      const events = PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.events
      const replies = {
        [events.getAllByPurchaseId.replies.success]: () => {
          const { purchaseReturnItems } = payload.data
          let procesedItems = []
          purchaseReturnItems.forEach(item =>
            procesedItems.push(ticketTools.buildTicketReturnItemFromBD(item))
          )
          this[purchasesViewActions.setReturnProductsToPurchase](procesedItems)
          this.getTotalPrice()
        },
        [events.getAllByPurchaseId.replies.error]: () =>
          notificationsService.showError(
            'notification.vendors.purchaseError',
            this.$vuetify.lang
          ),
        [events.add.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'add_return_product',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Add return product purchase store',
          })
          this[purchasesViewActions.addReturnProductToPurchase](
            payload.data.purchaseOrderReturnItem
          )
          this.getTotalPrice()
        },
        [events.add.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Error adding return product',
          })
          notificationsService.showError(
            'notification.purchases.addItemError',
            this.$vuetify.lang
          )
        },
        [events.update.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'edit_return_product',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Edit return product purchase store',
          })
          this[purchasesViewActions.updateReturnProductToPurchase](
            payload.data.purchaseReturnItemUpdated
          )
          this.getTotalPrice()
        },
        [events.update.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Error editing return product',
          })
          notificationsService.showError(
            'notification.purchases.updateItemError',
            this.$vuetify.lang
          )
        },
        [events.delete.replies.success]: () => {
          this.$track({
            type: 'system',
            action: 'delete_return_product',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Delete return product purchase store',
          })
          this[purchasesViewActions.removeReturnProductFromPurchase]({
            returnProductId:
              payload.data.purchaseOrderReturnItem.productReturnId,
          })
          this.getTotalPrice()
        },
        [events.delete.replies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Error deleting return product',
          })
          notificationsService.showError(
            'notification.purchases.deleteItemError',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    processSelectedProduct(product) {
      this[purchasesViewActions.setSelectedProduct](product)
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event:
          PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.getLastPurchaseOrderItemCost
            .name,
        data: {
          productId: product.product.isGeneric ? null : product.product.id,
          vendorId: this.selectedVendor.id,
          showProductTriangulationDialog: true,
        },
      })
    },
    onBarcodeScanned(barcode) {
      if (
        this.tourEnabled &&
        this.$refs.purchaseTour.tour.getCurrentStep().id ===
          'tourPurchasesFifthStep'
      ) {
        this.$root.$emit('product-scanned-purchase-tour', barcode.trim())
        return
      }
      if (this.isReturnProductDialogOpen) return
      this.searchInput.blur()
      this[purchasesViewActions.setSearchTermFilter](barcode)
      if (
        this.filters.group !== 'search' &&
        this.getFilteredProducts.length > 1
      ) {
        this[purchasesViewActions.setSearchTermFilter](null)
        this.$root.$emit('reset')
      }
      if (this.isScannerActive === false) {
        this.$root.$emit('reset')
        this[purchasesViewActions.setSuperCategoriesFilter]([])
        this[appActions.updateScannerStatus]()
      }
      if (this.filters.group === 'search') {
        this[purchasesViewActions.setGroupFilter](this.defaultProductsFilter)
      }
      if (this.getFilteredProducts.length === 1) {
        this[purchasesViewActions.setSelectedProduct](
          this.getFilteredProducts[0]
        )
        const scannedProduct = getObjectCopy(this.getFilteredProducts[0])
        this.$root.$emit('reset')
        this[purchasesViewActions.setGroupFilter](this.defaultProductsFilter)
        this[purchasesViewActions.setSearchTermFilter](null)
        if (scannedProduct.isGramaje === 0 && scannedProduct.id > 0) {
          const productPrices = productsTools.getPrices(
            scannedProduct,
            this.products
          )
          this.processSelectedProduct({
            product: {
              uniqueId: uniqid(),
              id: scannedProduct.id,
              stock: scannedProduct.quantity,
              isGramaje: scannedProduct.isGramaje === 1 ? 1 : 0,
              isOpenProduct: scannedProduct.factor > 0 ? 1 : 0,
              openProductType: scannedProduct.factorSalesBy,
              openProductDbPrices: productPrices.openProductDbPrices,
              isGeneric: scannedProduct.isGeneric === 1 ? 1 : 0,
              isPriceChanged: productPrices.isPriceChanged,
              isPiecePriceChanged: productPrices.isPiecePriceChanged,
              name: scannedProduct.name,
              quantity: 1,
              unitPrice: productPrices.unitPrice,
              cost: scannedProduct.isGeneric === 1 ? 0 : scannedProduct.cost,
              upc: scannedProduct.upc,
              timeAdded: getNow(false),
              priceFrom: productsTools.getAddedFrom(scannedProduct),
              dbPrice: productPrices.dbPrice,
              levelWarning: scannedProduct.levelWarning,
              factor: scannedProduct.factor,
              description: scannedProduct.alternativeName,
              factorSalesBy: scannedProduct.factorSalesBy,
              iva: scannedProduct.iva,
              promotionTypeId: promotions.NONE,
              promotionExtra: 0,
              costWithoutTaxAndPromotion: scannedProduct.cost,
              discountPercent: 0,
              discountAmount: 0,
            },
          })
        } else if (scannedProduct.isGramaje === 1) {
          this.processSelectedProduct({
            product: {
              ...scannedProduct,
              promotionTypeId: promotions.NONE,
              promotionExtra: 0,
              costWithoutTaxAndPromotion: scannedProduct.cost,
              discountPercent: 0,
              discountAmount: 0,
            },
          })
        }
        return
      }
    },
    purchaseOperationsListener(event, payload) {
      const events = PURCHASE_ORDER_DB_API_EVENTS.events
      const replies = {
        [events.finishPurchase.replies.success]: async () => {
          this.$track({
            type: 'system',
            action: 'finish_purchase',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Go to vendors',
          })
          this.$root.$emit('setPurchaseTicketDate', payload.data.creationDate)
          this[purchasesViewActions.finishPurchase](payload.data)
          this[salesActions.updateProductsFieldsFromAllSales](
            payload.data.itemsToUpdate
          )
          await this[appActions.addPendingSyncOperation]()
          if (this.selectedPurchase.print) {
            rendererEventsService.send(PRINTER_EVENTS.channel, {
              event: PRINTER_EVENTS.events.printSale.name,
              data: {
                ticketToPrint: document.getElementById('ticket-to-print')
                  .innerHTML,
                addMarginTicket: this.addMarginTicket,
              },
            })
          }
          this[purchasesViewActions.setSelectedProduct]()
          this[purchasesViewActions.setSelectedPurchase]()
          notificationsService.showSuccess(
            'notification.vendors.purchaseSuccess',
            this.$vuetify.lang
          )
          if (!this.selectedUser.hasPurchases)
            this[usersViewActions.setSelectedUserHasPurchases](true)
          this.$router.push({
            path: '/app/vendors',
            query: { fromTour: this.tourEnabled },
          })
        },
        [events.finishPurchase.replies.error]: async () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Purchases',
            screen: 'Purchase',
            name: 'Error finishing purchase',
          })
          notificationsService.showError(
            payload.data.errorMsg,
            this.$vuetify.lang
          )
          this[purchasesViewActions.setFinishingPurchaseStatus](false)
        },
      }
      if (payload.event in replies) replies[payload.event]()
      this.$loading.hide()
    },
    inventoryListener(event, payload) {
      const storeInventoryEvents = STORE_INVENTORY_DB_API_EVENTS.events
      const replies = {
        [storeInventoryEvents.updateById.replies.success]: () => {
          if (!this.productDetailDialogIsOpen) {
            this[productsActions.editProductField](payload.data)
            this.$root.$emit('productWasEdited', payload.data._id)
          }
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    entitiesListener(event, payload) {
      const getAllReplies = ENTITIES_EVENTS.events.getAllByEntities.replies
      const replies = {
        [`${getAllReplies.success}-fetchProducts`]: () =>
          this[productsActions.fetchProducts](payload.data),
        [`${getAllReplies.error}-fetchProducts`]: () => {
          this[productsActions.setProductsOrSuperCategoriesError](payload.data)
          this[productsActions.setProductsOrSuperCategoriesFetching](false)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  watch: {
    'windowSize.x': function(value) {
      this.getPurchasesDataContainerColumns(value)
    },
  },
  created() {
    rendererEventsService.subscribe(
      MLP_DB_API_EVENTS.replyChannel,
      this.mlpApiListener
    )
    rendererEventsService.subscribe(
      PURCHASE_ORDER_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseItemsListener
    )
    rendererEventsService.subscribe(
      PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseOrderReturnItemsListener
    )
    rendererEventsService.subscribe(
      PURCHASE_ORDER_DB_API_EVENTS.replyChannel,
      this.purchaseOperationsListener
    )
    rendererEventsService.subscribe(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.inventoryListener
    )
    rendererEventsService.subscribe(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
  },
  beforeMount() {
    this.initPurchaseView()
  },
  mounted() {
    this.getLayoutHeight()
    this.getPurchasesDataContainerColumns(this.windowSize.x)
    this.$barcodeScanner.init(this.onBarcodeScanned)
    this.$root.$on('productAddedFromMatch', this.onBarcodeScanned)
    this.searchInput = document.getElementById('purchases-input-search')
    this.$root.$on('enable-scanner', () =>
      this.$barcodeScanner.init(this.onBarcodeScanned)
    )
  },
  beforeDestroy() {
    this.$root.$off('productAddedFromMatch', this.onBarcodeScanned)
    rendererEventsService.removeListener(
      MLP_DB_API_EVENTS.replyChannel,
      this.mlpApiListener
    )
    rendererEventsService.removeListener(
      PURCHASE_ORDER_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseItemsListener
    )
    rendererEventsService.removeListener(
      PURCHASE_ORDER_RETURN_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseOrderReturnItemsListener
    )
    rendererEventsService.removeListener(
      PURCHASE_ORDER_DB_API_EVENTS.replyChannel,
      this.purchaseOperationsListener
    )
    rendererEventsService.removeListener(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.inventoryListener
    )
    rendererEventsService.removeListener(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
  },
}
</script>

<style lang="scss" scoped>
#purchase-view {
  height: 100%;
  .purchase-products-list {
    background-color: var(--v-viewBackground-base);
  }
}
</style>
