<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'
import { isNil, values } from 'ramda'

import { isDevelopment } from '@/config/env'
import MLP_DB_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'
import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'
import productsActions from '@/store/products/actions.types'

import ToolBar from '@/components/shared/ToolBar'

import config from '@/components/PurchasesView/ProductsFilterToolbar/ProductsFilter/config'

export default {
  name: 'PurchasesFilter',
  components: { ToolBar },
  timer: null,
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    ...mapState('products', ['data']),
    ...mapState('purchasesView', {
      filters: state => state.filters,
      selectedPurchase: state => state.selectedPurchase,
      tourEnabled: state => state.tourEnabled,
    }),
    ...mapGetters('purchasesView', ['getFilteredProducts']),
    componentConfig() {
      return config(
        {
          data: this.data,
          filters: this.filters,
          isScannerActive: this.isScannerActive,
          products: this.data.products,
          defaultProductsFilter: this.defaultProductsFilter,
        },
        {
          setSearchTerm: this[purchasesViewActions.setSearchTermFilter],
          setGroup: this[purchasesViewActions.setGroupFilter],
          setSelectedSuperCategories: this[
            purchasesViewActions.setSuperCategoriesFilter
          ],
          onReset: this.onReset,
          context: this,
          onChange: this.onChange,
          onEnter: this.onEnter,
          updateScannerStatus: this[appActions.updateScannerStatus],
          resetScannerStatus: this.resetScannerStatus,
          backward: this.backward,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('purchasesView', values(purchasesViewActions)),
    ...mapActions('products', [productsActions.resetMlpFilteredProducts]),
    onReset() {
      this.$root.$emit('reset')
    },
    backward() {
      if (!this.tourEnabled) this.$router.push({ path: '/app/vendors' })
    },
    onChange(value) {
      const parsedValue = value === '' ? null : value
      if (this.filters.group === 'search') {
        this[purchasesViewActions.setSearchTermFilter](parsedValue)
      }
    },
    onEnter(value) {
      const parsedValue = value === '' ? null : value
      if (isDevelopment === false || value.length > 24 || this.tourEnabled)
        return
      if (
        this.getFilteredProducts.length === 0 &&
        this.data.mlp.length === 0 &&
        !isNil(parsedValue)
      ) {
        this.resetScannerStatus('search-control')
        this[purchasesViewActions.setSearchTermFilter](parsedValue)
      }
    },
    resetScannerStatus(group) {
      switch (group) {
        case 'search-control':
          if (this.isScannerActive === false)
            this[appActions.updateScannerStatus]()
          break
        case 'clear':
          this[purchasesViewActions.setSearchTermFilter](null)
          this[purchasesViewActions.setGroupFilter](this.defaultProductsFilter)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
        default:
          group === 'superCategories'
            ? this[purchasesViewActions.setGroupFilter]('superCategories')
            : this[purchasesViewActions.setGroupFilter](group)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
      }
    },
  },
  watch: {
    'filters.searchTerm'(newValue) {
      const parsedValue = newValue === '' ? null : newValue
      if (this.timer) clearTimeout(this.timer)
      if (isNil(parsedValue)) {
        this[productsActions.resetMlpFilteredProducts]([])
        return
      }
      if (this.filters.group === 'search') {
        this.timer = setTimeout(() => {
          rendererEventsService.send(MLP_DB_API_EVENTS.channel, {
            event: MLP_DB_API_EVENTS.events.findByPropertiesLikes.name,
            data: [
              { key: 'upc_code', value: parsedValue },
              { key: 'prod_name', value: parsedValue },
            ],
          })
        }, 500)
      }
    },
  },
  mounted() {
    if (this.tourEnabled) {
      setTimeout(
        () => document.getElementById('purchases-input-search').click(),
        500
      )
    }
    if (!this.getFilteredProducts.length) {
      this[purchasesViewActions.setGroupFilter]('all')
    }
  },
  beforeDestroy() {
    if (
      this.selectedPurchase.items.length === 0 &&
      this.selectedPurchase.returnItems.length === 0
    ) {
      rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
        event: PURCHASES_DB_API_EVENTS.events.delete.name,
        data: {
          purchase: this.selectedPurchase,
        },
      })
    }
    this[purchasesViewActions.setSelectedProduct]()
    this[purchasesViewActions.setSelectedPurchase]()
    this[purchasesViewActions.setGroupFilter]('vendor')
  },
}
</script>
