<template>
  <div>
    <AlertNoDataToShow v-if="purchaseReportList.length <= 0" />
    <div v-else :style="{ height: containerHeight + 'px' }">
      <PaginatedList :config="componentConfig">
        <template v-slot:item="{ item }">
          <DetailPurchaseRow :purchase-item="item" />
        </template>
      </PaginatedList>
    </div>
  </div>
</template>

<script>
import PURCHASE_ORDER_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderItemEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'
import setConfig from '@/components/ProductDetail/PurchasesTab/config'
import PaginatedList from '@/components/shared/PaginatedTable'
import AlertNoDataToShow from '@/components/shared/AlertNoDataToShow'
import DetailPurchaseRow from '@/components/ProductDetail/PurchasesTab/DetailPurchaseRow'

export default {
  name: 'ProductPurchasesTab',
  components: { AlertNoDataToShow, PaginatedList, DetailPurchaseRow },
  data() {
    return {
      purchaseReportList: [],
      containerHeight: 0,
    }
  },
  computed: {
    ...getSelectedProductByRoute(),
    componentConfig() {
      return setConfig(
        {
          items: this.purchaseReportList,
        },
        {
          context: this,
        }
      )
    },
  },
  methods: {
    loadPurchaseOrdersReport() {
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event:
          PURCHASE_ORDER_ITEM_DB_API_EVENTS.events
            .getPurchaseOrderItemByProductId.name,
        data: { productId: this.selectedProduct.id },
      })
    },
    async purchaseOrderItemListener(event, payload) {
      const purchaseOrderItemEvents = PURCHASE_ORDER_ITEM_DB_API_EVENTS.events
      const replies = {
        [purchaseOrderItemEvents.getPurchaseOrderItemByProductId.replies
          .success]: () => {
          const { purchaseReportList } = payload.data
          this.purchaseReportList = purchaseReportList
        },
        [purchaseOrderItemEvents.getPurchaseOrderItemByProductId.replies
          .error]: () => {
          notificationsService.showError(
            payload.data.errorMsg,
            this.$vuetify.lang
          )
          this.purchaseReportList = []
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    getCustomHeight() {
      const popupHeight = document.getElementById('product-detail-card')
        .offsetHeight
      const headerHeight = document.getElementById('product-detail-card-header')
        .offsetHeight
      const footerHeight = document.getElementById('product-detail-card-footer')
        .offsetHeight
      const tabHeaderHeight = document.getElementsByClassName(
        'v-slide-group__wrapper'
      )[0].offsetHeight
      this.containerHeight =
        popupHeight - headerHeight - footerHeight - tabHeaderHeight - 30
    },
  },
  created() {
    rendererEventsService.subscribe(
      PURCHASE_ORDER_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseOrderItemListener
    )
  },
  mounted() {
    this.loadPurchaseOrdersReport()
    this.getCustomHeight()
    this.$root.$on('navigateToProductWasDone', this.loadPurchaseOrdersReport)
  },
  beforeDestroy() {
    this.$root.$off('navigateToProductWasDone', this.loadPurchaseOrdersReport)
    rendererEventsService.removeListener(
      PURCHASE_ORDER_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseOrderItemListener
    )
  },
}
</script>
