<template>
  <div>
    <div v-show="false" ref="tourPurchasesFifthStep">
      <div class="tour-third-step-content">
        <h2>
          {{ getTranslatedText('tour.purchasesTour.fifthStep.firstText') }}
        </h2>
        <h3>
          {{ getTranslatedText('tour.purchasesTour.fifthStep.secondText') }}
        </h3>
      </div>
    </div>
    <div v-show="false" ref="tourPurchasesTenthStep">
      <div class="tour-first-step-content">
        <v-icon size="90" class="mb-6">
          mdi-cart-check
        </v-icon>
        <h1>
          {{ getTranslatedText('tour.purchasesTour.tenthStep.firstText') }}
        </h1>
        <h2>
          {{ getTranslatedText('tour.purchasesTour.tenthStep.secondText') }}
        </h2>
        <h2>
          {{ getTranslatedText('tour.purchasesTour.tenthStep.thirdText') }}
        </h2>
      </div>
    </div>
  </div>
</template>

<script>
import { mapState, mapActions, mapGetters } from 'vuex'

import purchasesTour from '@/config/tours/purchasesTour'
import USER_EVENTS from '@/config/events/databaseAPI/usersEvents'

import { getTranslatedText } from '@/tools/data'
import tourTrackTools from '@/tools/tourTrack'

import tourService from '@/services/renderer/tour'
import rendererEventsService from '@/services/renderer/rendererEvents'

import purchasesViewActions from '@/store/purchasesView/actions.types'
import appActions from '@/store/app/actions.types'
import usersViewActions from '@/store/usersView/actions.types'

export default {
  name: 'PurchasesViewTour',
  computed: {
    ...mapState('purchasesView', ['tourEnabled']),
    ...mapState('products', { mlpProducts: state => state.data.mlp }),
    ...mapGetters('products', ['getFilteredData']),
    ...mapState('usersView', ['selectedUser']),
  },
  methods: {
    getTranslatedText,
    ...mapActions('purchasesView', [purchasesViewActions.setTourEnabled]),
    ...mapActions('app', [appActions.setConfirmCancelTourDialogStatus]),
    ...mapActions('usersView', [usersViewActions.setSelectedUser]),
    createAndStartTour() {
      this.tour = tourService.createTour(this, purchasesTour.tourOptions)
      tourService.addSteps(this, purchasesTour.secondPartSteps)
      tourService.addCancelFunctionToSteps(this, () =>
        this[appActions.setConfirmCancelTourDialogStatus]({
          isOpen: true,
          tour: this.tour,
        })
      )
      this.tour.steps[0].once('show', () => {
        setTimeout(
          () => document.getElementById('purchases-input-search').click(),
          400
        )
      })
      this.tour.steps[1].once('show', () => {
        setTimeout(
          () => document.getElementById('purchases-input-search').click(),
          400
        )
      })
      this.tour.on('cancel', () => {
        this.disabledVendorsTour()
      })
      this.tour.on('complete', () => {
        this.disabledVendorsTour()
      })
      tourTrackTools.initTracks.call(this, 'Purchases')
      this.tour.start()
    },
    disabledVendorsTour() {
      const selectedUser = Object.assign(this.selectedUser)
      rendererEventsService.send(USER_EVENTS.channel, {
        event: USER_EVENTS.events.update.name,
        data: {
          userId: selectedUser.id,
          values: { vendors_tour_disabled: 1 },
        },
      })
      this[purchasesViewActions.setTourEnabled](false)
      selectedUser.vendorsTourDisabled = 1
      this[usersViewActions.setSelectedUser](selectedUser)
    },
  },
  watch: {
    mlpProducts: function(value) {
      if (this.tourEnabled) {
        const currentStep = this.tour.getCurrentStep().id
        if (currentStep === 'tourPurchasesFifthStep' && value.length !== 0)
          this.tour.next()
      }
    },
  },
  mounted() {
    if (this.tourEnabled) this.createAndStartTour()
    this.$root.$on('product-scanned-purchase-tour', barcode => {
      if (!this.tourEnabled) return
      const currentStep = this.tour.getCurrentStep().id
      if (
        currentStep === 'tourPurchasesFifthStep' &&
        this.getFilteredData.some(prod => prod.upc.includes(barcode))
      ) {
        setTimeout(() => {
          this.tour.next()
        }, 300)
      }
    })
    this.$root.$on('product-added-tour', () => {
      const currentStep = this.tour.getCurrentStep().id
      if (this.tourEnabled && currentStep === 'tourPurchasesSixthStep')
        setTimeout(() => this.tour.next(), 400)
    })
    this.$root.$on('purchase-cancel-tour', () => {
      const currentStep = this.tour.getCurrentStep().id
      if (
        this.tourEnabled &&
        (currentStep === 'tourPurchasesSeventhStep' ||
          currentStep === 'tourPurchasesNinthStep')
      )
        this.tour.back()
    })
  },
  beforeDestroy() {
    this.$root.$off('product-added-tour')
    this.$root.$off('purchase-cancel-tour')
    this.$root.$off('product-scanned-purchase-tour')
  },
}
</script>
