import { find, isNil } from 'ramda'
import uniqid from 'uniqid'

import priceFrom from '@/config/itemAddedFrom'

import { formatNumberToDb } from '@/tools/numbersFormat'
import {
  calculateUnitaryCost,
  getDiffDiscount,
  getDiscountAmount,
  getDiscountPercent,
  getPromotionExtra,
  getTotalExistences,
  getTotalQuantity,
} from '@/tools/purchases/tools'
import { getNow } from '@/tools/dates'

import Store from '@/store'

const buildTicketItem = (payload, purchaseOrderId) => {
  const { product } = Store.state.purchasesView.selectedProduct
  const { products } = Store.state.products.data
  const productFound = find(item => item.upc === product.upc, products)
  let dbPrice, openProductDbPrices
  if (payload.productType !== 'isOpenProductPiece') {
    dbPrice =
      product.isPriceChanged === 1
        ? !isNil(payload.product.openProductDbPrices)
          ? payload.product.openProductDbPrices.package
          : productFound.price
        : formatNumberToDb(payload.inputs.price)
    openProductDbPrices = {
      package:
        product.isPriceChanged === 1
          ? !isNil(payload.product.openProductDbPrices)
            ? payload.product.openProductDbPrices.package
            : productFound.price
          : formatNumberToDb(payload.inputs.pricePack),
      piece: formatNumberToDb(payload.inputs.price),
    }
    return {
      purchaseOrderId,
      uniqueId: uniqid(),
      id: product.id,
      stock: parseInt(
        getTotalExistences(
          product.factor,
          payload.inputs.existences,
          payload.inputs.existencesPack
        ),
        10
      ),
      isGramaje: product.isGramaje === 1 ? 1 : 0,
      isOpenProduct: product.factor > 0 ? 1 : 0,
      openProductType: 0,
      openProductDbPrices,
      isGeneric: product.isGeneric === 1 ? 1 : 0,
      isPriceChanged:
        payload.productType !== 'isOpenProductPiece'
          ? 1
          : productFound.isPriceChanged,
      isPiecePriceChanged:
        payload.productType === 'isOpenProductPiece'
          ? 1
          : productFound.isPiecePriceChanged,
      name: product.name,
      quantity: getTotalQuantity({
        quantity: parseInt(payload.inputs.quantity, 10),
        promotionTypeId: payload.inputs.promotionTypeId,
        promotionExtra: payload.inputs.freeUnits,
      }),
      unitPrice:
        product.isGeneric === 1 ? 0 : formatNumberToDb(payload.inputs.price),
      iva: payload.inputs.tax,
      cost: calculateUnitaryCost(payload.inputs, product.isGramaje),
      upc: product.upc,
      timeAdded: getNow(false),
      priceFrom: priceFrom.FROM_SCANNER,
      dbPrice: product.isGeneric === 1 ? 0 : dbPrice,
      dbCost: productFound.cost,
      dbIva: product.iva,
      levelWarning: product.levelWarning,
      factor: product.factor,
      promotionTypeId: payload.inputs.promotionTypeId,
      promotionExtra: getPromotionExtra(payload.inputs),
      costWithoutTaxAndPromotion: formatNumberToDb(payload.inputs.cost),
      discountPercent: getDiscountPercent(payload.inputs),
      discountAmount: getDiscountAmount(payload.inputs),
      description: productFound.alternativeName,
    }
  }
}

const buildTicketItemFromBD = (payload, purchaseOrderId) => {
  const { products } = Store.state.products.data
  const product = find(item => item.id === payload.product_id, products)
  let openProductDbPrices
  if (product.factor > 1) {
    openProductDbPrices = {
      package: !isNil(product.unitPrice) ? product.unitPrice : product.price,
      piece: product.unitProdPrice,
    }
  }
  return {
    purchaseOrderId,
    purchaseItemId: payload._id,
    uniqueId: uniqid(),
    id: product.id,
    stock: product.quantity,
    isGramaje: product.isGramaje === 1 ? 1 : 0,
    isOpenProduct: product.factor > 0 ? 1 : 0,
    openProductType: 0,
    isGeneric: product.isGeneric === 1 ? 1 : 0,
    isPriceChanged:
      payload.productType !== 'isOpenProductPiece' ? 1 : product.isPriceChanged,
    isPiecePriceChanged:
      payload.productType === 'isOpenProductPiece'
        ? 1
        : product.isPiecePriceChanged,
    name: product.name,
    quantity: parseInt(payload.purchase_quantity, 10),
    unitPrice: !isNil(product.unitPrice) ? product.unitPrice : product.price,
    openProductDbPrices,
    iva: payload.iva,
    cost: payload.purchase_price,
    upc: product.upc,
    timeAdded: payload.date,
    priceFrom: priceFrom.FROM_SCANNER,
    levelWarning: product.levelWarning,
    factor: product.factor,
    dbCost: product.cost,
    dbIva: product.iva,
    promotionTypeId: payload.promotion_type_id,
    promotionExtra: payload.promotion_extra,
    costWithoutTaxAndPromotion: payload.unit_cost,
    discountPercent: payload.discount,
    discountAmount: getDiffDiscount(payload, product.isGramaje),
    description: product.alternativeName,
  }
}

const buildTicketProductUpdateByType = (payload, purchaseOrderId) => {
  const { product } = Store.state.purchasesView.selectedProduct
  const { products } = Store.state.products.data
  const productInventory = find(item => item.id === product.id, products)
  let openProductDbPrices
  if (productInventory.factor > 1) {
    openProductDbPrices = {
      package: formatNumberToDb(payload.inputs.pricePack),
      piece: formatNumberToDb(payload.inputs.price),
    }
  }
  return {
    purchaseOrderId,
    uniqueId: uniqid(),
    id: product.id,
    stock: parseInt(
      getTotalExistences(
        product.factor,
        payload.inputs.existences,
        payload.inputs.existencesPack
      ),
      10
    ),
    isGramaje: product.isGramaje === 1 ? 1 : 0,
    isOpenProduct: product.factor > 0 ? 1 : 0,
    openProductType: 0,
    isGeneric: product.isGeneric === 1 ? 1 : 0,
    isPriceChanged: 1,
    isPiecePriceChanged: 1,
    name: product.name,
    quantity: getTotalQuantity({
      quantity: parseInt(payload.inputs.quantity, 10),
      promotionTypeId: payload.inputs.promotionTypeId,
      promotionExtra: payload.inputs.freeUnits,
    }),
    openProductDbPrices,
    unitPrice: formatNumberToDb(payload.inputs.price),
    iva: payload.inputs.tax,
    cost: calculateUnitaryCost(payload.inputs, product.isGramaje),
    upc: product.upc,
    timeAdded: getNow(false),
    priceFrom: priceFrom.FROM_SCANNER,
    levelWarning: product.levelWarning,
    factor: product.factor,
    factorSalesBy: product.factorSalesBy,
    dbCost: productInventory.cost,
    dbIva: product.iva,
    promotionTypeId: payload.inputs.promotionTypeId,
    promotionExtra: getPromotionExtra(payload.inputs),
    costWithoutTaxAndPromotion: formatNumberToDb(payload.inputs.cost),
    discountPercent: getDiscountPercent(payload.inputs),
    discountAmount: getDiscountAmount(payload.inputs),
    description: productInventory.alternativeName,
  }
}

export default {
  buildTicketItem,
  buildTicketItemFromBD,
  buildTicketProductUpdateByType,
}
