<template>
  <v-col cols="3">
    <v-text-field
      id="free-quantity-input"
      ref="freeUnits"
      v-model.number="inputs.freeUnits"
      class="custom-text-field-large"
      filled
      rounded
      color="primary"
      :label="
        getTranslatedText(
          'purchaseView.productTriangulationDialog.promotion.fields.quantity'
        )
      "
      :error-messages="onValidateFields('freeUnits')"
      @blur="$v.inputs.freeUnits.$touch()"
      @keydown.enter="onEnterEvent"
    />
  </v-col>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

import productTriangulation from '@/mixins/purchases/productTriangulation'

export default {
  name: 'FreeUnitsForm',
  props: {
    inputs: {
      type: Object,
      required: true,
    },
    onEnterEvent: {
      type: Function,
    },
  },
  methods: {
    getTranslatedText,
    setFormValidators() {
      const validations = {
        inputs: {
          freeUnits: this.setDefaultValidators(100000, false, true),
        },
      }
      return validations
    },
  },
  mixins: [productTriangulation],
  validations() {
    return this.setFormValidators()
  },
}
</script>
