<template>
  <v-card
    class="pa-0 rounded-widget"
    color="cardBackgroundSecondary"
    flat
    id="stock-sold-details"
  >
    <div class="py-1 pl-5 pr-1 d-flex widget-title">
      <v-icon color="textOverBackground">mdi-currency-usd</v-icon>
      <FormattedText
        intl
        type="text-body-1"
        color="textOverBackground"
        value="productsView.details.tabs.sales.profit"
        class="pl-2 pt-1"
        className="font-weight-bold"
      />
    </div>
    <v-container class="pa-0">
      <v-row>
        <v-col cols="12" class="d-flex flex-column px-8">
          <div class="d-flex justify-space-between">
            <div v-for="widget in widgetConfig.singleWidgets" :key="widget.id">
              <component
                :is="widget.type"
                :config="widget"
                v-if="widget.visible"
              />
            </div>
          </div>
        </v-col>
      </v-row>
    </v-container>
  </v-card>
</template>

<script>
import SingleDataWidget from '@/components/shared/SingleDataWidget'
import FormattedText from '@/components/shared/FormattedText'
import setConfig from '@/components/ProductDetail/SalesTab/ProfitsDetails/config'
import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'

export default {
  name: 'ProfitsDetails',
  components: { FormattedText, SingleDataWidget },
  props: {
    report: {
      type: Object,
      required: true,
    },
  },
  computed: {
    ...getSelectedProductByRoute(),
    widgetConfig: function() {
      return setConfig(
        {
          report: this.report,
          selectedProduct: this.selectedProduct,
        },
        {}
      )
    },
  },
}
</script>

<style lang="scss" scoped>
.rounded-widget {
  border-radius: 8px;
  .widget-title {
    background-color: var(--v-cardSecondary-base);
  }
}
</style>
