<template>
  <div v-if="enableWastedProducts" class="d-inline-block">
    <v-btn
      color="secondary"
      @click="showWastedProductsDialog"
      v-track:click="{
        category: $route.name,
        screen: 'ProductDetails',
        name: 'Create wasted product',
      }"
    >
      <v-icon>mdi-basket-unfill</v-icon>
      {{ getTranslatedText('productsView.wastedProducts.create') }}
    </v-btn>
    <DialogCard :config="config.dialogData">
      <Form2Columns :config="config" class="pt-4" />
    </DialogCard>
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import STORE_INVENTORY_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'

import { cleanObjectObserver, getTranslatedText } from '@/tools/data'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'

import {
  getSelectedProductByRoute,
  updateSelectedProductByRoute,
} from '@/components/ProductDetail/selectedProduct.tools'
import setConfig from '@/components/ProductDetail/Footer/WastedProducts/config'
import Form2Columns from '@/components/shared/Form2Columns'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'WastedProducts',
  components: { DialogCard, Form2Columns },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
    }
  },
  computed: {
    ...mapState('productsView', ['wastedProductsDialog']),
    ...mapState('products', { products: state => state.data.products }),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('account', {
      country: state => state.data.country,
    }),
    ...getSelectedProductByRoute(),
    enableWastedProducts() {
      return (
        this.selectedUser.inventoryPermission === 0 &&
        this.selectedProduct.quantity > 0
      )
    },
    config() {
      return setConfig(
        {
          isOpen: this.wastedProductsDialog.isOpen,
          selectedProduct: this.selectedProduct,
          inputs: this.inputs,
          v: this.$v.inputs,
        },
        {
          cancel: this.hideWastedProductsDialog,
          accept: this.saveWastedProducts,
        }
      )
    },
  },
  methods: {
    ...mapActions('productsView', [
      productsViewActions.setWastedProductsDialogStatus,
    ]),
    ...updateSelectedProductByRoute(),
    getTranslatedText,
    showWastedProductsDialog() {
      this.inputs = {}
      this.validators = { inputs: {} }
      this.setInputsProperties()
      this.resetInputValues()
      this.$v.$reset()
      this[productsViewActions.setWastedProductsDialogStatus](true)
    },
    hideWastedProductsDialog() {
      this[productsViewActions.setWastedProductsDialogStatus](false)
      this.resetInputValues()
    },
    resetInputValues() {
      Object.keys(this.inputs).forEach(input => {
        this.inputs[input] = 0
        this.$v.inputs[input].$reset()
      })
    },
    setInputsProperties() {
      this.config.fields.forEach(field => {
        this.$set(this.inputs, field.id, 0)
        if (field.validators) {
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
        }
      })
    },
    saveWastedProducts() {
      if (this.$v.$invalid) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'WastedProductDialog',
        name: `Save wasted product`,
      })
      rendererEventsService.send(STORE_INVENTORY_EVENTS.channel, {
        event: STORE_INVENTORY_EVENTS.events.generateWastedProducts.name,
        data: {
          product: this.selectedProduct,
          wastedProducts: this.inputs,
          username: this.selectedUser.name,
          limitCost: this.country.limits.maxValuePrice,
        },
      })
    },
    wastedProductsListener(event, payload) {
      const events = STORE_INVENTORY_EVENTS.events
      const replies = {
        [events.generateWastedProducts.replies.success]: () => {
          notificationsService.showSuccess(payload.message, this.$vuetify.lang)
        },
        [events.generateWastedProducts.replies.error]: () => {
          notificationsService.showError(
            payload.data.error.message,
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    productStoreWasUpdatedListener(fromEvent) {
      if (fromEvent !== 'generateWastedProducts') return
      this.setSelectedProduct(
        this.getProductFromProductsList(this.selectedProduct.id)
      )
      this.hideWastedProductsDialog()
    },
    getProductFromProductsList(id) {
      return this.products.find(product => product.id === id)
    },
    initializeWastedForm() {
      this.inputs = {}
      this.validators = { inputs: {} }
      this.setInputsProperties()
      if (this.$v) this.$v.$reset()
    },
  },
  validations() {
    return this.validators
  },
  watch: {
    'selectedProduct.isGramaje': {
      immediate: true,
      handler() {
        this.initializeWastedForm()
      },
    },
  },
  beforeMount() {
    this.$root.$on('productDetailTabsWasChanged', this.hideWastedProductsDialog)
    this.$root.$on(
      'productStoreWasUpdated',
      this.productStoreWasUpdatedListener
    )
    rendererEventsService.subscribe(
      STORE_INVENTORY_EVENTS.replyChannel,
      this.wastedProductsListener
    )
  },
  mounted() {
    this.setInputsProperties()
  },
  beforeDestroy() {
    this.hideWastedProductsDialog()
    this.$root.$off(
      'productDetailTabsWasChanged',
      this.hideWastedProductsDialog
    )
    this.$root.$off(
      'productStoreWasUpdated',
      this.productStoreWasUpdatedListener
    )
    rendererEventsService.removeListener(
      STORE_INVENTORY_EVENTS.replyChannel,
      this.wastedProductsListener
    )
  },
}
</script>
