<template>
  <div>
    <FormattedText
      intl
      type="body-1"
      class-name="font-weight-bold"
      :value="`promotion.ticket.discount.${typeDiscount}Discount`"
      class="mb-1"
    />
    <p class="mb-5 text-body-2 grey--text">
      <v-icon class="text-h6" color="grey ">mdi-information </v-icon>
      {{ getTranslatedText('promotion.ticket.discount.info') }}
      (<v-icon color="grey " small>mdi-swap-horizontal</v-icon>)
    </p>
    <div class="d-flex align-center">
      <DiscountPromotionForm
        class="flex-grow-1"
        ref="promotionForm"
        :form="formData"
      />
      <v-tooltip v-if="showDeleteButton" right>
        <template v-slot:activator="{ on, attrs }">
          <v-btn
            v-bind="attrs"
            v-on="on"
            icon
            class="mb-8 ml-2"
            color="error"
            @click="deletePromotion()"
          >
            <v-icon>mdi-delete</v-icon>
          </v-btn>
        </template>
        <span>{{
          getTranslatedText('promotion.ticket.discount.deleteDiscount')
        }}</span>
      </v-tooltip>
    </div>
  </div>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'
import DiscountPromotionForm from '@/components/shared/DiscountPromotionForm'

export default {
  name: 'TicketDiscount',
  components: { DiscountPromotionForm, FormattedText },
  props: {
    formData: {
      type: Object,
      required: true,
    },
    typeDiscount: {
      type: String,
      required: true,
    },
    showDeleteButton: {
      type: Boolean,
      default: false,
    },
  },
  methods: {
    getTranslatedText,
    deletePromotion() {
      this.$refs.promotionForm.resetValue()
    },
  },
}
</script>
