<template>
  <v-row>
    <v-col cols="12">
      <FormattedText
        intl
        value="purchaseView.productTriangulationDialog.othersFields.title"
        type="text-h6"
      />
    </v-col>
    <v-row class="pl-3" v-if="product.factor > 1">
      <v-col cols="3">
        <v-text-field
          v-if="!hasInventoryLimitation"
          id="existencesPack-input"
          ref="existencesPack"
          type="number"
          v-model="inputs.existencesPack"
          class="custom-text-field-large"
          filled
          rounded
          color="primary"
          suffix="paq"
          :label="
            getTranslatedText(
              'purchaseView.productTriangulationDialog.othersFields.quantity'
            )
          "
          :error-messages="onValidateFields('existencesPack')"
          @focus="currentFocus = 'existencesPack'"
          @input="onExistencesPackInput"
          @blur="$v.inputs.existencesPack.$touch()"
          @keydown.enter="onEnterEvent"
        />
        <SingleTextFieldWidget
          v-if="hasInventoryLimitation"
          class="custom-text-field-large"
          filled
          rounded
          color="primary"
          :config="{
            label: getTranslatedText(
              'purchaseView.productTriangulationDialog.othersFields.quantity'
            ),
            value: inputs.existencesPack,
            readonly: true,
            suffix: 'paq',
          }"
        />
      </v-col>
      <v-col cols="3">
        <MoneyTextField
          ref="pricePack"
          v-model.number="inputs.pricePack"
          :config="{
            fieldName: 'pricePack',
            label: this.getTranslatedText(
              'salesView.byWeightSelector.pricePackage'
            ),
            color: 'primary',
            filled: true,
            rounded: true,
            class: 'custom-text-field-large price',
            errorMessage: onValidateFields,
          }"
          :options="moneyInputsConfig"
          @focus="currentFocus = 'pricePack'"
          @input="onPricePackInput"
          @blur="$v.inputs.pricePack.$touch()"
          @enter="onEnterEvent"
        />
      </v-col>
      <v-col cols="3">
        <SingleTextFieldWidget
          :config="{
            label: getTranslatedText(
              'purchaseView.productTriangulationDialog.othersFields.margin'
            ),
            value: averageMarginPack,
            readonly: true,
          }"
        />
      </v-col>
    </v-row>
    <v-row class="pl-3 mt-0 pt-0">
      <v-col cols="3" class="pt-0">
        <v-text-field
          v-if="!hasInventoryLimitation"
          id="existences-input"
          ref="existences"
          v-model="inputs.existences"
          type="number"
          class="custom-text-field-large"
          filled
          rounded
          color="primary"
          :suffix="typeUnit"
          :label="
            getTranslatedText(
              'purchaseView.productTriangulationDialog.othersFields.quantity'
            )
          "
          :error-messages="onValidateFields('existences')"
          @focus="currentFocus = 'existences'"
          @change="onExistencesChange"
          @blur="$v.inputs.existences.$touch()"
          @keydown.enter="onEnterEvent"
        />
        <SingleTextFieldWidget
          v-if="hasInventoryLimitation"
          class="custom-text-field-large"
          filled
          rounded
          color="primary"
          :config="{
            label: getTranslatedText(
              'purchaseView.productTriangulationDialog.othersFields.quantity'
            ),
            value: inputs.existences,
            readonly: true,
            suffix: typeUnit,
          }"
        />
      </v-col>
      <v-col cols="3" class="pt-0">
        <MoneyTextField
          ref="price"
          v-model.number="inputs.price"
          :config="{
            fieldName: 'price',
            label: getPriceLabel(),
            color: 'primary',
            filled: true,
            rounded: true,
            class: 'custom-text-field-large price',
            errorMessage: onValidateFields,
          }"
          :options="moneyInputsConfig"
          @focus="currentFocus = 'price'"
          @input="onPriceInput"
          @blur="$v.inputs.price.$touch()"
          @enter="onEnterEvent"
        />
      </v-col>
      <v-col cols="3" class="pt-0">
        <SingleTextFieldWidget
          :config="{
            label: getTranslatedText(
              'purchaseView.productTriangulationDialog.othersFields.margin'
            ),
            value: averageMargin,
            readonly: true,
          }"
        />
      </v-col>
    </v-row>
  </v-row>
</template>

<script>
import { mapState } from 'vuex'

import productsVariables from '@/config/products'

import { getTranslatedText } from '@/tools/data'
import { moneyTextFieldCountryConfig } from '@/tools/numbersFormat'

import FormattedText from '@/components/shared/FormattedText'
import SingleTextFieldWidget from '@/components/shared/SingleTextFieldWidget'
import MoneyTextField from '@/components/shared/MoneyTextField'
import {
  getPackageMarginValue,
  getPieceMarginValue,
} from '@/components/ProductDetail/DetailsTab/tools'

import productTriangulation from '@/mixins/purchases/productTriangulation'

export default {
  name: 'OthersFieldsForm',
  components: { FormattedText, SingleTextFieldWidget, MoneyTextField },
  props: {
    product: {
      type: Object,
      required: true,
    },
    productType: {
      type: String,
      required: true,
    },
    onEnterEvent: {
      type: Function,
    },
    inputs: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      currentFocus: '',
      hasInventoryLimitation: false,
      moneyInputsConfig: this.getMoneyInputsConfig(),
    }
  },
  computed: {
    ...mapState('usersView', ['selectedUser']),
    averageMargin() {
      const { pricePack, price, cost } = this.inputs
      const factor = this.product.factor
      const tax = this.applyTax()
      return factor > 1
        ? getPieceMarginValue(pricePack, price, cost, factor, tax)
        : getPackageMarginValue(price, cost, tax)
    },
    averageMarginPack() {
      const { pricePack, cost } = this.inputs
      const tax = this.applyTax()
      return getPackageMarginValue(pricePack, cost, tax)
    },
    typeUnit() {
      const factor = this.product.factor
      if (factor > 1) {
        return 'pzs'
      } else if (this.product.isGramaje === 1) {
        return 'g'
      }
      return 'uds'
    },
  },
  methods: {
    getTranslatedText,
    getMoneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
    onExistencesChange() {
      if (this.currentFocus !== 'existences') return
      const { factor } = this.product
      if (factor > 1) {
        const totalExistences =
          Math.floor(this.inputs.existencesPack) * factor +
          Math.floor(this.inputs.existences)
        this.inputs.existencesPack = Math.floor(totalExistences / factor)
        const excess = Math.floor(totalExistences % factor)
        if (Math.floor(this.inputs.existences) !== excess)
          this.inputs.existences = excess
      }
    },
    onPriceInput() {
      if (this.currentFocus !== 'price') return
    },
    onExistencesPackInput() {
      if (this.currentFocus !== 'existencesPack') return
    },
    onPricePackInput() {
      if (this.currentFocus !== 'pricePack') return
    },
    getPriceLabel() {
      switch (this.productType) {
        case 'isPieceProduct':
          return this.getTranslatedText('salesView.byWeightSelector.pricePiece')
        case 'isByWeightProduct':
          return this.getTranslatedText('salesView.byWeightSelector.priceUnit')
        case 'isOpenProductPackage':
          return this.getTranslatedText('salesView.byWeightSelector.pricePiece')
        case 'isOpenProductPiece':
          return this.getTranslatedText('salesView.byWeightSelector.pricePiece')
      }
    },
    setFormValidators() {
      const validations = {
        inputs: {
          price: this.setMoneyValidator(1000000, 4),
          existences: this.setDefaultValidators(
            productsVariables.STOCK_MAX_VALUE,
            true
          ),
        },
      }
      if (this.product.factor > 1) {
        validations.inputs = {
          ...validations.inputs,
          pricePack: this.setMoneyValidator(1000000, 4),
          existencesPack: this.setDefaultValidators(
            productsVariables.STOCK_MAX_VALUE,
            true
          ),
        }
      }
      return validations
    },
  },
  mixins: [productTriangulation],
  validations() {
    return this.setFormValidators()
  },
  mounted() {
    this.hasInventoryLimitation = !(
      this.selectedUser.id === 1 || this.selectedUser.inventoryPermission === 0
    )
  },
}
</script>

<style lang="scss" scoped>
.price {
  max-width: 214px;
}
.database-price {
  color: var(--v-salesPrimary-base);
}
</style>
