const setConfig = (state, methods, text) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    title: text.title,
    icon: 'mdi-alert-circle',
    messages: text.messages,
    titleBackground: '',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 300,
    maxWidth: 500,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => {
      methods.closeDialog()
      setTimeout(() => {
        methods.enableEdit()
      }, 750)
    },
  },
})

export default setConfig
