<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'

import { validateBarcode } from '@/tools/customValidations'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'

import {
  getSelectedProductByRoute,
  updateSelectedProductByRoute,
} from '@/components/ProductDetail/selectedProduct.tools'

import setDialogConfig from '@/components/ProductDetail/Footer/DeleteProductDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'DeleteProductDialog',
  components: { DialogCard },
  data() {
    return {
      openProductInSale: false,
      barcode: null,
    }
  },
  computed: {
    ...mapState('productsView', ['deleteProductDialog']),
    ...mapState('sales', ['sales']),
    ...getSelectedProductByRoute(),
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.deleteProductDialog.isOpen,
          routeName: this.$route.name,
        },
        {
          closeDialog: this.closeDialog,
          deleteProduct: this.openProductInSaleDialog,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('productsView', [
      productsViewActions.setDeleteProductDialogStatus,
      productsViewActions.setProductInSaleDialogStatus,
    ]),
    ...updateSelectedProductByRoute(),
    closeDialog() {
      this[productsViewActions.setDeleteProductDialogStatus](false)
    },
    openProductInSaleDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'DeleteProductDialog',
        name: 'Confirm',
      })
      this.sales.forEach(sale => {
        if (sale.items.find(item => item.id === this.selectedProduct.id))
          this.openProductInSale = true
      })
      rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
        event: PURCHASES_DB_API_EVENTS.events.checkItemInDraftPurchases.name,
        data: {
          productsId: [this.selectedProduct.id],
        },
      })
    },
    async purchaseOrderListener(event, payload) {
      const purchaseEvents = PURCHASES_DB_API_EVENTS.events
      const replies = {
        [purchaseEvents.checkItemInDraftPurchases.replies.success]: () => {
          const { productsInDraft } = payload.data
          if (this.openProductInSale || productsInDraft) {
            this.$track({
              type: 'system',
              action: 'check_products_in_tickets',
              category: this.$route.name,
              screen: 'DeleteProductDialog',
              name: 'Show product in ticket',
            })
            this[productsViewActions.setProductInSaleDialogStatus](true)
            return
          }
          this.$track({
            type: 'system',
            action: 'check_products_in_tickets',
            category: this.$route.name,
            screen: 'DeleteProductDialog',
            name: 'Delete product',
          })
          this.$root.$emit('productMustBeDeleted')
        },
        [purchaseEvents.checkItemInDraftPurchases.replies.error]: () => {
          notificationsService.showError(
            'notification.products.errorDeleting',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseOrderListener
    )
  },
  mounted() {
    this.$barcodeScanner.destroy()
    this.$barcodeScanner.init(barcode => {
      if (validateBarcode(barcode)) {
        this.barcode = barcode
      }
    })
    this.$root.$on('productDetailTabsWasChanged', this.closeDialog)
  },
  beforeDestroy() {
    this.$barcodeScanner.destroy()
    this.$root.$emit('enable-scanner', {})
    this.$root.$off('productDetailTabsWasChanged', this.closeDialog)
    rendererEventsService.removeListener(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseOrderListener
    )
    this.closeDialog()
  },
}
</script>
