const setConfig = (state, methods) => ({
  dialogData: {
    opened: state.isOpen,
    maxWidth: 650,
    height: state.onlyOnePromotionOption ? 320 : 400,
    icon: 'mdi-sale',
    title: state.hasPromotion
      ? 'promotion.ticket.edit'
      : 'promotion.ticket.add',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    isAcceptButtonDisabled: state.v.$invalid,
    onClickCancel: () => {
      methods.closeDialog()
    },
    onClickAccept: () => methods.applyPromotion(),
  },
  formData: {
    inputs: state.inputs,
    v: state.v,
    cost: state.cost,
  },
})

export default setConfig
