<template>
  <v-tooltip bottom>
    <template v-slot:activator="{ on }">
      <v-card
        id="pay-button"
        v-on="on"
        :flat="config.payButton.flat"
        :color="config.payButton.color"
        :style="`border-radius: ${config.payButton.borderRadius};`"
        :class="config.payButton.class"
        :disabled="disabledButton"
        @click="config.payButton.onClick"
        v-track:click="{
          category: $route.name,
          screen: 'PayButton',
          name: 'Pay ticket',
        }"
      >
        <div class="d-flex justify-space-between">
          <div
            v-for="column in config.payButton.columns"
            :key="column.id"
            :class="column.class"
          >
            <div v-for="element in column.elements" :key="element.id">
              <div v-if="'columns' in element" class="d-flex">
                <div v-for="text in element.columns" :key="text.id">
                  <v-icon
                    v-if="text.type === 'icon'"
                    :size="text.size"
                    :color="text.color"
                  >
                    {{ text.icon }}
                  </v-icon>
                  <FormattedText v-else v-bind="text" />
                </div>
              </div>
              <div v-else>
                <FormattedText v-bind="element" />
              </div>
            </div>
          </div>
        </div>
      </v-card>
    </template>
    <FormattedText :value="config.payButton.tooltip" color="white" intl />
  </v-tooltip>
</template>

<script>
import { promotions } from '@/config/promotions'

import setConfig from '@/components/shared/PayButton/config'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'PayButton',
  components: { FormattedText },
  props: {
    ticket: {
      type: Object,
      required: true,
    },
    getPrice: {
      type: Function,
      required: true,
    },
  },
  computed: {
    fromPage() {
      return this.$route.name.toLowerCase()
    },
    disabledButton() {
      if (!this.ticket) return true
      const totalTicket = this.getPrice(
        this.ticket.items,
        this.ticket.returnItems || []
      )
      if (
        totalTicket <= 0 &&
        this.allProductsHasFreePromotion &&
        this.ticket.returnItems &&
        this.ticket.returnItems.length === 0
      ) {
        return false
      }
      return totalTicket <= 0
    },
    allProductsHasFreePromotion() {
      const freeProductPromotion = [
        promotions.PURCHASE_ITEM_FREE_PRODUCT,
        promotions.SALE_ITEM_FREE_PRODUCT,
      ]
      return (
        this.ticket.items.length &&
        !this.ticket.items.some(
          item => !freeProductPromotion.includes(item.promotionTypeId)
        )
      )
    },
    config() {
      return setConfig(
        {
          data: this.ticket,
          lang: this.$vuetify.lang,
          isDarkMode: this.$vuetify.theme.isDark,
          fromPage: this.fromPage,
          disabledButton: this.disabledButton,
        },
        {
          getPrice: this.getPrice,
          onClickPayButton: () => this.$emit('payButtonWasClicked'),
        }
      )
    },
  },
}
</script>
