<template>
  <div :class="config.type === 'error' ? 'default-alert' : 'custom-alert'">
    <v-alert
      :value="show"
      :type="config.type"
      :icon="config.icon"
      :dismissible="!config.alertFixed"
      transition="scale-transition"
      :prominent="config.big || true"
    >
      <FormattedText
        v-if="config.title"
        intl
        :value="config.title"
        :color="config.textColor"
        type="text-h5 font-weight-bold"
        className="ml-4 font-weight-bold"
      />
      <FormattedText
        v-if="config.subTitle"
        intl
        :value="config.subTitle"
        :color="config.textColor"
        className="ml-4"
      />
      <slot />
    </v-alert>
  </div>
</template>

<script>
import audioService from '@/services/renderer/audio'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'Alert',
  components: { FormattedText },
  props: {
    config: {
      type: Object,
      required: true,
    },
    show: {
      type: Boolean,
      default: false,
    },
  },
  watch: {
    config(newValue, oldValue) {
      if (newValue.type !== oldValue.type) {
        switch (newValue.type) {
          case 'error':
            audioService.play('error')
            break
          case 'warning':
            audioService.play('warning')
            break
        }
      }
    },
  },
}
</script>

<style lang="scss" scoped>
.custom-alert {
  :deep(.v-alert) {
    margin-bottom: 0;
    .v-alert__icon.v-icon {
      color: var(--v-textPrimary-base);
    }
    .v-btn__content {
      color: var(--v-textPrimary-base);
    }
  }
}
.default-alert {
  :deep(.v-alert) {
    margin-bottom: 0;
  }
}
</style>
