import { required } from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-alert-circle',
    title: 'productsView.details.reportDialog.title',
    titleBackground: '',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['productsView.details.reportDialog.message'],
    height: 380,
    maxWidth: 500,
    acceptButtonText: 'shared.send',
    id: 'report-product-form',
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.reportProduct(),
  },
  fields: [
    {
      id: 'type',
      type: 'select',
      items: getListErrorsType(state.product, methods.getTranslatedText),
      label: 'shared.error',
      errorMessage: 'productsView.details.reportDialog.filledType',
      required: true,
      validators: { required },
    },
    {
      id: 'solution',
      type: 'input',
      label: getInputHint(state.inputs['type']),
      errorMessage: 'productsView.details.reportDialog.filledInput',
      required: true,
      validators: { required },
    },
  ],
  id: 'report-product-form',
})

const getListErrorsType = (product, translateFunction) => {
  let typeList = []
  typeList.push({
    id: '1',
    text: translateFunction('productsView.details.reportDialog.typeErrorName'),
  })
  if (!(product.isGramaje === 1) && !(product.factor > 1)) {
    typeList.push({
      id: '2',
      text: translateFunction(
        'productsView.details.reportDialog.typeErrorOpen'
      ),
    })
  }
  if (product.factor > 1) {
    typeList.push({
      id: '5',
      text: translateFunction(
        'productsView.details.reportDialog.typeErrorPieces'
      ),
    })
  }
  product.isGramaje === 1
    ? typeList.push({
        id: '4',
        text: translateFunction(
          'productsView.details.reportDialog.typeErrorUnits'
        ),
      })
    : typeList.push({
        id: '3',
        text: translateFunction(
          'productsView.details.reportDialog.typeErrorByWeight'
        ),
      })
  return typeList
}

const getInputHint = errorId => {
  switch (errorId) {
    case '1':
      return 'productsView.details.reportDialog.inputTypeName'
    case '5':
      return 'productsView.details.reportDialog.inputTypePieces'
    case '2':
    case '3':
    case '4':
      return 'productsView.details.reportDialog.inputTypeSoldBy'
    default:
      return 'productsView.details.reportDialog.inputHint'
  }
}

export default setConfig
