import ChipsGroup from '@/components/shared/ChipsGroup'
import ProductBrandCardList from '@/components/shared/ProductBrandCardList'
import ProductTriangulationForm from '@/components/PurchasesView/ProductTriangulationDialog/ProductTriangulationForm'

const setConfig = (state, methods) => ({
  state,
  methods,
  stepper: {
    data: {
      product: state.product,
      productError: state.productError,
      selectedByWeightCategory: state.selectedByWeightCategory,
    },
    steps: [
      {
        id: 'type',
        editable: true,
        complete: false,
        name: 'salesView.byWeightSelector.type',
        component: ChipsGroup,
      },
      {
        id: 'brand',
        editable: false,
        complete: false,
        name: 'salesView.byWeightSelector.branch',
        component: ProductBrandCardList,
      },
    ],
    finalStep: {
      enable: true,
      name: 'salesView.byWeightSelector.amount',
      component: ProductTriangulationForm,
      hook: methods.products.getProductByUpc,
    },
    errorAlertConfig: {
      icon: 'mdi-alert-circle-outline',
      type: 'error',
      textColor: 'error-base',
      text: 'salesView.byWeightSelector.alerts.productNotFound',
    },
    onFormEnterEvent: methods.dialog.onSubmitForm,
  },
})

export default setConfig
