<template>
  <v-card
    flat
    color="cardBackgroundAlternative"
    class="rounded-lg pointer"
    height="180px"
    :disabled="isCardDisabled"
  >
    <div class="image-section">
      <div
        class="image-container"
        :class="data.airTime === 1 ? 'big-image' : 'normal-image'"
      >
        <img :src="cardImage" class="product-image" />
      </div>
    </div>
    <v-card-title class="name-container justify-center align-center pa-0">
      <FormattedText
        :value="data.name"
        type="text-subtitle-1"
        color="textPrimary"
        className="font-weight-bold product-name"
      />
    </v-card-title>
  </v-card>
</template>

<script>
import { mapState } from 'vuex'
import { isNil, isEmpty } from 'ramda'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'ProductImageCard',
  components: { FormattedText },
  props: {
    data: {
      type: Object,
      required: true,
    },
  },
  computed: {
    ...mapState('app', {
      assetsPath: state => state.paths.assets,
    }),
    ...mapState('airtimeServices', ['balance']),
    cardImage() {
      if (isNil(this.data.image) || isEmpty(this.data.image))
        return require(`@/assets/logos/Icono_PlayStore.svg`)

      return this.data.image.substring(4, 0) === 'data'
        ? this.data.image
        : this.getImageSRC(this.data.image)
    },
    isCardDisabled() {
      return this.data.airTime === 1 && this.balance.amount <= 0
    },
  },
  methods: {
    getImageSRC(fileName) {
      return `file://${this.assetsPath}/${fileName}`
    },
  },
}
</script>

<style lang="scss" scoped>
.image-section {
  background-color: var(--v-cardBackgroundSecondary-base);
  .image-container {
    margin: auto;
    height: 130px;
    .product-image {
      display: block;
      height: 100%;
      margin-left: auto;
      margin-right: auto;
    }
  }
}
.name-container {
  height: 50px;
  word-break: normal;
  text-align: center;
  line-height: 0;
  :deep(.product-name) {
    line-height: 1.25rem !important;
    word-wrap: normal;
    overflow-wrap: normal;
  }
}
.big-image {
  img {
    padding: 20px;
    height: 100%;
    width: 100%;
    object-fit: contain;
  }
}
.normal-image {
  img {
    height: 100%;
    width: 100%;
    object-fit: contain;
  }
}
</style>
