<template>
  <DialogCard :config="config.dialogData">
    <FormattedText
      type="text-body-1"
      color="textPrimary"
      class="body-text"
      :value="description"
    />
    <v-alert dense text type="warning" class="my-4">
      <div>
        <FormattedText
          type="text-body-1"
          color="orange"
          className="font-weight-bold"
          value="productsView.changeOpenGramajeDialog.alertTitle"
          intl
        />
      </div>
      <FormattedText
        color="orange"
        value="productsView.changeOpenGramajeDialog.alert"
        intl
      />
    </v-alert>
    <div>
      <v-text-field
        id="quantity-input"
        ref="quantity"
        v-model.number="inputs.quantity"
        class="custom-text-field-large"
        filled
        rounded
        color="primary"
        :label="quantityLabel"
        :error-messages="onValidateFields('quantity')"
        @blur="$v.inputs.quantity.$touch()"
        @keydown.enter="changeInventory"
      />
      <MoneyTextField
        id="price-input"
        ref="price"
        v-model.number="inputs.price"
        :config="{
          fieldName: 'price',
          label: priceLabel,
          color: 'primary',
          filled: true,
          rounded: true,
          class: 'custom-text-field price',
          backgroundColor: 'cardBackgroundSecondary',
          errorMessage: onValidateFields,
        }"
        :options="moneyInputsConfig"
        @blur="$v.inputs.price.$touch()"
        @enter="changeInventory"
      />
    </div>
  </DialogCard>
</template>

<script>
import { has } from 'ramda'
import { mapActions, mapState } from 'vuex'

import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import { storeInventory as storeInventoryMapper } from '@/config/storeMapper'

import { getTranslatedText, mapStoreObject } from '@/tools/data'

import {
  formatNumberToDb,
  moneyTextFieldCountryConfig,
} from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'

import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'
import setConfig from '@/components/ProductDetail/ChangeOpenGramajeDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import FormattedText from '@/components/shared/FormattedText'
import MoneyTextField from '@/components/shared/MoneyTextField'
import {
  setDefaultValidators,
  setMoneyValidator,
} from '@/components/PurchasesView/ReturnProductDialog/ReturnProductForm/tools'

export default {
  name: 'ChangeOpenGramajeDialog',
  components: { DialogCard, FormattedText, MoneyTextField },
  data() {
    return {
      moneyInputsConfig: this.getMoneyInputsConfig(),
      inputs: {
        quantity: null,
        price: null,
      },
    }
  },
  computed: {
    ...mapState('productsView', ['changeOpenGramajeDialog']),
    ...mapState('usersView', ['selectedUser']),
    ...getSelectedProductByRoute(),
    description() {
      const changeText =
        this.selectedProduct.isGramaje === 1
          ? this.getTranslatedText(
              'productsView.changeOpenGramajeDialog.gramsToPieces'
            )
          : this.getTranslatedText(
              'productsView.changeOpenGramajeDialog.piecesToGrams'
            )
      return this.getTranslatedText(
        'productsView.changeOpenGramajeDialog.description',
        [this.selectedProduct.name, changeText]
      )
    },
    priceLabel() {
      return this.selectedProduct.isGramaje === 1
        ? this.getTranslatedText(
            'productsView.changeOpenGramajeDialog.newPriceGrams'
          )
        : this.getTranslatedText(
            'productsView.changeOpenGramajeDialog.newPricePieces'
          )
    },
    quantityLabel() {
      return this.selectedProduct.isGramaje === 1
        ? this.getTranslatedText(
            'productsView.changeOpenGramajeDialog.newQuantityGrams'
          )
        : this.getTranslatedText(
            'productsView.changeOpenGramajeDialog.newQuantityPieces'
          )
    },
    config() {
      return setConfig(
        {
          isOpen: this.changeOpenGramajeDialog.isOpen,
          formInvalid: this.$v.$invalid,
        },
        {
          closeDialog: this.closeDialog,
          changeInventory: this.changeInventory,
        }
      )
    },
  },
  methods: {
    ...mapActions('productsView', [
      productsViewActions.setChangeOpenGramajeDialog,
    ]),
    getTranslatedText,
    getMoneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
    closeDialog() {
      this.$root.$emit('changeOpenGramajeCanceled')
      this[productsViewActions.setChangeOpenGramajeDialog](false)
    },
    changeInventory() {
      if (this.$v.$invalid) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'ChangeOpenGramajeDialog',
        name: 'Confirm change unit measure',
      })
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
        data: {
          isUnitMeasureChange: true,
          username: this.selectedUser.name,
          productToUpdated: {
            id: this.selectedProduct.id,
            data: mapStoreObject(
              {
                cost: formatNumberToDb(-1),
                price: formatNumberToDb(this.inputs.price),
                quantity: this.inputs.quantity,
                isGramaje: this.selectedProduct.isGramaje,
              },
              storeInventoryMapper,
              true
            ),
          },
        },
      })
    },
    onValidateFields(input) {
      const errors = []
      if (
        !Object.keys(this.$v.inputs).includes(input) ||
        !this.$v.inputs[input].$dirty
      )
        return errors
      has('required')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].required &&
        errors.push(this.getTranslatedText('salesView.form.errors.empty'))
      has('minValue')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].minValue &&
        errors.push(this.getTranslatedText('salesView.form.errors.minValue'))
      has('maxValue')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].maxValue &&
        errors.push(this.getTranslatedText('salesView.form.errors.maxValue'))
      has('maxDecimals')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].maxDecimals &&
        errors.push(this.getTranslatedText('salesView.form.errors.maxValue'))
      has('integer')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].integer &&
        errors.push(this.getTranslatedText('salesView.form.errors.decimal'))
      return errors
    },
    getInitialFocus() {
      setTimeout(() => {
        this.$refs.quantity.focus()
      }, 100)
    },
    storeInventoryListener(event, payload) {
      const events = STORE_INVENTORY_DB_API_EVENTS.events
      const replies = {
        [events.updateById.replies.success]: () =>
          this[productsViewActions.setChangeOpenGramajeDialog](false),
        [events.updateById.replies.error]: () =>
          this[productsViewActions.setChangeOpenGramajeDialog](false),
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  validations() {
    return {
      inputs: {
        quantity: setDefaultValidators(),
        price: setMoneyValidator(1000000, 2),
      },
    }
  },
  created() {
    rendererEventsService.subscribe(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.storeInventoryListener
    )
  },
  mounted() {
    this.getInitialFocus()
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.storeInventoryListener
    )
    this[productsViewActions.setChangeOpenGramajeDialog](false)
  },
}
</script>
