<template>
  <div>
    <v-dialog
      v-model="confirmPurchaseDialog.isOpen"
      :overlay-opacity="0.15"
      max-width="600px"
      :hide-overlay="tourEnabled"
      :content-class="
        tourEnabled ? 'below-tour default-dialog' : 'default-dialog'
      "
      :persistent="tourEnabled"
      @click:outside="closeDialog"
    >
      <v-card
        id="confirm-purchase-dialog"
        flat
        :height="heightPopup"
        class="confirmPurchaseDialog"
        color="cardBackgroundPrimary"
      >
        <v-card-title class="d-flex justify-space-between align-center">
          <FormattedText
            intl
            type="text-h4"
            value="purchaseView.confirmDialog.confrimPurchase"
          />
          <v-avatar width="100px" height="80px" rounded="lg">
            <v-img contain :src="logoPath" />
          </v-avatar>
        </v-card-title>
        <v-card-text class="d-flex flex-column pt-4">
          <FormattedText
            intl
            type="text-h6"
            :value="
              `${
                isCashPayOption
                  ? 'purchaseView.confirmDialog.purchaseDetails'
                  : 'purchaseView.confirmDialog.creditPurchaseDetails'
              }`
            "
          />
          <v-divider />
          <div class="my-4 d-flex flex-column">
            <p
              v-for="(detail, index) in purchaseDetails"
              :key="`detail-${index}`"
              class="text-subtitle-1 mb-2"
            >
              {{ getTranslatedText(detail[0], detail[1]) }}
            </p>
          </div>
          <v-divider />
          <div class="py-8 text-center">
            <FormattedText
              v-if="hasPromotion"
              type="text-h5"
              class="mx-auto"
              color="grey"
              className="text-decoration-line-through"
              :value="totalPrice"
            />
            <FormattedText
              type="text-h3"
              class="mx-auto"
              className="font-weight-bold"
              :value="totalPriceWithPromotion"
            />
          </div>
        </v-card-text>
        <v-card-actions>
          <v-spacer />
          <v-btn color="error" @click="closeDialog" ref="cancelPurchaseOrder">
            <FormattedText intl value="shared.cancel" color="white" />
          </v-btn>
          <v-tooltip v-if="selectedPurchase.payOption === 'cash'" bottom>
            <template #activator="{ on, attrs }">
              <v-btn
                v-on="on"
                v-bind="attrs"
                color="primary"
                id="dialog-accept-confirm-external-purchase-dialog"
                :disabled="tourEnabled"
                @click="confirmPurchase(true)"
              >
                <FormattedText
                  intl
                  value="purchaseView.confirmDialog.externalCashRegister"
                  color="white"
                />
              </v-btn>
            </template>
            <span>{{
              getTranslatedText(
                'purchaseView.confirmDialog.payExternalCashRegister'
              )
            }}</span>
          </v-tooltip>
          <v-tooltip bottom :disabled="selectedPurchase.payOption !== 'cash'">
            <template #activator="{ on, attrs }">
              <v-btn
                v-on="on"
                v-bind="attrs"
                color="primary"
                @click="confirmPurchase(false)"
                id="dialog-accept-confirm-purchase-dialog"
              >
                <FormattedText
                  intl
                  :value="
                    isCashPayOption
                      ? 'purchaseView.confirmDialog.mainCashRegister'
                      : 'purchaseView.confirmDialog.confrimPurchaseBtn'
                  "
                  color="white"
                />
              </v-btn>
            </template>
            <span>{{
              getTranslatedText(
                'purchaseView.confirmDialog.payMainCashRegister'
              )
            }}</span>
          </v-tooltip>
        </v-card-actions>
      </v-card>
    </v-dialog>
    <ExternalCashRegisterInfo @userHasBeenInformed="finishPurchase(true)" />
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'

import { getTranslatedText } from '@/tools/data'
import {
  formatNumberFromDbToCurrency,
  roundToNearestMultiple,
} from '@/tools/numbersFormat'
import { getPromotionTicketToDB, discountTypes } from '@/tools/promotions'

import rendererEventsService from '@/services/renderer/rendererEvents'

import purchasesViewActions from '@/store/purchasesView/actions.types'
import appActions from '@/store/app/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import tools from '@/components/PurchasesView/ConfirmPurchaseDialog/confirmPurchaseDialog.tools'
import ExternalCashRegisterInfo from '@/components/shared/ExternalCashRegisterInfo'

export default {
  name: 'ConfirmPurchaseDialog',
  components: { ExternalCashRegisterInfo, FormattedText },
  computed: {
    ...mapState('app', {
      assetsPath: state => state.paths.assets,
    }),
    ...mapState('purchasesView', [
      'confirmPurchaseDialog',
      'selectedPurchase',
      'currentPurchase',
      'tourEnabled',
    ]),
    ...mapState('vendorsView', ['selectedVendor']),
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    purchaseDetails() {
      return tools.getDetails.call(this)
    },
    heightPopup() {
      if (this.hasPromotion) {
        return this.isCashPayOption ? 620 : 655
      }
      return this.isCashPayOption ? 560 : 580
    },
    isCashPayOption() {
      return this.selectedPurchase.payOption === 'cash'
    },
    hasPromotion() {
      return this.selectedPurchase.promotion > 0
    },
    logoPath() {
      return tools.getLogoPath.call(this)
    },
    totalPrice() {
      return formatNumberFromDbToCurrency(tools.getPriceToDb.call(this))
    },
    totalPriceWithPromotion() {
      if (!this.hasPromotion) {
        return this.totalPrice
      }
      const discount = discountTypes.isDiscountPerAmount(
        this.selectedPurchase.promotion_type
      )
        ? this.selectedPurchase.promotion
        : tools.getDiscountAmountFromPercent.call(this)
      return formatNumberFromDbToCurrency(
        tools.getPriceToDb.call(this) - discount
      )
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
    roundToNearestMultiple,
    ...mapActions('purchasesView', [
      purchasesViewActions.toggleConfirmPurchaseDialogStatus,
      purchasesViewActions.setFinishingPurchaseStatus,
      purchasesViewActions.toggleOverCreditLimitDialogStatus,
    ]),
    ...mapActions('app', [appActions.toggleExternalCashRegisterInfoDialog]),
    closeDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'ConfirmPurchaseDialog',
        name: 'Cancel',
      })
      if (this.tourEnabled) this.$root.$emit('purchase-cancel-tour')
      this[purchasesViewActions.toggleConfirmPurchaseDialogStatus]()
    },
    confirmPurchase(isFromExternalCashRegister = false) {
      if (this.currentPurchase.isFinishing === true)
        return this.$track({
          type: 'interaction',
          action: 'click',
          category: 'Purchases',
          screen: 'ConfirmPurchaseDialog',
          name: 'Confirm',
        })
      this.isCashPayOption
        ? this.showInfoDialog(isFromExternalCashRegister)
        : this.checkCreditLimit()
    },
    showInfoDialog(isFromExternalCashRegister) {
      if (!isFromExternalCashRegister) {
        this.$track({
          type: 'system',
          action: 'confirm_purchase',
          category: 'Purchases',
          screen: 'ConfirmPurchaseDialog',
          name: 'Finish purchase',
        })
        this.finishPurchase(isFromExternalCashRegister)
        return
      }
      this.$track({
        type: 'system',
        action: 'confirm_purchase',
        category: 'Purchases',
        screen: 'ConfirmPurchaseDialog',
        name: 'Show external cash register dialog',
      })
      this[appActions.toggleExternalCashRegisterInfoDialog](true)
    },
    finishPurchase(isFromExternalCashRegister) {
      this[purchasesViewActions.setFinishingPurchaseStatus](true)
      this.selectedPurchase.cost = tools.getPriceToDb.call(this)
      const { payOption, cost } = this.selectedPurchase
      this.$loading.show('finishPurchase')
      rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
        event: PURCHASES_DB_API_EVENTS.events.finishPurchase.name,
        data: {
          purchaseData: {
            ...this.selectedPurchase,
            payOption:
              payOption === 'credit' && cost === 0 ? 'cash' : payOption,
            promotion: getPromotionTicketToDB(this.selectedPurchase),
          },
          userId: this.selectedUser.id,
          username: this.selectedUser.name,
          estimatedCash: tools.getEstimatedCash.call(this),
          isFromExternalCashRegister:
            typeof isFromExternalCashRegister === 'boolean'
              ? isFromExternalCashRegister
              : false,
        },
      })
      this[purchasesViewActions.toggleConfirmPurchaseDialogStatus]()
    },
    checkCreditLimit() {
      if (tools.isCreditLessThanDebtLimit.call(this)) {
        this.$track({
          type: 'system',
          action: 'confirm_purchase',
          category: 'Purchases',
          screen: 'ConfirmPurchaseDialog',
          name: 'Finish purchase',
        })
        this.finishPurchase()
        return
      }
      this.$track({
        type: 'system',
        action: 'confirm_purchase',
        category: 'Purchases',
        screen: 'ConfirmPurchaseDialog',
        name: 'Show over credit limit dialog',
      })
      this[purchasesViewActions.toggleOverCreditLimitDialogStatus]()
      this[purchasesViewActions.toggleConfirmPurchaseDialogStatus]()
    },
  },
}
</script>

<style lang="scss" scoped>
.purchase-details {
  p {
    font-size: 1rem;
    color: var(--v-textPrimary-base);
  }
}

.confirmPurchaseDialog {
  border-radius: 8px;
}
</style>
