<template>
  <v-row>
    <v-col cols="12" class="d-flex align-center">
      <FormattedText
        intl
        value="purchaseView.productTriangulationDialog.promotion.title"
        type="text-h6"
      />
      <span class="mx-3 " v-if="showRemovePromotionBtn">
        <FormattedText :value="promotionTypeLabel" type="text-subtitle-1" />
      </span>
      <CustomButton
        iconBtn
        iconColorDark="error"
        color="error"
        textColor="error"
        icon="mdi-delete"
        class="mr-2"
        @click="resetPromotion"
        tooltipText="loyaltyProgramView.table.tooltips.delete"
        tooltipPosition="right"
        v-if="showRemovePromotionBtn"
      />
    </v-col>
    <span class="mx-3 mb-3 d-flex align-center" v-if="showDiscountInfo">
      <v-icon>mdi-information-outline</v-icon>
      <FormattedText
        intl
        value="purchaseView.productTriangulationDialog.promotion.fields.infoDiscount"
        type="text-subtitle-2"
        class="ml-2"
      />
    </span>
    <v-row class="px-3">
      <v-col cols="3">
        <v-select
          ref="promotionSelect"
          v-model="inputs.promotionTypeId"
          :items="promotionTypes"
          :item-text="item => getTranslatedText(item.text)"
          item-value="value"
          background-color="cardBackgroundSecondary"
          filled
          rounded
        />
      </v-col>
      <component
        :is="promotionFormSelected"
        :inputs="inputs"
        :offset="6"
        :cols="3"
      />
    </v-row>
  </v-row>
</template>

<script>
import { productPurchasePromotions, promotions } from '@/config/promotions'

import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'
import CustomButton from '@/components/shared/CustomButton'
import GiftProductsForm from '@/components/PurchasesView/ProductTriangulationDialog/ProductTriangulationForm/PromotionsForm/Promotions/GiftProductsForm'
import FreeUnitsForm from '@/components/PurchasesView/ProductTriangulationDialog/ProductTriangulationForm/PromotionsForm/Promotions/FreeUnitsForm'
import DiscountForm from '@/components/PurchasesView/ProductTriangulationDialog/ProductTriangulationForm/PromotionsForm/Promotions/DiscountForm'

import productTriangulation from '@/mixins/purchases/productTriangulation'

export default {
  name: 'PromotionsForm',
  components: {
    FormattedText,
    CustomButton,
    GiftProductsForm,
    FreeUnitsForm,
    DiscountForm,
  },
  props: {
    product: {
      type: Object,
      required: true,
    },
    onEnterEvent: {
      type: Function,
    },
    inputs: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      promotionTypes: productPurchasePromotions,
    }
  },
  computed: {
    promotionTypeLabel() {
      const promotionText = productPurchasePromotions.find(
        promo => promo.value === this.inputs.promotionTypeId
      )?.text
      return `(${this.getTranslatedText(promotionText)})`
    },
    showRemovePromotionBtn() {
      return this.inputs.promotionTypeId !== promotions.NONE
    },
    showDiscountInfo() {
      return (
        this.inputs.promotionTypeId ===
        promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT
      )
    },
    promotionFormSelected() {
      switch (this.inputs.promotionTypeId) {
        case promotions.PURCHASE_ITEM_FREE_PRODUCT:
          return GiftProductsForm
        case promotions.PURCHASE_ITEM_FREE_UNITS:
          return FreeUnitsForm
        case promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT:
          return DiscountForm
        default:
          return ''
      }
    },
  },
  methods: {
    getTranslatedText,
    setFormValidators() {
      return {
        inputs: {
          promotionTypeId: this.setRequiredValidator(),
        },
      }
    },
    resetPromotion() {
      this.inputs.promotionTypeId = promotions.NONE
    },
  },
  mixins: [productTriangulation],
  validations() {
    return this.setFormValidators()
  },
}
</script>
