<template>
  <v-row>
    <v-col cols="6">
      <MoneyTextField
        id="amount-to-discount-input"
        ref="amountToDiscount"
        v-model.number="inputs.amountToDiscount"
        :config="{
          fieldName: 'amountToDiscount',
          label: getTranslatedText(
            'purchaseView.returnProductDialog.productToReturnForm.cost'
          ),
          color: 'primary',
          filled: true,
          rounded: true,
          disabled: !isProductSelected,
          class: `price custom-text-field`,
          backgroundColor: 'cardBackgroundSecondary',
          errorMessage: onValidateFields,
        }"
        @input="onTotalInput"
        @focus="inputs.currentFocus = 'amountToDiscount'"
        :options="moneyInputsConfig"
        @blur="$v.inputs.amountToDiscount.$touch()"
      />
    </v-col>
  </v-row>
</template>

<script>
import { has, isNil, isEmpty } from 'ramda'

import { moneyTextFieldCountryConfig } from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'

import { setMoneyValidator } from '@/components/PurchasesView/ReturnProductDialog/ReturnProductForm/tools'

import MoneyTextField from '@/components/shared/MoneyTextField'

export default {
  name: 'DiscountForm',
  components: { MoneyTextField },
  props: {
    inputs: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      moneyInputsConfig: this.getMoneyInputsConfig(),
    }
  },
  computed: {
    isProductSelected() {
      return !isNil(this.inputs.productToReturn)
    },
  },
  methods: {
    getTranslatedText,
    getMoneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
    onValidateFields(input) {
      const errors = []
      if (
        !Object.keys(this.$v.inputs).includes(input) ||
        !this.$v.inputs[input].$dirty
      )
        return errors
      has('required')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].required &&
        errors.push(this.getTranslatedText('salesView.form.errors.empty'))
      has('minValue')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].minValue &&
        errors.push(this.getTranslatedText('salesView.form.errors.minValue'))
      has('maxValue')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].maxValue &&
        errors.push(this.getTranslatedText('salesView.form.errors.maxValue'))
      has('maxDecimals')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].maxDecimals &&
        errors.push(this.getTranslatedText('salesView.form.errors.maxValue'))
      return errors
    },
    onTotalInput() {
      if (
        this.inputs.currentFocus !== 'amountToDiscount' ||
        isEmpty(this.inputs.unitsToReturn) ||
        this.inputs.unitsToReturn === 0
      ) {
        return
      }
      this.inputs.costToReturn =
        this.inputs.productToReturn?.isGramaje === 1
          ? (this.inputs.amountToDiscount * 1000) / this.inputs.unitsToReturn
          : this.inputs.amountToDiscount / this.inputs.unitsToReturn
    },
  },
  validations() {
    return {
      inputs: {
        amountToDiscount: setMoneyValidator(1000000, 2),
      },
    }
  },
}
</script>

<style lang="scss" scoped>
.custom-text-field {
  border-radius: 12px;
}
</style>
