<template>
  <div :key="form.inputs.type" class="d-flex align-center">
    <MoneyTextField
      ref="discount"
      v-model.number="form.inputs.discount"
      :config="configInputTextField"
      :options="optionsInputTextField"
      @input="inputWasUpdated()"
      @blur="form.v.inputs.discount.$touch()"
      @focus="$event => $event.target.select()"
    />
    <v-tooltip bottom>
      <template v-slot:activator="{ on, attrs }">
        <v-btn
          v-bind="attrs"
          v-on="on"
          icon
          color="primary"
          class="mx-2 mb-8"
          @click="changeDiscountType"
        >
          <v-icon>mdi-swap-horizontal</v-icon>
        </v-btn>
      </template>
      <span>{{
        getTranslatedText(`promotion.discount.${getTypeToggled()}Toggle`)
      }}</span>
    </v-tooltip>
    <SingleTextFieldWidget
      class="custom-text-field-large"
      :config="configTextWidget"
    />
  </div>
</template>

<script>
import { getTranslatedText } from '@/tools/data'
import {
  decimal,
  formatNumberFromDb,
  formatNumberFromDbToCurrency,
  formatNumberToCurrency,
  moneyTextFieldCountryConfig,
} from '@/tools/numbersFormat'
import {
  discountTypes,
  getAmountFromPercent,
  getPercentFromAmount,
} from '@/tools/promotions'

import MoneyTextField from '@/components/shared/MoneyTextField'
import SingleTextFieldWidget from '@/components/shared/SingleTextFieldWidget'

export default {
  name: 'DiscountPromotionForm',
  components: { SingleTextFieldWidget, MoneyTextField },
  props: {
    form: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      showErrors: true,
    }
  },
  computed: {
    configInputTextField() {
      return {
        rounded: true,
        filled: true,
        class: 'custom-text-field-large',
        fieldName: 'discount',
        label: this.getTranslatedText(
          `promotion.discount.${this.form.inputs.type}`
        ),
        errorMessage: this.showErrors ? this.inputErrorMessages : () => [],
      }
    },
    optionsInputTextField() {
      if (discountTypes.isDiscountPerAmount(this.form.inputs.type)) {
        return moneyTextFieldCountryConfig() || { precision: 2 }
      }
      return {
        currency: { suffix: '%' },
        precision: { min: 0, max: 2 },
        autoDecimalMode: false,
      }
    },
    configTextWidget() {
      return {
        value: discountTypes.isDiscountPerAmount(this.form.inputs.type)
          ? this.getPercent(this.form.inputs.discount, this.form.cost)
          : this.getAmount(this.form.inputs.discount, this.form.cost),
        readonly: true,
        label: this.getTranslatedText(
          `promotion.discount.${this.getTypeToggled()}`
        ),
      }
    },
  },
  methods: {
    getTranslatedText,
    inputErrorMessages() {
      const errors = []
      this.form.v.inputs.discount.$dirty &&
        !this.form.v.inputs.discount.minValue &&
        errors.push(
          this.getTranslatedText(
            `promotion.discount.${this.form.inputs.type}MinValue`
          )
        )
      this.form.v.inputs.discount.$dirty &&
        !this.form.v.inputs.discount.maxValue &&
        errors.push(
          this.getTranslatedText(
            `promotion.discount.${this.form.inputs.type}MaxValue`,
            `${this.getMaxValue(this.form.inputs.type, this.form.cost)}`
          )
        )
      return errors
    },
    getMaxValue(discountType, cost) {
      return discountTypes.isDiscountPerAmount(discountType)
        ? formatNumberFromDbToCurrency(cost)
        : '100'
    },
    inputWasUpdated() {
      if (this.form.inputs.discount === null) {
        this.resetValue()
      }
    },
    resetValue() {
      this.$refs.discount.setValue(0)
    },
    getPercent(amount, cost) {
      const result = decimal(
        getPercentFromAmount(amount, formatNumberFromDb(cost))
      )
      if (result > 100 || result < 0) {
        return ''
      }
      return `${result}%`
    },
    getAmount(percent, cost) {
      const result = getAmountFromPercent(percent, formatNumberFromDb(cost))
      if (result > formatNumberFromDb(cost) || result < 0) {
        return ''
      }
      return formatNumberToCurrency(result)
    },
    changeDiscountType() {
      this.showErrors = false
      const { discount, type } = this.form.inputs
      this.form.inputs.type = this.getTypeToggled()
      setTimeout(() => {
        this.toggleDiscountByType(discount, type)
        this.showErrors = true
      }, 10)
    },
    getTypeToggled() {
      return discountTypes.isDiscountPerAmount(this.form.inputs.type)
        ? discountTypes.percent
        : discountTypes.amount
    },
    toggleDiscountByType(discount, type) {
      if (discountTypes.isDiscountPerAmount(type)) {
        this.setDiscountPercent(discount)
        return
      }
      this.setDiscountAmount(discount)
    },
    setDiscountPercent(discount) {
      const percent = getPercentFromAmount(
        discount,
        formatNumberFromDb(this.form.cost)
      )
      this.$refs.discount.setValue(percent > 100 || percent < 0 ? 0 : percent)
    },
    setDiscountAmount(discount) {
      const amount = getAmountFromPercent(
        discount,
        formatNumberFromDb(this.form.cost)
      )
      this.$refs.discount.setValue(
        amount > formatNumberFromDb(this.form.cost) || amount < 0 ? 0 : amount
      )
    },
  },
}
</script>
