<template>
  <div>
    <div class="d-flex">
      <PaymentType :config="config.paymentType" />
      <Promotion
        :cost="selectedPurchase.cost"
        :ticket="{
          ...selectedPurchase,
          promotionTicketId: promotions.PURCHASE_TICKET_DISCOUNT,
        }"
        :disabled-button="disabledTicketPromotionBtn"
        @applyPromotion="applyTicketPromotion"
      />
      <ReturnProductBtn class="ml-2" />
    </div>
    <PayButton
      :get-price="getPrice"
      :ticket="selectedPurchase"
      @payButtonWasClicked="onClickPayButton"
    />
    <div class="d-flex mt-2">
      <div
        v-for="field in config.fields"
        :key="field.id"
        :class="field.class ? field.class : ''"
      >
        <v-switch
          v-if="field.type === 'switch'"
          :input-value="field.value"
          @change="field.onChangeValue"
          :label="getTranslatedText(field.label)"
          :color="field.color"
          :inset="field.inset"
          :hide-details="field.hideDetails"
          class="mt-0"
        />
      </div>
    </div>
    <div v-if="notInTestMode" id="ticket-to-print" v-show="false">
      <TicketToPrint
        :products="products"
        :returnProducts="returnProducts"
        :operationType="operationType"
        :details="vendor"
        :operationDate="ticketDate"
        :ticket-promotion="ticketPromotion"
      />
    </div>
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { isEmpty } from 'ramda'

import { testMode } from '@/config/env'
import { idOperations } from '@/config/cashOperationsVariables'
import { returnTypes } from '@/config/returnProductTypes'
import PURCHASE_ORDER_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'

import { promotions } from '@/config/promotions'

import { roundToNearestMultiple } from '@/tools/numbersFormat'
import { getTranslatedText } from '@/tools/data'
import { getPromotionTicketToDB } from '@/tools/promotions'
import { getTotalTicketPrice } from '@/tools/ticket'

import rendererEventsService from '@/services/renderer/rendererEvents'

import purchasesViewActions from '@/store/purchasesView/actions.types'

import Promotion from '@/components/shared/Ticket/Promotion'
import setConfig from '@/components/PurchasesView/Ticket/TicketFooter/config'
import TicketToPrint from '@/components/TicketToPrint'
import PaymentType from '@/components/shared/PaymentType'
import ReturnProductBtn from '@/components/PurchasesView/Ticket/ReturnProductBtn'
import PayButton from '@/components/shared/PayButton'

export default {
  name: 'TicketFooter',
  components: {
    PayButton,
    Promotion,
    PaymentType,
    TicketToPrint,
    ReturnProductBtn,
  },
  data() {
    return {
      ticketDate: '',
    }
  },
  computed: {
    promotions() {
      return promotions
    },
    ...mapState('purchasesView', {
      selectedPurchase: state => state.selectedPurchase,
      purchaseStatus: state => state.selectedPurchase.status,
    }),
    ...mapState('vendorsView', ['selectedVendor']),
    ...mapState('app', ['printTicketDefault']),
    disabledTicketPromotionBtn() {
      return (
        !this.selectedPurchase.items.length ||
        (!!this.selectedPurchase.items.length &&
          this.selectedPurchase.cost <= 0)
      )
    },
    products() {
      return this.selectedPurchase.items.map(item => ({
        id: item.id,
        name: item.name,
        quantity: item.quantity,
        iva: item.iva,
        price: item.cost,
        isGramaje: item.isGramaje,
        promotionTypeId: item.promotionTypeId,
        promotionExtra: item.promotionExtra,
        costWithoutTaxAndPromotion: item.costWithoutTaxAndPromotion,
        discount: item.discountPercent,
        description: item.description,
      }))
    },
    returnProducts() {
      return this.selectedPurchase.returnItems.map(returnItem => ({
        id: returnItem.productReturnId,
        name: returnItem.productReturnName,
        quantity: returnItem.productReturnQuantity,
        price: returnItem.productReturnCost,
        amountToDiscount: returnItem.amountToDiscount,
        isGramaje: returnItem.productReturnIsGramaje,
        returnType: returnItem.returnType,
        idChange: returnItem.productChangeId,
        nameChange: returnItem.productChangeName,
        quantityChange: returnItem.productChangeQuantity,
        priceChange: returnItem.productChangeCost,
        isGramajeChange: returnItem.productChangeIsGramaje,
      }))
    },
    operationType() {
      return this.selectedPurchase.payOption === 'cash'
        ? idOperations.ID_OPERATION_CASH_PURCHASE
        : idOperations.ID_OPERATION_CREDIT_PURCHASE
    },
    vendor() {
      return { vendor: this.selectedVendor }
    },
    config() {
      return setConfig(
        {
          data: this.selectedPurchase,
        },
        {
          changePrintStatus: () => {
            this.$track({
              type: 'interaction',
              action: 'change',
              category: 'Purchases',
              screen: 'TicketFooter',
              name: 'Ticket printed satus',
            })
            this.updatePrintTicketStatus()
          },
          changePayOption: option =>
            this[purchasesViewActions.updatePayOptionStatus](option),
        }
      )
    },
    notInTestMode() {
      return !testMode
    },
    ticketPromotion() {
      if (this.selectedPurchase.promotion <= 0) {
        return null
      }
      return {
        promotion: this.selectedPurchase.promotion,
        promotionType: this.selectedPurchase.promotion_type,
      }
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('purchasesView', [
      purchasesViewActions.toggleConfirmPurchaseDialogStatus,
      purchasesViewActions.updatePrintTicketStatus,
      purchasesViewActions.updatePayOptionStatus,
      purchasesViewActions.toggleOverCreditLimitDialogStatus,
      purchasesViewActions.addPromotionTicket,
    ]),
    async onClickPayButton() {
      if (
        isEmpty(this.selectedPurchase.items) ||
        this.hasAllProductsWithFreePromotion()
      ) {
        return
      }
      this.$track({
        type: 'system',
        action: 'pay_purchase',
        category: 'Purchases',
        screen: 'TicketFooter',
        name: 'Show confirm finish purchase dialog',
      })
      this[purchasesViewActions.toggleConfirmPurchaseDialogStatus]()
    },
    hasAllProductsWithFreePromotion() {
      return (
        this.selectedPurchase.cost <= 0 &&
        this.selectedPurchase.items.some(
          item => item.promotionTypeId !== promotions.PURCHASE_ITEM_FREE_PRODUCT
        )
      )
    },
    getPrice(products, returnProducts) {
      let toPay = getTotalTicketPrice(products, 'cost')
      returnProducts.forEach(returnProduct => {
        const { amountToDiscount, returnType } = returnProduct
        const subtotal =
          returnType === returnTypes.DISCOUNT ? amountToDiscount : 0
        toPay -= subtotal
      })
      return roundToNearestMultiple(parseInt(toPay.toFixed(0)))
    },
    shortcutListener() {
      this.onClickPayButton()
    },
    async applyTicketPromotion(promotion) {
      await this[purchasesViewActions.addPromotionTicket]({
        promotion: promotion.discount,
        type: promotion.type,
      })
      rendererEventsService.send(PURCHASE_ORDER_DB_API_EVENTS.channel, {
        event: PURCHASE_ORDER_DB_API_EVENTS.events.update.name,
        data: {
          purchaseOrder: {
            ...this.selectedPurchase,
            promotion: getPromotionTicketToDB(this.selectedPurchase),
          },
        },
      })
    },
    setPurchaseTicketDate(date) {
      this.ticketDate = date
    },
  },
  created() {
    this.$root.$on(`click-pay-purchase`, this.shortcutListener)
    this.$root.$on(`setPurchaseTicketDate`, this.setPurchaseTicketDate)
    this.selectedPurchase.print = this.printTicketDefault
    this.selectedPurchase.payOption = 'cash'
  },
  beforeDestroy() {
    this.$root.$off(`click-pay-purchase`, this.shortcutListener)
    this.$root.$off(`setPurchaseTicketDate`, this.setPurchaseTicketDate)
  },
}
</script>
