<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { values } from 'ramda'

import appActions from '@/store/app/actions.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'

import ToolBar from '@/components/shared/ToolBar'

import config from '@/components/PurchasesView/ProductsFilterToolbar/PurchaseTools/config'

export default {
  name: 'PurchaseTools',
  components: { ToolBar },
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
    }),
    ...mapState('products', ['data', 'view']),
    ...mapState('purchasesView', {
      filters: state => state.filters,
      listType: state => state.component,
      selectedPurchase: state => state.selectedPurchase,
    }),
    componentConfig() {
      return config(
        {
          data: this.data,
          filters: this.filters,
          listType: this.listType,
          isScannerActive: this.isScannerActive,
          purchase: this.selectedPurchase,
        },
        {
          setSearchTerm: this[purchasesViewActions.setSearchTermFilter],
          setGroup: this[purchasesViewActions.setGroupFilter],
          setSelectedSuperCategories: this[
            purchasesViewActions.setSuperCategoriesFilter
          ],
          setViewComponent: this[purchasesViewActions.setViewType],
          updateScannerStatus: this[appActions.updateScannerStatus],
          onReset: this.onReset,
          resetScannerStatus: this.resetScannerStatus,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('purchasesView', values(purchasesViewActions)),
    onReset() {
      this.$root.$emit('reset')
    },
    resetScannerStatus() {
      const searchInput = document.getElementById('purchases-input-search')
      this.isScannerActive ? searchInput.focus() : searchInput.blur()
      this[appActions.updateScannerStatus]()
    },
  },
}
</script>
