const setConfig = (state, methods) => ({
  state,
  methods,
  floatingButtons: [
    {
      id: 'delete',
      show: state.hover,
      class: 'delete-from-cart-button',
      absolute: true,
      icon: 'mdi-delete',
      iconColor: 'primary',
      fab: true,
      xSmall: true,
      onClick: () => methods.deleteFromCart(),
    },
    {
      id: 'edit',
      show: state.hover,
      class: 'edit-from-cart-button',
      absolute: true,
      icon: 'mdi-square-edit-outline',
      iconColor: 'primary',
      fab: true,
      xSmall: true,
      onClick: () => methods.editReturnProduct(),
    },
  ],
})

export default setConfig
