import { storeInventory } from '@/config/storeMapper'
import productsVariables from '@/config/products'

import { mapStoreObject } from '@/tools/data'

import {
  setValue,
  getPackagesStockValue,
  getPiecesStockValue,
  setOpenProductStockValue,
} from '@/components/ProductDetail/DetailsTab/tools'

const setConfig = (state, methods) => ({
  state,
  methods,
  singleWidgets: {
    firstSection: [
      {
        id: 'packagesStock',
        type: 'SingleDataWidget',
        value: getPackagesStockValue(
          state.product.quantity,
          state.product.factor
        ),
        label: 'productsView.details.packages',
        labelIcon: 'mdi-package-variant-closed',
        iconColor: state.product.quantity <= 0 ? 'error' : 'accent',
        show: state.product.factor > 1 && state.hasInventoryLimitation,
        extraClasses: 'pr-12',
        reverse: false,
      },
      {
        id: 'piecesStock',
        type: 'SingleDataWidget',
        value: getPiecesStockValue(
          state.product.quantity,
          state.product.factor
        ),
        label:
          state.product.isGramaje === 1
            ? 'productsView.details.grams'
            : 'productsView.details.pieces',
        labelIcon: 'mdi-food-apple-outline',
        show: state.hasInventoryLimitation,
        extraClasses: state.product.factor > 1 ? 'pl-12' : '',
        reverse: false,
      },
      {
        id: 'packagesStockEdit',
        type: 'SingleEditDataWidget',
        value: state.product.packagesQuantity,
        valueTextColor: 'testPrimary',
        valueLimit: productsVariables.STOCK_MAX_VALUE,
        label: 'productsView.details.packages',
        labelIcon: 'mdi-pencil',
        iconColor: state.product.quantity <= 0 ? 'error' : 'accent',
        reverse: false,
        show: state.product.factor > 1 && !state.hasInventoryLimitation,
        editing: false,
        extraClasses: 'pr-12',
        onInputChange: newValue => {
          setOpenProductStockValue(methods, 'packagesQuantity', newValue)
        },
        onInputFinishEdit: () => {
          methods.track({
            type: 'interaction',
            action: 'click',
            category: state.routeName,
            screen: 'ProductDetails',
            name: `Save package stock`,
          })
          methods.updatePackageStock()
        },
        textFormatter: value => value.toString(),
      },
      {
        id: 'piecesStockEdit',
        type: 'SingleEditDataWidget',
        value:
          state.product.factor > 1
            ? state.product.piecesQuantity
            : state.product.quantity,
        valueTextColor: 'textPrimary',
        valueLimit: productsVariables.STOCK_MAX_VALUE,
        label:
          state.product.isGramaje === 1
            ? 'productsView.details.grams'
            : 'productsView.details.pieces',
        labelIcon: 'mdi-pencil',
        iconColor: state.product.quantity <= 0 ? 'error' : 'accent',
        reverse: false,
        show: !state.hasInventoryLimitation,
        editing: false,
        extraClasses: state.product.factor > 1 ? 'pl-12' : '',
        onInputChange: newValue =>
          setOpenProductStockValue(
            methods,
            state.product.factor > 1 ? 'piecesQuantity' : 'quantity',
            newValue
          ),
        onInputFinishEdit: () => {
          methods.track({
            type: 'interaction',
            action: 'click',
            category: state.routeName,
            screen: 'ProductDetails',
            name: `Save pieces stock`,
          })
          methods.updatePiecesStock()
        },
        textFormatter: value => value?.toString() || '0',
      },
    ],
    secondSection: [
      {
        id: 'levelWarning',
        type: 'SingleEditDataWidget',
        value: state.product.levelWarning,
        valueTextColor: 'textPrimary',
        valueLimit: productsVariables.STOCK_MAX_VALUE,
        label: 'productsView.details.levelWarning',
        labelIcon: 'mdi-pencil',
        reverse: true,
        onInputChange: newValue => setValue(methods, 'levelWarning', newValue),
        onInputFinishEdit: () => {
          methods.track({
            type: 'interaction',
            action: 'click',
            category: state.routeName,
            screen: 'ProductDetails',
            name: `Save alert for restocking`,
          })
          methods.updateDatabase({
            id: state.product.id,
            data: mapStoreObject(
              { levelWarning: state.product.levelWarning },
              storeInventory,
              true
            ),
          })
        },
        textFormatter: value => value.toString(),
      },
    ],
  },
})

export default setConfig
