<template>
  <div>
    <v-tooltip top>
      <template v-slot:activator="{ on, attrs }">
        <v-btn
          v-bind="attrs"
          v-on="on"
          color="primary"
          class="promotion-btn"
          elevation="0"
          @click="openReturnProductDialog"
          v-track:click="{
            category: 'Purchases',
            screen: 'TicketFooter',
            name: 'Open return product dialog',
          }"
        >
          <v-icon large>$vuetify.icons.values.returnProduct</v-icon>
        </v-btn>
      </template>
      <span>{{
        getTranslatedText('purchaseView.payButton.returnProduct')
      }}</span>
    </v-tooltip>
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { getTranslatedText } from '@/tools/data'

import purchasesViewActions from '@/store/purchasesView/actions.types'

export default {
  name: 'ReturnProductBtn',
  computed: {
    ...mapState('purchasesView', {
      returnProductDialog: 'returnProductDialog',
    }),
  },
  methods: {
    getTranslatedText,
    ...mapActions('purchasesView', [
      purchasesViewActions.setReturnProductDialogStatus,
    ]),
    openReturnProductDialog() {
      this[purchasesViewActions.setReturnProductDialogStatus]({ isOpen: true })
    },
  },
}
</script>

<style lang="scss" scoped>
.promotion-btn {
  border-radius: 10px;
  height: 45px !important;
}
</style>
