import { isNil } from 'ramda'
import { required, integer } from 'vuelidate/lib/validators'

import { getDecimalsCount } from '@/tools/numbersFormat'
import { getDiscountRule } from '@/tools/promotions'
import { validate } from '@/tools/validations'
import { getTotal } from '@/tools/purchases/tools'

export default {
  methods: {
    getDiscountRule,
    getTotal,
    setMoneyValidator(valueLimit, decimalsLimit, zeroIsValid = false) {
      return {
        required,
        minValue: value => (zeroIsValid ? value >= 0 : value > 0),
        maxValue: value => value < valueLimit,
        maxDecimals: value => getDecimalsCount(value) <= decimalsLimit,
      }
    },
    setDefaultValidators: function(
      limit,
      negativeIsValid = false,
      isOptional = false
    ) {
      return {
        required: !isOptional ? required : {},
        minValue: value => (negativeIsValid ? value > -limit : value > 0),
        maxValue: value => value < limit,
        integer,
      }
    },
    initTax() {
      this.inputs.tax =
        isNil(this.product.iva) || this.product.iva === -1
          ? 0
          : this.product.iva
    },
    initTotal() {
      this.inputs.total = this.getTotal(
        this.product.isGramaje,
        this.inputs.quantity,
        this.inputs.cost,
        this.inputs.tax
      )
    },
    setRequiredValidator: function() {
      return {
        required,
      }
    },
    onValidateFields(input) {
      return validate(this.$v.inputs, input, { fn: this.getTranslatedText })
    },
    applyTax() {
      return this.inputs.tax / 100 + 1
    },
  },
}
