<template>
  <div>
    <div v-if="product !== undefined">
      <ProductForm
        :productType="productType"
        :product="product"
        :inputs="inputs"
        :onEnterEvent="onEnterEvent"
      />
      <PromotionsForm
        v-if="product.isGeneric !== 1"
        :product="product"
        :inputs="inputs"
        :onEnterEvent="onEnterEvent"
      />
      <OtherFieldsForm
        v-if="product.isGeneric !== 1"
        :productType="productType"
        :product="product"
        :inputs="inputs"
        :onEnterEvent="onEnterEvent"
      />
    </div>
  </div>
</template>

<script>
import { mapState } from 'vuex'
import { isNil } from 'ramda'

import productsVariables from '@/config/products'
import { promotions } from '@/config/promotions'

import { formatNumberFromDb, formatNumberToDb } from '@/tools/numbersFormat'
import { discountTypes } from '@/tools/promotions'
import { getQuantityWithoutFreeUnits } from '@/tools/purchases/tools'

import ProductForm from '@/components/PurchasesView/ProductTriangulationDialog/ProductTriangulationForm/ProductForm'
import OtherFieldsForm from '@/components/PurchasesView/ProductTriangulationDialog/ProductTriangulationForm/OtherFieldsForm'
import PromotionsForm from '@/components/PurchasesView/ProductTriangulationDialog/ProductTriangulationForm/PromotionsForm'

import productTriangulation from '@/mixins/purchases/productTriangulation'

export default {
  name: 'ProductTriangulationForm',
  components: { ProductForm, OtherFieldsForm, PromotionsForm },
  props: {
    product: {
      type: Object,
      required: true,
    },
    onEnterEvent: {
      type: Function,
    },
    fromTicket: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      inputs: {
        quantity: 0,
        cost: 0,
        tax: 1,
        total: 0,
        price: 0,
        pricePack: 0,
        existences: 0,
        existencesPack: 0,
        promotionTypeId: promotions.NONE,
        totalWithDiscount: 0,
        freeUnits: 0,
        discount: 0,
        type: discountTypes.amount,
      },
      openProductType: null,
      productType: '',
    }
  },
  computed: {
    ...mapState('purchasesView', ['selectedProduct']),
  },
  methods: {
    setFormValidators() {
      const validations = {
        inputs: {
          quantity: this.setDefaultValidators(100000),
          cost: this.setMoneyValidator(1000000, 4),
          tax: this.setRequiredValidator(),
          total: this.setMoneyValidator(1000000, 4),
        },
      }
      if (this.product.isGeneric) return validations
      validations.inputs = {
        ...validations.inputs,
        price: this.setMoneyValidator(1000000, 4),
        existences: this.setDefaultValidators(
          productsVariables.STOCK_MAX_VALUE,
          true
        ),
        promotionTypeId: this.setRequiredValidator(),
        totalWithDiscount: this.setMoneyValidator(1000000, 4, true),
      }
      if (this.inputs.promotionTypeId === promotions.PURCHASE_ITEM_FREE_UNITS) {
        validations.inputs = {
          ...validations.inputs,
          freeUnits: this.setDefaultValidators(100000, false, true),
        }
      }
      if (
        this.inputs.promotionTypeId ===
        promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT
      ) {
        validations.inputs = {
          ...validations.inputs,
          discount: this.getDiscountRule(
            this.inputs.type,
            formatNumberToDb(
              this.getTotal(
                this.selectedProduct.product.isGramaje,
                this.inputs.quantity,
                this.inputs.cost,
                this.inputs.tax
              )
            )
          ),
        }
      }
      if (this.product.factor > 1) {
        validations.inputs = {
          ...validations.inputs,
          pricePack: this.setMoneyValidator(1000000, 4),
          existencesPack: this.setDefaultValidators(
            productsVariables.STOCK_MAX_VALUE,
            true
          ),
        }
      }
      return validations
    },
    initQuantity() {
      if (isNil(this.product.uniqueId)) {
        this.inputs.quantity = this.product.isGramaje === 1 ? 100 : 1
        return
      }
      this.inputs.quantity =
        this.product.quantity > 0
          ? getQuantityWithoutFreeUnits(this.product)
          : 1
    },
    initCost() {
      this.inputs.cost = this.fromTicket
        ? formatNumberFromDb(this.product.costWithoutTaxAndPromotion)
        : formatNumberFromDb(this.product.cost)
    },
    initExistences() {
      const factor = this.product.factor
      const stockRaw = this.fromTicket
        ? this.product.stock
        : this.product.isGramaje || this.product.isGeneric
        ? this.product.quantity
        : this.product.stock
      if (factor > 1) {
        this.inputs.existencesPack =
          factor === 0
            ? Math.floor(stockRaw) | 0
            : Math.floor(stockRaw / factor) | 0
        this.inputs.existences = stockRaw % factor
        return
      }
      this.inputs.existences = stockRaw
    },
    initPrice() {
      let price
      if (this.product.factor > 1) {
        this.inputs.pricePack = formatNumberFromDb(
          this.product.openProductDbPrices.package
        )
        price = this.product.openProductDbPrices.piece
      } else if (this.product.isGramaje === 1) {
        price = this.product.price || this.product.unitPrice
      } else {
        price = this.product.isGeneric === 1 ? 0 : this.product.unitPrice
      }
      this.inputs.price = formatNumberFromDb(price)
    },
    getFormValues() {
      return {
        inputs: this.inputs,
        product: this.product,
        isValid: !this.$v.$invalid,
        costChanged: this.costChanged,
        productType: this.productType,
        openProductType: this.openProductType,
      }
    },
    setProductType(product) {
      const isOpenProduct = product.factor > 0 || product.isOpenProduct === 1
      const isPieceProduct = isOpenProduct === false && product.isGramaje === 0
      const isByWeightProduct =
        isOpenProduct === false && product.isGramaje === 1
      if (isPieceProduct) return 'isPieceProduct'
      if (isByWeightProduct) return 'isByWeightProduct'
      if (isOpenProduct) return 'isOpenProductPackage'
    },
  },
  watch: {
    $v: {
      handler() {
        this.$root.$emit('by-weight-selected-product', this.getFormValues())
      },
      deep: true,
    },
    'inputs.promotionTypeId': function(newVal) {
      if (this.selectedProduct.product.promotionTypeId === newVal) return
      this.inputs.freeUnits = 0
      this.inputs.discount = 0
      this.inputs.totalWithDiscount = 0
      this.inputs.type = discountTypes.amount
    },
  },
  mixins: [productTriangulation],
  validations() {
    return this.setFormValidators()
  },
  beforeMount() {
    this.initQuantity()
    this.initCost()
    this.initTax()
    this.initExistences()
    this.initPrice()
  },
  mounted() {
    this.inputs.promotionTypeId = this.product.promotionTypeId
    this.inputs.freeUnits = this.product.promotionExtra
    this.initTotal()
    if (
      this.product.promotionTypeId ===
      promotions.PURCHASE_ITEM_SUBTOTAL_DISCOUNT
    ) {
      if (this.product.discountPercent > 0) {
        this.inputs.type = discountTypes.percent
        this.inputs.discount = this.product.discountPercent
      } else {
        this.inputs.type = discountTypes.amount
        this.inputs.discount = formatNumberFromDb(this.product.discountAmount)
      }
    }
    this.productType = this.setProductType(this.product)
    this.openProductType = !isNil(this.product.openProductType)
      ? this.product.openProductType.toString()
      : this.product.factorSalesBy
  },
}
</script>
