import { promotions } from '@/config/promotions'

import {
  formatNumberFromDb,
  formatNumberFromDbToCurrency,
  formatNumberToDb,
} from '@/tools/numbersFormat'
import { discountTypes, getDiscountRule } from '@/tools/promotions'

import notificationsService from '@/services/renderer/notifications'

const DISCOUNT_PROMOTIONS_IDS = [
  promotions.SALE_TICKET_DISCOUNT,
  promotions.PURCHASE_TICKET_DISCOUNT,
]

const TICKET_AT_COST_IDS = [promotions.SALE_TICKET_AT_COST]

const setInputsValueFromTicket = function() {
  this.inputs.type = this.ticket.promotion_type
  this.inputs.discount = getPromotion(this.ticket)
  this.inputs.promotionTicketId = this.ticket.promotionTicketId
}

const getPromotion = ticket => {
  return discountTypes.isDiscountPerAmount(ticket.promotion_type)
    ? formatNumberFromDb(ticket.promotion)
    : ticket.promotion
}

const getPromotionTicketToSave = function() {
  const discount = getDiscount(this.inputs)
  return {
    discount,
    type: discount === 0 ? this.defaultType : this.inputs.type,
    promotionTicketId: this.inputs.promotionTicketId,
  }
}

const getDiscount = inputs => {
  if (!DISCOUNT_PROMOTIONS_IDS.includes(inputs.promotionTicketId)) {
    return 0
  }
  return discountTypes.isDiscountPerPercent(inputs.type)
    ? inputs.discount
    : formatNumberToDb(inputs.discount)
}

const isPromotionPerAmountGreaterThanCost = function() {
  return (
    this.ticket.promotion !== 0 &&
    discountTypes.isDiscountPerAmount(this.ticket.promotion_type) &&
    this.cost < this.ticket.promotion
  )
}

const showHighDiscountAlertWarning = function() {
  notificationsService.showWarning(
    'promotion.ticket.discount.exceededAmountAlert',
    this.$vuetify.lang,
    { timeout: 3500 },
    [formatNumberFromDbToCurrency(this.ticket.promotion)]
  )
}

const getDiscountValidation = function() {
  return {
    ...getDiscountRule(this.inputs.type, this.cost),
    minValue: value =>
      this.promotionsOptions.length === 0 ||
      !DISCOUNT_PROMOTIONS_IDS.includes(this.inputs.promotionTicketId)
        ? value >= 0
        : value > 0,
  }
}

export default {
  DISCOUNT_PROMOTIONS_IDS,
  TICKET_AT_COST_IDS,
  setInputsValueFromTicket,
  getPromotionTicketToSave,
  isPromotionPerAmountGreaterThanCost,
  showHighDiscountAlertWarning,
  getDiscountValidation,
}
