<template>
  <v-card
    class="pa-0 mt-6 rounded-widget"
    color="cardBackgroundSecondary"
    flat
    id="main-details"
  >
    <div class="py-1 pl-5 pr-1 d-flex widget-title">
      <v-icon color="textOverBackground">{{
        selectedProduct.isGramaje === 1
          ? 'mdi-weight-kilogram'
          : 'mdi-food-apple-outline'
      }}</v-icon>
      <FormattedText
        intl
        type="text-body-1"
        color="textOverBackground"
        :value="
          selectedProduct.isGramaje === 1
            ? 'productsView.details.kiloDetails'
            : selectedProduct.factor > 1
            ? 'productsView.details.pieceDetails'
            : 'productsView.details.unitDetails'
        "
        class="pl-2 pt-1"
        className="font-weight-bold"
      />
      <v-spacer />
      <v-btn
        v-if="widgetStatus !== null"
        @click="onClickDropDown"
        elevation="0"
        color="productSecondary"
        small
        class="pt-1"
      >
        <v-icon>
          {{ widgetStatus ? 'mdi-chevron-down' : 'mdi-chevron-right' }}
        </v-icon>
      </v-btn>
    </div>
    <v-container
      class="pa-0"
      v-if="widgetStatus === null || widgetStatus === true"
    >
      <v-row>
        <v-col cols="4" class="px-8">
          <div
            v-for="widget in widgetConfig.singleWidgets.firstSection"
            :key="widget.id"
          >
            <component :is="widget.type" :config="widget" />
          </div>
        </v-col>
        <v-col cols="8" class="px-8">
          <div class="d-flex justify-space-between">
            <div
              v-for="widget in widgetConfig.singleWidgets.secondSection"
              :key="widget.id"
            >
              <component :is="widget.type" :config="widget" />
            </div>
          </div>
        </v-col>
      </v-row>
    </v-container>
  </v-card>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'

import { getActionsTypes, getViewStore } from '@/tools/view'
import { deepCopy } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'

import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'
import setConfig from '@/components/ProductDetail/DetailsTab/MainDetails/config'
import FormattedText from '@/components/shared/FormattedText'
import SingleDataWidget from '@/components/shared/SingleDataWidget'
import SingleEditDataWidget from '@/components/shared/SingleEditDataWidget'

export default {
  name: 'MainDetails',
  components: {
    FormattedText,
    SingleDataWidget,
    SingleEditDataWidget,
  },
  props: {
    opened: {
      type: Boolean,
    },
    onClickDropDown: {
      type: Function,
    },
  },
  data() {
    return {
      oldPrice: 0,
    }
  },
  computed: {
    ...mapState('account', ['data']),
    ...mapState('usersView', ['selectedUser']),
    ...getSelectedProductByRoute(),
    widgetStatus() {
      return this.opened
    },
    widgetConfig: function() {
      return setConfig(
        {
          product: this.selectedProduct,
          limits: this.data.country.limits,
          routeName: this.$route.name,
        },
        {
          setSelectedProductField: this[
            productsViewActions.updateSelectedProductField
          ],
          updateDatabase: this.editProduct,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions({
      updateSelectedProductField(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).updateSelectedProductField
          }`,
          payload
        )
      },
    }),
    editProduct(productToUpdated) {
      if (this.priceWasChanged(productToUpdated.data)) {
        productToUpdated.data.is_price_changed = 1
      }
      if (this.priceIsLessThanOne(productToUpdated.data)) {
        productToUpdated.data.is_price_changed = 0
      }
      this.oldPrice = deepCopy(this.selectedProduct.price)
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
        data: {
          productToUpdated,
          username: this.selectedUser.name,
        },
      })
    },
    priceWasChanged(data) {
      if (this.selectedProduct.isPriceChanged === 1) return false
      return !!data.prod_price && data.prod_price !== this.oldPrice
    },
    priceIsLessThanOne(data) {
      return 'prod_price' in data && data.prod_price <= 0
    },
  },
  mounted() {
    this.oldPrice = deepCopy(this.selectedProduct.price)
  },
}
</script>

<style lang="scss" scoped>
.rounded-widget {
  border-radius: 8px;
  .widget-title {
    background-color: var(--v-cardSecondary-base);
  }
}
</style>
