import uniqid from 'uniqid'

import { returnTypes } from '@/config/returnProductTypes'
import { purchaseReturnItems as purchaseReturnItemsMapper } from '@/config/storeMapper'

import { formatNumberToDb } from '@/tools/numbersFormat'
import { mapStoreObject } from '@/tools/data'

const buildTicketReturnItem = (payload, purchaseOrderId) => {
  const { inputs } = payload
  const {
    productToReturn,
    unitsToReturn,
    costToReturn,
    returnType,
    productToChange,
    unitsToChange,
    costToChange,
    amountToDiscount,
  } = inputs
  const isChangeProduct = returnType === returnTypes.CHANGE_PRODUCT
  return {
    purchaseOrderId,
    uniqueId: uniqid(),
    returnType,
    productReturnId: productToReturn.id,
    productReturnName: productToReturn.name,
    productReturnQuantity: unitsToReturn,
    productReturnCost: formatNumberToDb(costToReturn),
    productReturnIsGramaje: productToReturn.isGramaje,
    amountToDiscount: formatNumberToDb(amountToDiscount),
    productChangeId: isChangeProduct ? productToChange.id : null,
    productChangeName: isChangeProduct ? productToChange.name : null,
    productChangeQuantity: isChangeProduct ? unitsToChange : null,
    productChangeCost: isChangeProduct ? formatNumberToDb(costToChange) : null,
    productChangeIsGramaje: isChangeProduct ? productToChange.isGramaje : null,
  }
}

const buildTicketReturnItemFromBD = item => {
  const returnItem = mapStoreObject(item, purchaseReturnItemsMapper)
  return {
    ...returnItem,
    uniqueId: uniqid(),
  }
}

const buildTicketReturnProductUpdated = (payload, purchaseOrderId) => {
  return buildTicketReturnItem(payload, purchaseOrderId)
}

export default {
  buildTicketReturnItem,
  buildTicketReturnItemFromBD,
  buildTicketReturnProductUpdated,
}
