<template>
  <div class="payment-type mb-2">
    <v-menu
      v-for="type in config.options"
      :key="type.id"
      :disabled="!type.options"
      top
      offset-y
      content-class="elevation-3"
    >
      <template v-slot:activator="{ on: menu, attrs }">
        <v-tooltip top>
          <template v-slot:activator="{ on: tooltip }">
            <v-btn
              v-bind="attrs"
              v-on="{ ...tooltip, ...menu }"
              :id="`paymentType_${type.id}`"
              :color="
                isButtonActive(type.id, config.value)
                  ? 'primary'
                  : 'grey lighten-4'
              "
              depressed
              tile
              :class="{
                'payment-type__option--active': isButtonActive(
                  type.id,
                  config.value
                ),
              }"
              :disabled="
                config.disabled(type.id) ||
                  ('disabled' in type && type.disabled)
              "
              class="payment-type__option"
              @click="payOptionWasClicked(type.id)"
              v-track:click="{
                category: $route.name,
                screen: 'PaymentType',
                name: `Change payment type to ${type.id}`,
              }"
            >
              <v-icon
                large
                :color="
                  isButtonActive(type.id, config.value)
                    ? 'white'
                    : 'grey lighten-1'
                "
              >
                {{ icons[type.id] }}
              </v-icon>
            </v-btn>
          </template>
          <span>{{ getTranslatedText(type.label) }}</span>
        </v-tooltip>
      </template>
      <v-list dense min-width="150">
        <v-list-item-group :value="config.subValue" mandatory color="primary">
          <v-list-item
            v-for="item in type.options"
            :key="item.id"
            :value="item.value"
            @click="config.onChangeValue(item.type, item.value)"
          >
            <v-list-item-title>{{ item.label }}</v-list-item-title>
          </v-list-item>
        </v-list-item-group>
      </v-list>
    </v-menu>
  </div>
</template>

<script>
import paymentMethods from '@/config/paymentMethods'

import { getTranslatedText } from '@/tools/data'

export default {
  name: 'PaymentType',
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  computed: {
    icons() {
      return {
        cash: 'mdi-hand-coin',
        credit: 'mdi-cash-clock',
        card: 'mdi-credit-card-outline',
        qr: 'mdi-qrcode-scan',
        owner: 'mdi-account-reactivate',
        others: 'mdi-dots-horizontal',
      }
    },
  },
  methods: {
    getTranslatedText,
    payOptionWasClicked(value) {
      const subOptions = this.config.options.find(option => option.id === value)
        .options
      const subOptionSelected = this.getSubOptionSelected(subOptions)
      this.config.onChangeValue(
        subOptions ? subOptions[0].type : value,
        subOptionSelected
          ? subOptionSelected.id
          : subOptions
          ? subOptions[0].id
          : value
      )
    },
    getSubOptionSelected(subOptions) {
      if (!subOptions) return null
      return subOptions.find(option => option.id === this.config.subValue)
    },
    isButtonActive(id, value) {
      if (id === paymentMethods.others && value !== id) {
        const otherOptions = this.config.options.find(
          option => option.id === id
        )
        if (otherOptions) {
          return otherOptions.options.some(other => other.type === value)
        }
      }
      return id === value
    },
  },
}
</script>

<style scoped lang="scss">
.payment-type {
  width: 100%;
  display: flex;
  justify-content: space-between;
  border-radius: 10px;
  &__option {
    width: 100%;
    flex: auto;
    height: 45px !important;
    &.v-btn.v-size--default {
      padding: 0 10px;
    }
    border: 1px solid rgba(0, 0, 0, 0.12) !important;
    &.grey.lighten-4 {
      border: 1px solid rgba(0, 0, 0, 0.12) !important;
    }
    &:first-child {
      border-radius: 10px 0 0 10px !important;
    }
    &:last-child {
      border-radius: 0 10px 10px 0 !important;
    }
    &--active {
      &.v-btn--disabled {
        &::before {
          opacity: 0.18;
        }
      }
    }
  }
}
</style>
