<template>
  <v-row>
    <v-col cols="12">
      <FormattedText
        intl
        value="purchaseView.returnProductDialog.productToReturnForm.title"
        type="text-h6"
      />
    </v-col>
    <v-row class="px-3">
      <v-col cols="6">
        <ProductAutoComplete
          id="products-autocomplete-return"
          ref="productToReturn"
          v-model="inputs.productToReturn"
          :items="getOnlyStockedProducts"
          :customFilter="customFilter"
          :label="
            getTranslatedText(
              'purchaseView.returnProductDialog.productToReturnForm.productToReturn'
            )
          "
          className="custom-text-field"
          clearable
          returnObject
          :errorMessages="onValidateFields('productToReturn')"
          @blur="$v.inputs.productToReturn.$touch()"
        />
      </v-col>
      <v-col cols="3">
        <v-text-field
          id="quantity-return-input"
          ref="unitsToReturn"
          v-model.number="inputs.unitsToReturn"
          type="number"
          class="custom-text-field"
          filled
          :disabled="!isProductSelected"
          rounded
          background-color="cardBackgroundSecondary"
          :label="
            getTranslatedText(
              'purchaseView.returnProductDialog.productToReturnForm.quantity'
            )
          "
          :error-messages="onValidateFields('unitsToReturn')"
          @input="onUnitsToReturn"
          @focus="inputs.currentFocus = 'unitsToReturn'"
          @blur="$v.inputs.unitsToReturn.$touch()"
        />
      </v-col>
      <v-col cols="3">
        <MoneyTextField
          id="cost-return-input"
          ref="costToReturn"
          v-model.number="inputs.costToReturn"
          :config="{
            fieldName: 'costToReturn',
            label: getCostLabel(),
            color: 'primary',
            filled: true,
            rounded: true,
            disabled: !isProductSelected,
            class: 'custom-text-field price',
            backgroundColor: 'cardBackgroundSecondary',
            errorMessage: onValidateFields,
          }"
          :options="moneyInputsConfig"
          @input="onCostToReturn"
          @focus="inputs.currentFocus = 'costToReturn'"
          @blur="$v.inputs.costToReturn.$touch()"
        />
      </v-col>
    </v-row>
  </v-row>
</template>

<script>
import { mapGetters, mapState } from 'vuex'
import { has, isNil, isEmpty } from 'ramda'
import { required } from 'vuelidate/lib/validators'

import PURCHASE_ORDER_ITEM_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderItemEvents'
import { returnTypes } from '@/config/returnProductTypes'
import { testMode } from '@/config/env'

import { getTranslatedText, getTruncatedText } from '@/tools/data'
import {
  formatNumberFromDb,
  moneyTextFieldCountryConfig,
} from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import {
  setDefaultValidators,
  setMoneyValidator,
} from '@/components/PurchasesView/ReturnProductDialog/ReturnProductForm/tools'
import FormattedText from '@/components/shared/FormattedText'
import MoneyTextField from '@/components/shared/MoneyTextField'
import ProductAutoComplete from '@/components/shared/ProductAutoComplete'

export default {
  name: 'ProductToReturnForm',
  components: { FormattedText, MoneyTextField, ProductAutoComplete },
  props: {
    inputs: {
      type: Object,
      required: true,
    },
    productType: {
      type: String,
      required: true,
    },
  },
  data() {
    return {
      moneyInputsConfig: this.getMoneyInputsConfig(),
    }
  },
  computed: {
    ...mapState('vendorsView', ['selectedVendor']),
    ...mapGetters('products', ['getOnlyStockedProducts']),
    isProductSelected() {
      return !isNil(this.inputs.productToReturn)
    },
  },
  methods: {
    getTranslatedText,
    getTruncatedText,
    customFilter(item, queryText) {
      return (
        item.name.toLowerCase().indexOf(queryText.toLowerCase()) > -1 ||
        item.upc.toLowerCase().indexOf(queryText.toLowerCase()) > -1
      )
    },
    getMoneyInputsConfig() {
      return moneyTextFieldCountryConfig() || { precision: 2 }
    },
    getInitialFocus() {
      if (testMode) return
      const unitsInput = this.$refs.unitsToReturn.$el.querySelector('input')
      setTimeout(() => {
        unitsInput.select()
      }, 200)
    },
    getCostLabel() {
      switch (this.productType) {
        case 'isPieceProduct':
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costPiece'
          )
        case 'isByWeightProduct':
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costUnit'
          )
        case 'isOpenProductPackage':
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costPackage'
          )
        default:
          return this.getTranslatedText(
            'purchaseView.byWeightSelector.costPiece'
          )
      }
    },
    onValidateFields(input) {
      const errors = []
      if (
        !Object.keys(this.$v.inputs).includes(input) ||
        !this.$v.inputs[input].$dirty
      )
        return errors
      has('required')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].required &&
        errors.push(this.getTranslatedText('salesView.form.errors.empty'))
      has('minValue')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].minValue &&
        errors.push(this.getTranslatedText('salesView.form.errors.minValue'))
      has('maxValue')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].maxValue &&
        errors.push(this.getTranslatedText('salesView.form.errors.maxValue'))
      has('maxDecimals')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].maxDecimals &&
        errors.push(this.getTranslatedText('salesView.form.errors.maxValue'))
      has('integer')(this.$v.inputs[input]) &&
        !this.$v.inputs[input].integer &&
        errors.push(this.getTranslatedText('salesView.form.errors.decimal'))
      return errors
    },
    calculateDiscount() {
      if (
        isNil(this.inputs.productToReturn) ||
        isEmpty(this.inputs.unitsToReturn)
      )
        return
      this.inputs.amountToDiscount =
        this.inputs.productToReturn?.isGramaje === 1
          ? (this.inputs.unitsToReturn / 1000) * this.inputs.costToReturn
          : this.inputs.unitsToReturn * this.inputs.costToReturn
    },
    onUnitsToReturn() {
      if (this.inputs.currentFocus !== 'unitsToReturn') return
      this.calculateDiscount()
    },
    onCostToReturn() {
      if (this.inputs.currentFocus !== 'costToReturn') return
      this.calculateDiscount()
    },
    async purchaseOrdenItemListener(event, payload) {
      const events = PURCHASE_ORDER_ITEM_DB_API_EVENTS.events
      const replies = {
        [events.getLastPurchaseOrderItemCost.replies.success]: () => {
          this.inputs.costToReturn = !isNil(payload.data.unitCost)
            ? formatNumberFromDb(payload.data.unitCost)
            : formatNumberFromDb(
                Number.isFinite(this.inputs.productToReturn.cost)
                  ? this.inputs.productToReturn.cost
                  : 0
              )
          if (payload.data.unitCost <= 0) {
            this.$v.inputs.costToReturn.$touch()
          }
          this.calculateDiscount()
          this.getInitialFocus()
        },
        [events.getLastPurchaseOrderItemCost.replies.error]: () => {
          this.inputs.costToReturn = formatNumberFromDb(
            Number.isFinite(this.inputs.productToReturn.cost)
              ? this.inputs.productToReturn.cost
              : 0
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  watch: {
    'inputs.productToReturn': function() {
      this.$refs.productToReturn.blur()
      if (isNil(this.inputs.productToReturn)) {
        this.inputs.costToReturn = 0
        this.inputs.unitsToReturn = 0
        this.inputs.amountToDiscount = 0
        this.inputs.productToChange = null
        this.inputs.costToChange = 0
        this.inputs.unitsToChange = 0
        this.inputs.returnType = returnTypes.DISCOUNT
        this.inputs.currentFocus = ''
        return
      }
      rendererEventsService.send(PURCHASE_ORDER_ITEM_DB_API_EVENTS.channel, {
        event:
          PURCHASE_ORDER_ITEM_DB_API_EVENTS.events.getLastPurchaseOrderItemCost
            .name,
        data: {
          productId: this.inputs.productToReturn.id,
          vendorId: this.selectedVendor.id,
          showProductTriangulationDialog: false,
        },
      })
    },
  },
  validations() {
    const maxStock = isNil(this.inputs.productToReturn)
      ? 0
      : this.productType === 'isOpenProductPackage'
      ? this.inputs.productToReturn.quantity /
        this.inputs.productToReturn.factor
      : this.inputs.productToReturn.quantity
    return {
      inputs: {
        productToReturn: {
          required,
        },
        unitsToReturn: setDefaultValidators(maxStock),
        costToReturn: setMoneyValidator(1000000, 2),
      },
    }
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      PURCHASE_ORDER_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseOrdenItemListener
    )
  },
  mounted() {
    if (!isNil(this.inputs.productToReturn)) this.getInitialFocus()
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      PURCHASE_ORDER_ITEM_DB_API_EVENTS.replyChannel,
      this.purchaseOrdenItemListener
    )
  },
}
</script>

<style lang="scss" scoped>
.custom-text-field {
  border-radius: 12px;
}
</style>
