<template>
  <div>
    <p
      class="text-body-1"
      v-html="getTranslatedText('promotion.ticket.atCost.info')"
    />
    <v-alert
      v-if="hasSomeCustomPromotion"
      dense
      color="secondary"
      text
      icon="mdi-alert-outline"
      class="mb-0"
    >
      {{ getTranslatedText('customPromotionsView.inSale.ticketAtCostAlert') }}
    </v-alert>
  </div>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

export default {
  name: 'TicketToCost',
  props: {
    ticket: {
      type: Object,
      required: true,
    },
  },
  computed: {
    hasSomeCustomPromotion() {
      return (
        this.ticket.promotions.length > 0 ||
        this.ticket.items.some(item => item.promotions.length > 0)
      )
    },
  },
  methods: { getTranslatedText },
}
</script>
