<template>
  <v-tooltip right max-width="300">
    <template v-slot:activator="{ on, attrs }">
      <v-chip v-bind="attrs" v-on="on" label :color="color" class="chip-status">
        <v-icon left>{{ icon }}</v-icon>
        {{ textTooltip }}
      </v-chip>
    </template>
    <span>
      <ul>
        <li>{{ getTranslatedText('byWeightScale.info.port') }}</li>
        <li>{{ getTranslatedText('byWeightScale.info.detected') }}</li>
      </ul>
    </span>
  </v-tooltip>
</template>

<script>
import WEIGHT_SCALE_EVENTS from '@/config/events/weightScaleEvents'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

export default {
  name: 'WeightScaleStatus',
  data() {
    return {
      status: 'disconnect',
      showTooltip: false,
    }
  },
  computed: {
    icon() {
      if (this.status === 'error') return 'mdi-scale-off'
      return 'mdi-scale'
    },
    color() {
      if (this.status === 'error') return 'error lighten-2'
      if (this.status === 'connected') return 'primary lighten-4'
      return 'grey lighten-2'
    },
    textTooltip() {
      let text = this.getTranslatedText('byWeightScale.disconnect')
      if (this.status === 'error') {
        text = this.getTranslatedText('byWeightScale.error')
      }
      if (this.status === 'connected') {
        text = this.getTranslatedText('byWeightScale.connect')
      }
      this.displayTooltip()
      return text
    },
  },
  methods: {
    getTranslatedText,
    weightScaleStatusListener(event, payload) {
      const replies = {
        [WEIGHT_SCALE_EVENTS.events.connection.replies.success]: () => {
          this.status = 'connected'
        },
        [WEIGHT_SCALE_EVENTS.events.connection.replies.error]: () => {
          this.status = 'error'
        },
        [WEIGHT_SCALE_EVENTS.events.stop.replies.success]: () => {
          this.status = 'disconnect'
        },
        [WEIGHT_SCALE_EVENTS.events.stop.replies.error]: () => {
          this.status = 'disconnect'
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    displayTooltip() {
      setTimeout(() => {
        this.showTooltip = true
      }, 300)
      setTimeout(() => {
        this.showTooltip = false
      }, 2100)
    },
  },
  beforeMount() {
    rendererEventsService.subscribe(
      WEIGHT_SCALE_EVENTS.replyChannel,
      this.weightScaleStatusListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      WEIGHT_SCALE_EVENTS.replyChannel,
      this.weightScaleStatusListener
    )
  },
}
</script>
<style scoped lang="scss">
.chip-status {
  color: var(--v-textPrimary-base) !important;
}
</style>
