const setConfig = (state, methods) => ({
  state,
  methods,
  maxWidgetsOpened: 2,
  widgets: getWidgetsByProductType(state.selectedProduct, methods),
})

const getWidgetsByProductType = (product, methods) => {
  let widgetsList = [
    {
      id: 'stockDetails',
      type: 'StockDetails',
      onClickDropDown: () => methods.toggleWidgetDropDown('stockDetails'),
    },
    {
      id: 'mainDetails',
      type: 'MainDetails',
      onClickDropDown: () => methods.toggleWidgetDropDown('mainDetails'),
    },
  ]
  if (product.factor > 1) {
    widgetsList.splice(1, 0, {
      id: 'packageDetails',
      type: 'PackageDetails',
      onClickDropDown: () => methods.toggleWidgetDropDown('packageDetails'),
    })
  }
  return widgetsList
}

export default setConfig
