const config = (state, methods) => ({
  state,
  methods,
  groupClass: 'pr-4',
  groups: [
    {
      id: 'utility-button-01',
      controls: [
        {
          id: 'fordward-button-control',
          type: 'button',
          icon: 'mdi-arrow-left-thick',
          group: 'utility',
          color: 'primary',
          onClick: () => methods.backward(),
        },
      ],
    },
    {
      id: 'filters-group-01',
      controls: [
        {
          id: 'search-control',
          type: 'input',
          label: 'productsView.toolbar.searchField.label',
          placeholder: 'productsView.toolbar.searchField.placeholder',
          icon: 'mdi-magnify',
          backgroundColor: 'cardBackgroundSecondary',
          color: 'salesPrimary',
          ref: 'purchases-input-search',
          group: 'search',
          onChange: value => methods.onChange(value),
          onEnter: value => methods.onEnter(value),
          onClick: resetSelector => {
            state.isScannerActive === true
              ? methods.updateScannerStatus()
              : null
            resetSelector()
            methods.setGroup('search')
            methods.setSelectedSuperCategories([])
          },
        },
      ],
    },
    {
      id: 'filters-group-02',
      controls: [
        {
          id: 'all-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.all',
          icon: 'mdi-view-module',
          group: 'all',
          color:
            state.filters.group === 'all' ? 'accent lighten-1' : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('all', methods, resetSelector, resetSearchTerm)
          },
        },
        {
          id: 'prices-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.generics',
          icon: 'mdi-calculator',
          group: 'generics',
          color:
            state.filters.group === 'generics'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('generics', methods, resetSelector, resetSearchTerm)
          },
        },
        {
          id: 'weight-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.byWeight',
          icon: 'mdi-weight',
          group: 'byWeight',
          color:
            state.filters.group === 'byWeight'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('byWeight', methods, resetSelector, resetSearchTerm)
          },
        },
        {
          id: 'favorites-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.favorites',
          icon: 'mdi-cards-heart',
          group: 'favorites',
          color:
            state.filters.group === 'favorites'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('favorites', methods, resetSelector, resetSearchTerm)
          },
        },
        {
          id: 'vendor-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.vendor',
          icon: 'mdi-truck',
          group: 'vendor',
          color:
            state.filters.group === 'vendor'
              ? 'accent lighten-1'
              : 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('vendor', methods, resetSelector, resetSearchTerm)
          },
        },
      ],
    },
    {
      id: 'filters-group-03',
      controls: [
        {
          id: 'superCategories-select-control',
          type: 'select',
          label: 'productsView.toolbar.selectCategoryField.label',
          group: 'superCategories',
          items: state.data.superCategories,
          stringValueSelected:
            'productsView.toolbar.selectCategoryField.categoriesSelected',
          backgroundColor: 'cardBackgroundSecondary',
          limit: 3,
          width: 285,
          onChange: data => methods.setSelectedSuperCategories(data),
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect(
              'superCategories',
              methods,
              resetSelector,
              resetSearchTerm
            )
          },
        },
      ],
    },
    {
      id: 'filters-group-04',
      controls: [
        {
          id: 'clear-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.clear',
          icon: 'mdi-close-circle',
          group: 'clear',
          color: 'salesPrimary',
          onClick: (resetSelector, resetSearchTerm) => {
            buttonEffect('clear', methods, resetSelector, resetSearchTerm)
          },
        },
      ],
    },
  ],
})

const buttonEffect = (group, methods, resetSelector, resetSearchTerm) => {
  group === 'clear' ? methods.setGroup('all') : methods.setGroup(group)
  resetSelector()
  resetSearchTerm()
  methods.setSearchTerm(null)
  methods.setSelectedSuperCategories([])
  methods.resetScannerStatus(group)
}

export default config
