const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.dialog.isOpen,
    icon: 'mdi-weight',
    title: 'salesView.byWeightProductDialog.title',
    messages: ['salesView.byWeightProductDialog.message'],
    extraValuesMessages: [state.selectedByWeightCategory.name] || '',
    persistent: true,
    titleBackground: '#white',
    titleColor: 'textPrimary',
    acceptButtonText: 'salesView.byWeightProductDialog.acceptButtonText',
    isAcceptButtonDisabled: state.dialog.isAcceptButtonDisabled,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    maxWidth: 860,
    height: 760,
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Purchases',
        screen: 'ByWeightProductDialog',
        name: 'Cancel',
      })
      methods.dialog.onCloseDialog()
    },
    onClickAccept: () => methods.dialog.onSubmitForm(),
  },
})

export default setConfig
