<template>
  <v-col cols="9">
    <v-row no-gutters>
      <v-col cols="8" class="pr-1">
        <DiscountPromotionForm
          ref="DiscountPromotionForm"
          :form="componentConfig.formData"
        />
      </v-col>
      <TotalWithPromotion :inputs="inputs" class="pl-4" />
    </v-row>
  </v-col>
</template>

<script>
import { mapState } from 'vuex'

import { formatNumberToDb } from '@/tools/numbersFormat'
import { discountTypes } from '@/tools/promotions'

import DiscountPromotionForm from '@/components/shared/DiscountPromotionForm'
import TotalWithPromotion from '@/components/PurchasesView/ProductTriangulationDialog/ProductTriangulationForm/PromotionsForm/Promotions/GiftProductsForm'
import setConfig from '@/components/PurchasesView/ProductTriangulationDialog/ProductTriangulationForm/PromotionsForm/Promotions/DiscountConfig'

import productTriangulation from '@/mixins/purchases/productTriangulation'

export default {
  name: 'DiscountForm',
  components: { DiscountPromotionForm, TotalWithPromotion },
  props: {
    inputs: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      totalWithIVA: 0,
    }
  },
  computed: {
    ...mapState('purchasesView', ['selectedProduct']),
    componentConfig() {
      return setConfig(
        {
          inputs: this.inputs,
          v: this.$v,
          cost: formatNumberToDb(this.totalWithIVA),
        },
        {}
      )
    },
  },
  methods: {
    setFormValidators() {
      const validations = {
        inputs: {
          discount: this.getDiscountRule(
            this.inputs.type,
            formatNumberToDb(this.totalWithIVA)
          ),
        },
      }
      return validations
    },
    updateTotalWithDiscount(discount) {
      this.totalWithIVA = this.getTotal(
        this.selectedProduct.product.isGramaje,
        this.inputs.quantity,
        this.inputs.cost,
        this.inputs.tax
      )
      this.inputs.totalWithDiscount = discountTypes.isDiscountPerAmount(
        this.inputs.type
      )
        ? this.totalWithIVA - discount
        : this.totalWithIVA - (this.totalWithIVA * discount) / 100
    },
  },
  watch: {
    'inputs.discount': function(discount) {
      this.updateTotalWithDiscount(discount)
    },
    'inputs.total': function() {
      this.updateTotalWithDiscount(this.inputs.discount)
    },
  },
  mixins: [productTriangulation],
  validations() {
    return this.setFormValidators()
  },
  mounted() {
    this.totalWithIVA = this.getTotal(
      this.selectedProduct.product.isGramaje,
      this.inputs.quantity,
      this.inputs.cost,
      this.inputs.tax
    )
    this.updateTotalWithDiscount(this.inputs.discount)
  },
}
</script>
