const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'purchaseView.overCreditLimitDialog.title',
    messages: ['purchaseView.overCreditLimitDialog.message'],
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    height: 235,
    maxWidth: 500,
    onClickCancel: () => {
      methods.closeDialog()
    },
    onClickAccept: () => {
      methods.closeDialog()
      methods.payPurchase()
    },
  },
})

export default setConfig
